/* 令和7年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r07.committeeSessions.push(...[{"id":"r07-20250702-21","meetingId":"r07-cm07","date":"2025年7月2日","dateIso":"2025-07-02","committee":"子ども若者支援・共生社会推進特別委員会","time":"午前１０時００分～午前１１時４８分","status":"正式会議録","sourceType":"formal","overview":"子ども若者支援・共生社会推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を33件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"鈴木委員","kind":"質問","question":"令和６年のところを見ると、０歳児は令和６年に出生した人数だと思うのですけれども、１歳児のところは令和５年のときに出生した３,２１１人になる。例えば、４歳児だと４８０人、３歳児だと４６２人減っている状況になりますが、これは子どもが生まれた後に転出しているので減っているということで捉えているのか、そこのところをどう区としては分析されているのか、その点を伺いたいと思います。","respondent":"芝野保育入園調整課長","answer":"推計値ですが、こちらは企画課のほうで取りまとめて人口推計を出しておりまして、それに基づいてこども計画の計画もこちらの数字を使わせていただき、今回の特別委員会の資料にも使わせていただいているですので。","voiceIndex":8,"id":"exchange-001"},{"speaker":"鈴木委員","kind":"質問","question":"続いて２ページのところで伺いたいのですけれども、２ページのところで下の図表を見ると、幼稚園に通われる子どもがこの１３年ぐらいの間で半分以下に減っているのだなというのが、改めてこんな状況まで来ているのかというふうに思ったのですが、こういうふうな形で幼稚園を希望する入園の子どもが減っているというのは、区としてはなぜ減っているというふうに分析しているのか。","respondent":"芝野保育入園調整課長、佐藤保育事業担当課長","answer":"私のほうから、何点かご質問をお答えさせていただきたいと思います。こうした考えに伴いまして、今までも様々な補助を実施してございまして。今回から４万円までの保育料の助成がスタートしておりますので、実質上は保育料は完全無償化になっているかなというような状況です。","voiceIndex":10,"id":"exchange-002"},{"speaker":"鈴木委員","kind":"質問","question":"ありがとうございました。４ページの下の図のところで、一番下の列に2)－1)の数字が書かれているのですが、これはこども誰でも通園制度の分ということで考えていいのでしょうか。それで、こども誰でも通園制度の需要というのは、区としてはどういうふうに見込んでいるのか、その点についても伺います。","respondent":"佐藤保育事業担当課長、芝野保育入園調整課長","answer":"現在、区といたしましては、来年度から法的に実施しなければならなくなりますこども誰でも通園に向けた調査というのを実施していますが、先行的事業といたしまして都の制度を活用して、令和５年度から区としては広報やＳＮＳ。私のほうからは、下の表の一番下2)－1)、こちらの数字の考え方についてご説明させていただきたいと思います。","voiceIndex":14,"id":"exchange-003"},{"speaker":"澤田委員","kind":"質問・要望","question":"５ページの下段のところについて。すくわくプログラムについて記載されていると思うのですが、各園のすくわくのテーマについてですけれども、このテーマについてはどのようにして決められているのかなというのを教えていただきたいところです。すくわくプログラムのポータルサイトなどを参考に、それぞれの園で決めているのでしょうか。教えてください。","respondent":"酒川指導課長","answer":"すくわくプログラムは東京都の補助金を使ってやっているものですが、テーマの例として色、泥遊び、音、絵本、自然、光、こういったものが示されておりまして、施設環境ですとか子どもたちの実態ですとか、指導の狙いに合わせて各園で設定しております。","voiceIndex":17,"id":"exchange-004"},{"speaker":"澤田委員","kind":"意見","question":"大きなテーマは東京都のプログラムの中から流れは決まっていて、その中から各園が皆さんお考えになって決められているということなのですね。","respondent":"酒川指導課長","answer":"おっしゃるとおりです。","voiceIndex":19,"id":"exchange-005"},{"speaker":"澤田委員","kind":"質問・要望","question":"巡回相談では、教員の皆さんへの助言指導のほか、保護者の皆さんへの相談も行われていると理解していますが、その理解で合っていますでしょうか。２７回の巡回の中で、保護者からの相談というのはその中の割合でどれくらいあるというか、基本的には先生のご相談なのか、それとも割と保護者からのご相談なんかもあるのかなというところを教えていただきたいです。お願いいたします。","respondent":"染谷保育施設運営課長","answer":"そのほか、区では育児相談会ということで、保護者の方を対象とした事業を実施しておりまして、その中で実際に通われている保護者の方のいろいろな子育てに関するお悩みなどをお聞きするというような事業も実施しております。","voiceIndex":21,"id":"exchange-006"},{"speaker":"澤田委員","kind":"意見","question":"なるほど。その辺りについて、お聞かせいただければと思います。","respondent":"染谷保育施設運営課長","answer":"三者での相談の機会というところにつきましては、特別支援保育は非常に重要なものであると認識しておりますので。","voiceIndex":23,"id":"exchange-007"},{"speaker":"澤田委員","kind":"質問","question":"最後に、６ページの預かり保育についてお伺いしたいのですが、幼保一体型の施設では１８時半、もしくは１９時半まで預かり保育をやっていらっしゃると思いますけれども、城南幼稚園と浜川幼稚園というのは単独園２園だけですが、浜川幼稚園は幼保一体と同じように１８時半までとなっており、城南幼稚園だけ１７時となっていますけれども。","respondent":"染谷保育施設運営課長","answer":"城南幼稚園の１７時の時間の設定については、今後まずは単独幼稚園がどういうふうになっていくかというところも含めて、この時間帯の設定を変更していくかどうかというところの検討をしている過程というところでして、この１７時の時間設定になっているという状況です。","voiceIndex":25,"id":"exchange-008"},{"speaker":"澤田委員","kind":"質問・要望","question":"どうぞよろしくお願いいたします。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":27,"id":"exchange-009"},{"speaker":"西村委員","kind":"質問・要望","question":"説明、ありがとうあります。今、単独園のお話があったのですけれども、城南、浜川で、伊藤幼稚園は閉園が決定しておりまして、今後単独園はどうしていくのかという今後の在り方みたいなものについてお話しいただける部分や、もしお考えがあればお聞かせいただきたいなというふうに思っております。それが１点です。","respondent":"芝野保育入園調整課長、酒川指導課長","answer":"２番目の施設活用の方向性です。こちらのほうは、今回特別委員会を設置していただきましたので、委員の皆様のご意見を伺いながら将来像を検討していきたいというふうに考えております。区立幼稚園のことになりますけれども、やはり区立幼稚園を選ばれる保護者というのは教育、それから教育の質、そういったものに重きを置いているご家庭なのかなというふうに思っております。","voiceIndex":29,"id":"exchange-010"},{"speaker":"西村委員","kind":"質問","question":"今回、これを取り上げするに至って、２３区の中での幼稚園の需要が維持されている自治体があるのではないかと思って調べてみたのですけれども、なかなか地域差があるので一概には言えないのですが、例えば江東区でしたら人口も違いますけれども区立２０園と私立が１２園ありまして、区立幼稚園の存在感が大きいというようなことを伺ったりします。","respondent":"酒川指導課長、佐藤保育事業担当課長","answer":"なので、そういったところを支援できないかなというふうに思っておりますが、今発信は各園が自由にできる状況にないというところが課題かなと考えています。私立幼稚園に入園をしていただくような方を増やしていく魅力の発信事業につきましては、そのような取組に対する補助というのを令和５年度で実施しており、例えば見やすいホームページであったり。","voiceIndex":32,"id":"exchange-011"},{"speaker":"西村委員","kind":"質問・要望","question":"本当に難しいなとこのテーマを考えるたびに思うのですけれども、やはり保護者の方々に幼稚園は何なのかというか、保育園との違い、暮らしとか保育ということと幼稚園が教育施設だと、初等科教育につながるものだということの違いがどんどんやはり伝わりづらくなっているなというのは感じますので、伝わっていくように、魅力の発信と言ったら簡単に聞こえてしまうのですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":35,"id":"exchange-012"},{"speaker":"せらく委員","kind":"質問・要望","question":"それで、区立幼稚園の、例えば城南幼稚園ですと４歳児の定員が３０名ということで、現在令和７年で１３名が入っていて充足率が４３.３％で、仮に定員いっぱいだったときにはクラス数というのは何クラスになるか教えていただきたいと思います。現在のクラス数も分かればお願いいたします。","respondent":"染谷保育施設運営課長","answer":"学級数につきましては、１学級となっております。","voiceIndex":36,"id":"exchange-013"},{"speaker":"せらく委員","kind":"質問","question":"定員いっぱいでも、現在の半分以下でもクラス数は１学級ということで、分かりました。施設の有効活用についても伺っていきたいなと思ったのですけれども、学級は変わらないということで、単独幼稚園の幼保一体施設への転換の今後の可能性とかは、何か具体的な計画だとか条件がそろえばというところがあればお聞きしたいです。","respondent":"芝野保育入園調整課長","answer":"単独園の幼保一体施設への転用ですが、施設のスペースもございまして、なかなか難しいかなと思います。今は、幼保一体施設を６園つくっておりますので、こちらのほうはしっかりと運営をしていきたいと考えております。","voiceIndex":38,"id":"exchange-014"},{"speaker":"大倉委員","kind":"質問・要望","question":"保育園だけで足りているというふうにこれだとなるのですか。令和２年だと、一応区としてはずっと待機児童はゼロだということで言っているかと思うのですけれども、そうすると受け入れ切れてしまうよねというところも考えられるのかなということも踏まえて、どのように考えているのかというのは伺えればなと考えています。実際、品川区の私立幼稚園への補助金とかはどのくらいかかっているのでしょうか。","respondent":"芝野保育入園調整課長、佐藤保育事業担当課長","answer":"推計値は令和７年度以降緩やかに増加していくということで、その受皿ですが、先ほども少し申し上げましたように保護者の方のニーズというのは様々、多様化しておりまして、保育園に預けたい方、引き続き幼稚園に預けたい方。ですので、実際に今年度プレの事業で実施されていただいている幼稚園が２園あるのですけれども、基本的には満３歳と言われるような２歳児で、３歳になられたばかりの方というのが対象というふうになってありますので。","voiceIndex":40,"id":"exchange-015"},{"speaker":"つる委員","kind":"意見","question":"現状は、最初は１０園だか１１園が誰でも通園を東京都の事業を使っていて、今年度は幾つでしたか。それと、事業者とか園としての存続をどういうふうに区として支援するか、ここはどうしても私立のところといろいろな制度が、特に保育園とのジレンマもあるかもしれないですけれども、まさにその辺を含めて誰でも通園と関連して私立幼稚園の在り方について、区の今の考えをお聞かせください。","respondent":"佐藤保育事業担当課長","answer":"私立幼稚園の経営の支援に誰でも通園がなるのかですが、昨年度２園の幼稚園でご利用いただいてございまして、その方たちとお話しすると当然空きの定員というのを活用した事業ですので、非常に経営支援にはなっているというふうにお話を聞いているところですが。","voiceIndex":45,"id":"exchange-016"},{"speaker":"つる委員","kind":"確認","question":"このこども計画の教育、保育の量の見込みの確保予算の中の各年齢別教育・保育量の見込みの表を見すると、１０９ページです。在宅子育て等という表があって、１号、２号、３号と在宅子育てのところの０から２歳というのが主な誰でも通園の分母というところになりますけれども、そこをまず議論のスタートの土台として確認させてください。","respondent":"佐藤保育事業担当課長","answer":"誰でも通園制度はご利用される方が保育園、幼稚園等に通われていない未就園児ですので、委員にお話しいただきましたように、在宅子育て等に係る表のお子様たちが主な対象となるというふうに考えます。","voiceIndex":47,"id":"exchange-017"},{"speaker":"つる委員","kind":"質問","question":"０から２歳がそれで、今年度については４,０６７名ですけれども、その上でこれまで大体３割ぐらいと言われていて若干数字が減ってきて、これは就労家庭が増えてきているのかなというところだと思うのですが、下のほうに認可外保育施設の利用を含むとありますけれども、それぞれの年齢別でどういう施設を日常的に使われているのかというのは、分かれば教えてください。もちろん在宅子育て等の方たちです。","respondent":"佐藤保育事業担当課長","answer":"在宅で子育てをされていらっしゃる方がどのような施設とつながりがあるのかについてですが、基本的にはオアシスルームとかポップンルームとかそういった施設、または児童センターなどをご利用いただけているのではないかなというふうに考えてございまして。","voiceIndex":49,"id":"exchange-018"},{"speaker":"つる委員","kind":"質問","question":"そうすると、例えば３、４、５歳も基本的にはパーセンテージは全体の就学前の人口からいくと１０％くらいなのかなと思うのですけれども、そのぐらいのお子さんたちというのは１号、２号、３号とは別なので、全く保育園、幼稚園に日常的に通うということはせずに小学校に上がるという、そもそもですけれども、そこを教えてください。","respondent":"佐藤保育事業担当課長","answer":"こちらに記載されている約１０％程度のお子さんになりますけれども、こちらは認可外保育施設が含まれてありますので、例えばインターナショナルスクールであったり。","voiceIndex":51,"id":"exchange-019"},{"speaker":"つる委員","kind":"質問","question":"１回学校に在籍してというようなことがあって、そこは少し別の話ですけれども、そういう意味では今言ったように就学前にインターナショナルスクールみたいなところに行っていて、区内の区立の小学校に上がっているお子さんのその辺の細かい把握というのは分かるのでしょうか。","respondent":"石井学務課長","answer":"先ほど委員がおっしゃったとおり、インターナショナルスクールの学籍の問題についてはもろもろ議論されているところではありますけれども、そういったところとは別のところでそういった課題があることは認識しています。","voiceIndex":53,"id":"exchange-020"},{"speaker":"つる委員","kind":"質問","question":"そうすると、今日いただいている資料の中でも保幼小のジョイント事業なんかがあって、これは私立の保育園、幼稚園、区立の幼稚園、保育園、それから認証と、どこまでこれが保幼小のジョイント事業の対象になっているのか。事務事業を見ると分からなかったので、それを教えてください。","respondent":"染谷保育施設運営課長","answer":"連携の対象といたしましては、公立の保育園、幼稚園、それから私立の保育園、幼稚園、そして、公設民営の保育園が実際に令和６年度の実績において保幼小連携ジョイント事業のほうを実施しているという状況です。","voiceIndex":55,"id":"exchange-021"},{"speaker":"つる委員","kind":"質問","question":"保育園とか幼稚園の話というのは、どうしても保護者の状況だと思うのですけれども、保護者ないしその子どもが置かれている家庭環境において非常に大きく左右されてきました。この辺りは、区立の幼稚園、私立の幼稚園の在り方も含めて、どういうふうにしてまさにあることが子どもたちのそういったよきことにつながっていくのか、もし考えがあれば教えてください。","respondent":"佐藤子ども未来部長","answer":"我々といたしましても保幼小ジョイント事業の拡大というのは非常に大きな課題だと捉えておりますので、今は様々改善に向けて検討してまいりたいと考えています。","voiceIndex":57,"id":"exchange-022"},{"speaker":"つる委員","kind":"質問・要望","question":"けれども、まさに在り方としてその辺の選択はあくまでも自由ですが、減少傾向になっていったときに、でも中核ですからそれは存続していただかなければいけないし、この辺のバランスというのをまさにどうやっていくのか教えてください。","respondent":"佐藤保育事業担当課長","answer":"私立幼稚園に対する補助についてですけれども、まさに今委員にお話しいただきましたように幼児教育の中核を担っていただいている施設ですので、冒頭よりお話しさせていただいている保護者の方が選択できるような環境というのを整備していかなければならないということで。","voiceIndex":59,"id":"exchange-023"},{"speaker":"つる委員","kind":"質問・要望","question":"今日は区立、私立幼稚園の在り方ということで、４回あると先ほど冒頭でご説明があったのですけれども、今日の議論というのはどこまでやっていいかとか仕切りがあると思うのですが、一応連続で設定いただいているので、それに段階を応じて質疑をしたいなと思っているのですけれども、その辺を議事進行的に教えていただきたいです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":61,"id":"exchange-024"},{"speaker":"つる委員","kind":"提案","question":"ありがとうございました。では、在り方の中にもすごく項目がたくさんあるのですが、先ほどの答弁の中でも委員からまさにこの特別委員会が設定されて、委員から在り方についてはご提案いただきたいというような趣旨の話もあって、そういう意味ではまさに今日の設定の中でどこまでかなと思っています。どういう世帯層の人たちが在宅子育てをしているのか。","respondent":"芝野保育入園調整課長","answer":"ですので、収入状況のほうは把握していないのが現状です。","voiceIndex":63,"id":"exchange-025"},{"speaker":"つる委員","kind":"質問","question":"傾向として在宅で子育てをするという世帯というのは、どういう世帯状況の方が多いのでしょうか。","respondent":"芝野保育入園調整課長","answer":"今の話と繰り返しになってしまうところではありますが、その状況についても把握していないところではありますので、経済的な余裕があっておうちのほうでしっかり見られている方もいらっしゃると思いますし、そうでないいろいろな事情があるとは思いますけれども。","voiceIndex":65,"id":"exchange-026"},{"speaker":"つる委員","kind":"質問・要望","question":"そういったことをしないと社会が立ち行かない、社会保障も成り立たないよねとなってきていて、だけれどもその辺の社会が求める部分と子どもを育てる環境に置かれている保護者の状況というのが今は数字で言うと３割弱ぐらいなんですけれども、その辺の中のニーズというか、補足というのは先ほどのご答弁でもあったオアシスルームとかポップンルームとかを利用されていますとありましたが。","respondent":"芝野保育入園調整課長","answer":"在宅で子育てをされている方の情報はなかなか補足する、把握する手段というのは持ち合わせていないところですが、今委員のほうからお話がありましたオアシスルームとかポップンルームとか、いろいろな在宅子育ての方がお使いになれるような施策を展開しておりますので。","voiceIndex":67,"id":"exchange-027"},{"speaker":"つる委員","kind":"質問","question":"でも、品川区はこの間におむつの宅配だとかをやって、月齢の段階だとそういった取組で定期的に声を聞くタイミングというのはものの数秒だったり１分もあるのかとかあるのかもしれないですけれども、そういうこととか、オアシスルームを利用する機会とか児童センターもそうですが、そういった約３割あるニーズと。","respondent":"佐藤子ども未来部長","answer":"区といたしましてはＥＢＰＭの観点で施策をしっかり検討しなさいという指示も出ておりますので、そういった声を聞きながら今後のお子さんの状況でありましたり、どういった施設に預ける希望があるのか、もしくはどういう施策を拡充すべきというものをしっかりと把握して。","voiceIndex":69,"id":"exchange-028"},{"speaker":"つる委員","kind":"質問・要望","question":"いろいろな事業でポイント的に聞いていただく機会というのはあったというのは今のご答弁にもあって、あとは恐らく結局最終的には一人一人に寄ってしまうのかもしれないのですけれども、新しい名前で今また展開いただいている子育て情報のアプリとか、そういったところに投げていただいている情報とか話とか悩みとか苦しみとか希望とか要望とかというのはあると思いますが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":71,"id":"exchange-029"},{"speaker":"大倉委員","kind":"質問・要望","question":"誰でも通園のところで、今もお話がいろいろあって、１８４の園が利用されていてというところで言うと、どういった課題があったのかとかという把握はもちろんされていると思いますけれども、やはり一方で余裕があって受け入れていくとなると、人数がそれだけ負担が、負担と言うか、１人見る数が増えるというところで保育の質とかとよく言われるとは思うのですが。","respondent":"佐藤保育事業担当課長、染谷保育施設運営課長、酒川指導課長","answer":"これは、事業実施を通じた好事例なんかを保育園長会などを通じて各事業者様にお伝えすることによって、参加していただける事業者を増やしているですので。学校のほうで受入れというお話がまさにあって、そこが一つ課題なのかなという中で、ある学校からは一定の学校で行う授業のほうに複数の園を一度に招くとか。","voiceIndex":72,"id":"exchange-030"},{"speaker":"澤田委員","kind":"確認","question":"先ほど１つ聞き忘れてしまったこと、聞き漏らしてしまったことがありまして、私立幼稚園の取組の中でですけれども、特別支援教育・巡回相談というのをやっていらっしゃいますが、介助員の配置というのは区立ではありますけれども、私立ではこちらはやっていないのですよねという確認をまずはさせていただいてもいいでしょうか。","respondent":"佐藤保育事業担当課長","answer":"介助員の配置につきましては、私立園ですので各園において、その状況において実施されているものであるというふうに考えてあります。区はそういった取組を支援するために、特別な支援が必要なお子様をお預かりいただいた園に対しまして、補助を実施しているというものがあります。","voiceIndex":78,"id":"exchange-031"},{"speaker":"ゆきた副委員長","kind":"質問","question":"幼稚園の預かり保育は、国の制度に基づく法令なので難しいところもあると思うのですが、預かり保育について就労とか妊娠とか、病気、介護、求職活動だけではなくて、孤独、負担感という視点で柔軟な対応があればなと、そういうふうに思うのですけれども、そこの現状をお聞きできればと思います。","respondent":"染谷保育施設運営課長","answer":"預かり保育につきましては、現状台場幼稚園においては就労によらず子育て支援型預かり保育というようなことを実施している部分はありますけれども。","voiceIndex":81,"id":"exchange-032"},{"speaker":"ゆきた副委員長","kind":"質問・要望","question":"就労だけではなくて、診断書があってその状況に応じて園によって柔軟な対応というのはあると思うのですけれども、そこは予防的な観点とか幼稚園の関わっているお子さんの状況とかを見ながら、柔軟な対応をしていただければと思いますので、こちらは要望でお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":83,"id":"exchange-033"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7113#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=21&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":32171,"voices":87}},{"id":"r07-20250702-20","meetingId":"r07-cm07","date":"2025年7月2日","dateIso":"2025-07-02","committee":"ＳＤＧｓ推進・行財政改革特別委員会","time":"午前１０時００分～午前１１時３６分","status":"正式会議録","sourceType":"formal","overview":"ＳＤＧｓ推進・行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を26件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"公有地の件で、平塚２丁目寄付物件をぜひ視察に入れていただきたいです。それとあと、６月３０日の建設委員会で清掃事務所の西小山分室の統合ということで、こちらの公有施設が空くことになりましたので、そちらも視察も含めてといいますか、調査事項に入れていただきたいという要望をしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":4,"id":"exchange-001"}]},{"id":"topic-02","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"目的は何だったのか伺いたいと思います。それぞれについて、選定されたということで、何が変わるのか、選定されていないところとの違いというのはどういうものにあるのか伺いたいと思います。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"品川区では、ＳＤＧｓ未来都市に応募する以前から各部署での施策を通してＳＤＧｓ１７のゴールを目指すような取組を進めてまいりました。","voiceIndex":9,"id":"exchange-002"},{"speaker":"安藤委員","kind":"質問","question":"積極的に目標達成のためにということで分かりました。資料について幾つかお伺いしていきたいのですが、このファンドの実行委員会なのですが、会則によると実行委員会委員は会長が指名とあります。それについてお伺いしたいのですけれども。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"合わせましてＳＤＧｓの現在はプラットフォームの分科会となっております環境面での会議に長年、会長として関わってくださっていたという実績などもございまして、今回、令和６年度に新たにプラットフォームを立ち上げるときにこの方に委員長をお願いしたという次第です。","voiceIndex":11,"id":"exchange-003"},{"speaker":"安藤委員","kind":"質問","question":"区の課題を解決するものを募集しているとありますけれども、このうちのＳＤＧｓの様々なゴール・ターゲットのうち区が応えてほしい課題というのは主にどれだというのはあるのでしょうか。それと、助成金ですけれども、２年目までは受けられるようですけれども、その次の年度以降というのは応募不可となるのか、それとも、もう少し１年空ければ、応募できますようということなのか、そこら辺を伺います。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"現在、６の部署から課題を発信しておりますので、まず、ファンドの応募をいただくような事業者の方に今回説明会などもしておりまして、そこでこういうものを今は課題として認識しているということを発信しています。","voiceIndex":13,"id":"exchange-004"},{"speaker":"安藤委員","kind":"質問・要望","question":"分かりました。もう少し伺っていくのですが、去年は事業の実施期間というのは１２月から３月の４か月程度だったと思うのですけれども、今年はどうなのかというのが１つです。一次審査で不採用になった事業というのは主にどこが該当しなかったのかというところを教えていただきたいのと、それと３つ目は、二次審査で選定されなかった２つの事業というのは、平たく言えば６０点以下だったのかを教えてください。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"ただいまいただきました３点、質問にお答えいたします。１点目、事業の実施期間、対象の期間です。","voiceIndex":15,"id":"exchange-005"},{"speaker":"安藤委員","kind":"質問・要望","question":"なので、最後に、４つのこの事業を選定されましたけれども、どの点で、どのターゲットにこのような点で合致していますというのをもう少しこの場でもご説明いただきたいと思いますが、それぞれいかがでしょうか。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"２番目の一般社団法人めぐもりのところですが、先ほどもご説明したように地域の希薄化するコミュニティを活性化していくので、その取組自体が１１番のまちづくりにつながるといったところ。","voiceIndex":17,"id":"exchange-006"},{"speaker":"安藤委員","kind":"質問・要望","question":"そういった、２０３０年までに達成というところで本当に危機感を持ってやっていかなければいけないと思うのですけれども、やはり今の最後のところとかで品川区がかなり積極的に手を挙げて、ＳＤＧｓをするという姿勢を見せてこの事業に取り組んでいると思うのですけれども、各事業がＳＤＧｓのこういうところを進めるために行われているというのは、やはり発信という意味ではもっとより分かりやすいように。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":19,"id":"exchange-007"},{"speaker":"あくつ委員","kind":"提案","question":"ご説明、ありがとうあります。そこについて、まず１点目はお伺いをしたいと思うのです。すごい細かいことなのですけれども、ＳＤＧｓを冠とする事業ですから、そこが非常に重要になってくるということ。これはもしかしたら、所管課というよりは、事務局の話なのかもしれないのですけれども、そういったところも含めて、そこについての課題をどう捉えていくのか、外観から含めてお伺いしたいと思います。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"ただ、その一方で先ほどもご説明をさせていただいた中で触れさせていただいたように、そもそも申請の段階、提案の段階でＳＤＧｓに資するというところについての令和６年度の様式等ではまだまだそこを、申請書の段階での応募事業の内容が少し記述欄ですとか。","voiceIndex":21,"id":"exchange-008"},{"speaker":"あくつ委員","kind":"提案","question":"やはり、これは初年度だからというのもあると思うのですけれども、まず、こういう理解でいいのかというところで、この資料の中で寄附金収入が３万円ですけれども、区からの補助金として５,０００万円支出して、民間からの３万円で、これ１つ、大きな、私がこの事業スキームを見たときの今までにないと思ったのはまさにこの部分で、しかも、恐らく内閣府が評価したのもこの部分だと思うのですけれども。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"一方で、ただ社会的なメリットだけでは、なかなか企業の中で意思決定、寄附に決定するだけのものが弱い部分もあるというご意見も頂戴しておりますので。","voiceIndex":23,"id":"exchange-009"},{"speaker":"あくつ委員","kind":"提案","question":"けれども、やはり相当シビアだというところも企業として、今、こういう時代ですから、様々な不安定要素、経済的な要素もあって、そういった社会的な意見もあると思いながら、そこは本当に大きくてこ入れをしないと、今、私がどうこうとなかなかいいご提案ができないのですけれども、先ほど、大企業とか、金額の多寡ではなくて、広く募れる方法をというようなこともおっしゃっていましたけれども。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"国からの補助金につきましては令和６年度の６月の補正でモデル事業として予算計上していますので、当初予算には充てていないという形になります。","voiceIndex":25,"id":"exchange-010"},{"speaker":"あくつ委員","kind":"質問・要望","question":"ＳＤＧｓの予算が国から下りたところでそれは責任を果たさなければいけないのですけれども、というところも改めて確認をした次第です。もうこれも期限があって、今年の秋に終わりますけれども、そういったものを達成できているのかどうかとか、そういったものもやはり評価する側としてはもう少し細かい情報が欲しかったというところなのですけれども、その辺り、お考えをあれば、教えてください。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"ただ、ここにつきましてはなかなか事業実施期間まで期間中にアウトカム指標が出るかどうかもなかなか手探りなところはありますが、できるだけそういった指標を精査していき、より成果が区民の方にも見えやすい形になるように努めてまいりたいと考えております。","voiceIndex":29,"id":"exchange-011"},{"speaker":"あくつ委員","kind":"質問・要望","question":"既に課題として捉えていらっしゃって、アウトプット指標だけではなくて、アウトカム指標もこれから令和７年度の事業については行うということで、事務局としてはそういう認識でいらっしゃるということを今確認させていただいたので、まさにそこのところが区民への説明責任になると思いますので、要するに、この事業を新しいスキームで始めて狭い言い方ですけれども、品川区民に対して。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"令和７年度につきましては応募の段階からイベントに限らないのですけれども、そういう事業の実施のスケジュールを事前に出すとともに。","voiceIndex":31,"id":"exchange-012"},{"speaker":"あくつ委員","kind":"提案","question":"そういった中で、現場を見るしかないと思ったので先ほどご提案をしました。そうしないと評価もできない。これは実行委員会形式でやっていて、今までにない形での我々が関与できない形での場所でやっているものですから、当初から申し上げているとおり、議会としての危機感を持って昨年度も指摘をさせていただきました。代表的な事業でも結構です。最後に何かご意見があれば、教えてください。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"委員からご指摘いただきましたように、実行委員会形式で区の財源、５,０００万円当初予算乗せていただいたものを投入して実施している事業ですので、議会の皆様にもきちんとご報告、本委員会でもまた９月にご報告しますが。","voiceIndex":33,"id":"exchange-013"},{"speaker":"新妻委員","kind":"質問","question":"今の様々ご説明をいただきまして、令和６年度の事業の報告ということで、今日は報告をいただきました。次も継続をしていくというところで令和７年度の動きがもう始まっていると思います。シティラボのホームページを見ますと、寄附の申込みであったり、また、支援事業者の募集であったりというのがちょうど６月３０日まで行われていたと思いますので、その状況をお知らせいただけますでしょうか。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"ただいまご質問いただきました令和７年度の現在の進捗状況についてご報告をします。令和７年度の応募期間については６月１１日から募集開始しまして、６月３０日まででございました。応募事業者につきましては全部で８事業のご応募をいただいているところです。","voiceIndex":36,"id":"exchange-014"},{"speaker":"新妻委員","kind":"質問","question":"令和６年度は東京海上日動火災から１社、寄附をいただいたということなのですが、そこのキックオフイベントに参加をされていた企業・団体からはほぼ寄附がなかったという結果だったと受け止めてよろしいのでしょうか。今回、また、令和７年度はもう締め切っているわけなのですが、今後のさらに具体的な寄附を募っていくという取組について、もう少しお聞かせいただければと思います。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"はこのファンド事業について、きちんと趣旨ですとか、内容ですとか、あとは令和６年度に選定した事業の効果などにつきましても丁寧にご説明をしていくという周知の場を増やしていく、機会を増やしていくというのを考えております。","voiceIndex":38,"id":"exchange-015"},{"speaker":"新妻委員","kind":"質問・要望","question":"このホームページ、品川ＳＤＧｓ共創推進プラットフォームの会員企業としては企業が７、団体が１１団体ですか、ここに掲載がされております。ということは、まだまだ５６企業参加をされているということですので、関心を持ってこられた企業がこれだけいるわけですので、できたら、この会員になってしっかりこのホームページに記載をしていただくという、そういう会員登録ですか。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"委員からご指摘いただけましたとおり、品川ＳＤＧｓ共創推進プラットフォームの会員企業・団体を増やしていくことと、区の取組について理解していただき、今回のファンド事業の意義などについても丁寧にご説明をさせていただきまして。","voiceIndex":40,"id":"exchange-016"},{"speaker":"まつざわ委員","kind":"質問","question":"それと、一次審査でこれ、６事業が通過して、５事業が不採用となって、これ、経緯なんかもそうなのですけれども、いつも不思議に思うのは、例えば、不採用になった人というのはそれでもうお疲れさまという感じなのですか。何が言いたいかというと、多分不採用になっても、ここの事業に参加したいという企業があるとすると、何が駄目だったのかというのをある程度、フィードバックしてあげるというのですか。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"ただ、審査の具体的などういった点で不選定・不採用になったのかといった、審査の中身に関することはあまりお伝えできない部分もあるのですけれども、例えば、二次審査のところで事業の継続性だったり。","voiceIndex":43,"id":"exchange-017"},{"speaker":"まつざわ委員","kind":"質問","question":"そうすると、こういった募集期間を増やすとか、そういう改善の余地というのがあるのかどうかが１点と、あと、前後してしまうのですけれども、管理費支出の中で２９万余、これの管理費支出という部分なのですけれども、これって何に使われたものなのか気になっていて、そういう内訳、結局、これはしっかり２９万余、約３０万が効率的な運営にこうやってしっかり使われているのか。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"周知につきましては今回昨年の周知のチャネル・媒体に比べて、より区の、例えば、各部署で実施している中小企業の方とかスタートアップの方が参加しているようなイベントでチラシを直接お配りするですとか。","voiceIndex":45,"id":"exchange-018"},{"speaker":"筒井委員","kind":"提案","question":"それで、実証実験提示型は社会課題の解決に資する提案内容。ここは幅広に募集されていると思うのですけれども、課題解決型はしながわシティラボに今現在、各課から６課題挙げられていますけれども、結局、その課題解決の事業をやるということになったら、このしながわシティラボに挙げられている課題に結局縛られてしまうということなのですか。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"ただ、事業者の方などから、では、区は実際にどういった課題意識を持っているのかよく分からないというようなご質問もいただいておりますので、このしながわシティラボの課題一覧をご覧いただきまして、今。","voiceIndex":48,"id":"exchange-019"},{"speaker":"筒井委員","kind":"提案","question":"一方、しながわシティラボのページを見ますと、課題解決型の提案方法のご説明のところに提案募集中の課題に関する提案内容と書かれておりまして、課題一覧を見ると、各課の６課題が載っているということなので、応募しようと思っている企業・団体にしてみたら、この６課題しか駄目なのだと思ってしまうと思うのですけれども、先ほどの周知の部分も関連するかもしれないのですけれども、どのように。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"今回ご応募いただきました６事業の方中心に、あとは説明会にご参加いただいたような事業者の方に応募の際に分かりにくかった点など、ヒアリングをさせていただきまして、しながわシティラボの現在専用ホームページのほうでファンドについてのページも設けて掲出していますので。","voiceIndex":50,"id":"exchange-020"},{"speaker":"筒井委員","kind":"質問","question":"国連総会で明言をされて、それを受けて今までＳＤＧｓだとかＥＳＧだとか、ＤＥＩだとか、そういったことに協力的な企業も、やはり企業も営利事業をやられているわけですから、そうしたことでやはり政治の動向というのをめざとく見て、そういう人が後ろ向きになるという判断をされていると思うのですけれども、その辺り、今後、品川区としてはどのように影響が日本において、品川区においても出てくると。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"委員からご指摘ありましたトランプ政権の動きですとか、その辺の影響かヨーロッパでのＥＳＧ投資の動きなども後退しているというようなニュースも報道で認知しているところではありますが、ＳＤＧｓ、２０３０年の達成に向けた世界的な動きですとか。","voiceIndex":52,"id":"exchange-021"},{"speaker":"筒井委員","kind":"意見","question":"ですので、様々、流動的な状況になっていると思うのですけれども、一方で、こうした社会的課題を解決するというのは非常に意義があることだと考えておりますので、企業への周知、寄附を募るに当たってその説明の方法、ウェルビーイングとか、むしろ、社会的課題解決になるためのファンドなのですというような、そうした周知の工夫というのも必要と思っているのですけれども、その辺り、お聞かせください。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"民間資金の確保・獲得に向けた企業・団体の方向けの周知・説明の方法については、課題として認識していますので、引き続き、品川ＳＤＧｓ共創推進プラットフォームに会員企業の方などにもヒアリングをしながら、どういった点を説明するのが企業にとって、例えば。","voiceIndex":54,"id":"exchange-022"},{"speaker":"こしば委員","kind":"質問","question":"計画の中で３分の１、事業が減額されてしまっているので、何か全体にもまた影響があったと思うのですけれども、その辺り、どのような説明を受けていたのか、また、区の考えとかも含めて教えていただけますか。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"今回、畑の運営維持費用が計画段階よりも減額となった主な理由には、畑の運営委託を再委託と申しますか、専門としている協力関連会社のほうに委託をしていたのですけれども、そこの人件費が必要、計画よりも人数が少なく済んで、運営の維持費用が大きく減ったですので。","voiceIndex":57,"id":"exchange-023"},{"speaker":"山本委員","kind":"質問","question":"事業者のところは、当初２年目でどれぐらいを申込みがあることを想定して進めていらしたのかお聞きしたいのと、それから寄附のところは今年度の計画ではどれぐらいの金額を集めるというご計画を立てていらっしゃるのかというのをお伺いしたいのと、これ、なかなかすぐに１００点満点の姿が見られるというのは考えにくいと思っているのですけれども。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"ただ、そうは言っても応募の見込み数には達することができなかったので、その原因についてはきちんと分析をしてまいりたいと考えています。寄附につきまして、令和７年度の計画です。","voiceIndex":60,"id":"exchange-024"},{"speaker":"山本委員","kind":"質問・要望","question":"これまでの質疑の中でも様々工夫の必要性があることもご質問があり、されているということでしたので、ぜひ進めていただきたいと考えています。あるべき姿というところが、では、この５,０００万全てを民間資金でということなのか、その一部なのか、どのようにお考えなのか金額明細があれば、教えていただきたいと思います。","respondent":"井添ＳＤＧｓ推進担当課長","answer":"区の拠出額です５,０００万円に対して民間資金も同じ程度を目指して、あるいはそれを超えるような、区の財源に依存しないというのは、それを超えるような金額だと考えておりますので、そこを目指してまいりたいと考えております。","voiceIndex":62,"id":"exchange-025"},{"speaker":"山本委員","kind":"質問・要望","question":"この基本の延長線上だと、なかなか集まりにくいと思いますので、やはり出してもいい企業ですから、それを出している方々がそのメリットを一定感じると思うＣＳＲという観点でも企業宣伝としても価値があるような形でのその取組に仕立てていくことがこの事業を成功に導く１つの鍵となると思いますので、そういった点で改めて施策の推進のご検討をお願いしたいというところがあります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":64,"id":"exchange-026"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7115#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=20&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":31246,"voices":68}},{"id":"r07-20250703-22","meetingId":"r07-cm07","date":"2025年7月3日","dateIso":"2025-07-03","committee":"まちづくり・公共交通推進特別委員会","time":"午前１０時００分～午後 ０時２分","status":"正式会議録","sourceType":"formal","overview":"まちづくり・公共交通推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を41件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"石田（秀）副委員長","kind":"意見","question":"決を採るしかありませんね。だけれども、今は、会派の代表が発言しているから意見を聞いていない人もいる。どうかというのは分かりませんね。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":7,"id":"exchange-001"},{"speaker":"石田（秀）副委員長","kind":"意見","question":"決を採るか、あとは会派の代表に聞いているから、あと二人聞けば終わるわけです。３人かな、３人聞けば終わるわけなので。決を採ってもいいけれども。は委員長判断になる可能性もあります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":9,"id":"exchange-002"},{"speaker":"石田（秀）副委員長","kind":"意見","question":"いや、２つあります。審議の妨げにならないように冒頭だけにするのかと、それと、自席から撮るのか、前まで来て撮っていいのかというのもあります。感覚として、前に来て撮っても、それは審議の邪魔になりませんよと思うなら、いいか悪いかというのを今度諮らなくてはなりません。だから今ので、審議の邪魔にならないようにというのは、どこまでかという意味があります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":11,"id":"exchange-003"}]},{"id":"topic-02","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"そして上部工に移っていくということで計画は進んでおりますので、１点だけ伺いたいのですけれども、総工事費２０億円を見込んでいるとご説明があるのですが、資材高騰や人件費の高騰等あると思うのです。今、そういう状況だと思うのですけれども、出来上がる頃にはこの２０億円を超えるようなものになってくるのか、２０億円以内で済むと見込んでいるのか、そこを伺いたいと思います。","respondent":"森道路課長","answer":"令和４年度から進めております事業計画の中で２０億円とお示しをしてまいりましたが、今、委員からご指摘のあった物価高騰や労務費のアップということで、これを大分超過するのだろうと考えているところです。今のところ、３０億円ぐらいになるのではないかという状況です。","voiceIndex":33,"id":"exchange-004"},{"speaker":"石田（ち）委員","kind":"意見","question":"２０億円程度でという説明が、数年経って、今３０億円と見込んでいるということです。これもまた、３０億円で本当に済むのかなというところでもあるので、先ほども言いましたけれども、こうした物価高騰が続いている下で、そしてさらなる超高層再開発の基盤整備になるのではないかというところでは、私たちは改めて、必要ない、反対だということを主張しておきたいと、意見をしておきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":35,"id":"exchange-005"},{"speaker":"田中委員","kind":"質問・要望","question":"これは議会の総意として議決されています。回遊性ということもありますし、地域の交流ということもあって、ここを、ちょうど運河の中間に橋が造られることで、対岸のほうに渡れるという意味の回遊性は分かりますけれども、概要のところにある利便性というのは、何を求めて、というか何を指しているのかということかを改めて確認させていただきたいと思います。","respondent":"森道路課長","answer":"より利便性が高まってくるだろうと考えておりますので、そういった意味でも、橋の機能として、しっかり地元の両側の方々に使っていただければなと思っているところです。","voiceIndex":37,"id":"exchange-006"},{"speaker":"田中委員","kind":"質問・要望","question":"お話は分かりました。ただ、現実としたときに、既に東大井、立会川とか鮫洲方面の方々と、勝島あるいはそこを越えて八潮の方々の交流の動線は確保されている中で、今回の人道橋を新たに造り、利便性あるいは回遊性を向上させるということなのですね。人道橋建設後のネットワーク構築に向けた具体的な何か取組を何か既に行っているとするならば、ぜひお聞かせをいただきたいと思います。","respondent":"森道路課長","answer":"今のところ佐川急便のほうでは、特に、それは絶対駄目だというようなことはないと聞いておりますので、花海道と一体的に整備をして、より人道橋にアクセスしやすいような、また、委員おっしゃるように人道橋を渡ってきて勝島側のほうに行きやすいように。","voiceIndex":39,"id":"exchange-007"},{"speaker":"田中委員","kind":"質問・要望","question":"ぜひ、お願いをしたいと思います。もう１点、今回、上部工で、横から見た図面が出ているのですけれども、歩行者の目線からも、見えなくはないと思っています。要は水辺から見る景観というものも求められると思っているのですが、側面の、何か水辺に親しむような視点から、模様というか、何というのでしょうか、何かそういうものを描く予定があったりするのかどうか、少しそこを教えてください。","respondent":"森道路課長","answer":"花海道のほうからも、橋はしっかり見えるようになって、夜間はここをライトアップする予定にしています。今、目黒川中心に橋のライトアップをしておりますけれども、ここもライトアップをしていきたいと思っています。","voiceIndex":41,"id":"exchange-008"},{"speaker":"田中委員","kind":"質問・要望","question":"同時に、競馬場の設置区だからとして交付金が３億円、毎年、品川区に入っています。一つとして、競馬場が迷惑施設だから地元にお金を渡すというようなことはどうでしょうか。せっかくなので、その財源ということ、あるいは競馬場との関係性という視点で、今の思いというかお考えがあれば、最後にお聞かせをいただきたいと思います。","respondent":"高梨都市計画課長","answer":"大井競馬場といたしましても、競馬場の中だけではなくて、周辺地域への貢献であったり、にぎわいの拠点としてビジョンでも位置づけられていたところ、非常に重要視、十分認識をしていただいておりますので、今、委員からご提案のありました内容も含めて、そういった会議体。","voiceIndex":43,"id":"exchange-009"},{"speaker":"塚本委員","kind":"質問","question":"今、田中委員のお話よりもう少し細かな話になるのですけれども、同じように回遊ということで、特に橋は、一応自転車も降りて渡ることは可能というふうに伺っています。あるいは、なっていなければ、そこは、特に勝島の住宅街から行けるような形で整備するような予定とはあるのかというのを伺いたいと思います。","respondent":"大友公園課長","answer":"勝島人道橋までのアクセスですけれども、現在、こちらのほう、勝島の遊歩道の部分、護岸上のところについては、自転車の乗り入れが、乗ったまま走るということはできないという運用にしています。","voiceIndex":45,"id":"exchange-010"},{"speaker":"塚本委員","kind":"質問","question":"今の話だと、自転車に乗ったままではなく、自転車を転がしながら行く距離が相当あるので、今後もそのままというお話でしたけれども、ここは何とかしてほしいと皆さん思うと思うのです。そこは、何かやりようはないのか。何かしら、この先検討していくすべというのはないのかというのは改めて伺いたいと思います。","respondent":"大友公園課長","answer":"今後設計していく中で、どこまで拡幅できるかというところについては、かなり厳しいというところがありますので、現状のままの運用となるという見込みが非常に高いのですけれども、ご意見としていただいて。","voiceIndex":47,"id":"exchange-011"},{"speaker":"塚本委員","kind":"質問・要望","question":"現状ではというところで、なかなかハードルが高いということでしたけれども、この勝島のまちづくりというところでは、この先ずっと喉に刺さった骨のようになる課題のような気がしますので、ここの解決というのは１つの、区としても取り組むべき課題として進めるというか取り組んでいただきたいと要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":49,"id":"exchange-012"},{"speaker":"田中委員","kind":"質問・要望","question":"先ほど伺えばよかったのですが、聞き漏らした点が１点だけありました。今後、契約が進んで工事が進む中で、どの段階かは別として、勝島人道橋という名前を、もっと地元に親しまれる橋の名前に、私はぜひしていただきたいと思うのですが、橋のネーミングについて何か今お考えがあればお聞かせをいただきたい。","respondent":"森道路課長","answer":"橋の愛称といいましょうか。名称につきましては、地域の方々の意見をしっかり聞いてまいりたいと考えています。","voiceIndex":51,"id":"exchange-013"},{"speaker":"若林委員","kind":"質問","question":"続けてですが、この今の人道橋、まさに私も全く田中委員のおっしゃるとおりだと思います。そもそも人道橋というのは、いわゆる行政用語で、人道橋ということは、そもそも自転車は、乗って走行できないという橋のことを人道橋というふうに呼称するのでしょうか。","respondent":"森道路課長","answer":"自転車が通らない橋イコール人道橋というふうにしているかと言われると、昔からの名称であれば、もしかすると、自転車が通れても人道橋と言っているかもしれませんけれども、基本的に区内にある人道橋は。","voiceIndex":54,"id":"exchange-014"},{"speaker":"若林委員","kind":"確認","question":"これまでの答弁で一応確認させていただいて、今のところ、乗って通行することができないという、今の段階でのご答弁で言うと、このイメージ図がありますけれども、こういうイメージで整備が進んでいくだろうと思います。これは立会川駅方向から佐川急便に向かってということですよね。自転車は降りて走行してくださいと、通行してくださいとなると、どういうふうに通行させるのでしょうか。","respondent":"森道路課長","answer":"スロープについては、バリアフリーの観点から必要なものでございまして、どうしても橋の高さと堤防の高さ、花海道の表面の高さが２ｍ以上違うものですから、そこでスロープで必要な延長を取って回っていくということになります。","voiceIndex":56,"id":"exchange-015"},{"speaker":"若林委員","kind":"確認","question":"分かりました。もう一方で、対岸のほうの佐川急便側の課題もあるとは思います。これは、いわゆる自転車に乗ったまま走行ということを本当に検討しますということ以上に、いわゆる前向きに捉えたときに、どういう部署とこれから詰めていくのか。いろいろな法的な規制、道路交通法上の規制とかということが容易に考えられるわけですけども。どういった部署と進めるのか、そこだけ最後に確認させてください。","respondent":"大友公園課長","answer":"一番の課題として、今現状の護岸の天端、天端と言われる平らな部分、一番上の高い部分で歩行者が歩いている部分、こちらの幅が、今、通行できる、できないというところも含めて、約３ｍぐらいの幅になっております。","voiceIndex":58,"id":"exchange-016"},{"speaker":"藤原委員","kind":"質問・要望","question":"これ、まちづくりの目標１、２、３と出ています。言葉的というかこの文章は、なるほどなというきれいな文章なのですが、私は具体的にイメージが湧かないのです。目標は分かります、この文章は。ですので、もっと具体的に、こういうふうに３つの目標を掲げて、人道橋ができた後に、こうなっていくのですという町のイメージ、その辺を具体的に教えていただきたいのですけれども。","respondent":"高梨都市計画課長","answer":"１つは、やはり今、説明がありましたけれども、しながわ花海道水辺広場の公園として、地域の皆様方が護岸や、また、北側の鮫洲入江広場等のユリ等々、非常ににぎわいを持って皆さんで管理していただいて。","voiceIndex":60,"id":"exchange-017"},{"speaker":"藤原委員","kind":"質問・要望","question":"勝島、八潮、そしてこの人道橋ができることによって、すごく活性化されて、にぎわいの地域になったと、いわゆるわくわく感というのを形成していっていただきたいと思ってこういう質問をさせていただいています。１つの大きな町という意味でやっていっていただきたいと思うのですけれども、その辺について最後、また答弁していただけますか。","respondent":"高梨都市計画課長","answer":"今回の人道橋の整備も、いろいろと歩行者の動線についてのお話もありましたけれども、八潮とつなぐかもめ橋への動線の強化にもつながっているのかなと考えています。八潮についても、まちづくりの考え方、ガイドライン等の策定等、これまでも取組を区としても進めてまいりました。","voiceIndex":62,"id":"exchange-018"},{"speaker":"石田（秀）副委員長","kind":"質問・要望","question":"すみません、幾つか。私は一般質問もしたので、ぜひ、それで幾つか伺いたいのかですが、最初に今日、田中委員からも、今、藤原委員からもありましたように、これは特別委員会でやっています。特定事件調査で八潮・勝島のまちづくりに関することということになっているわけですから、これはもう本当にこのことをしっかりやっていっていただきたい。私の感覚では。質問の入り口にさせてほしいのですけれども。","respondent":"森道路課長","answer":"今、そういった部分で大分、この辺のまちづくりというのは大きく変わってくるだろうと認識をしています。ですので、ぜひこの特別委員会でも、そういった資料をしっかり出しまして、ご議論いただければなと思っているところです。","voiceIndex":65,"id":"exchange-019"},{"speaker":"石田（秀）副委員長","kind":"質問・要望","question":"あそこが本当に憩いの場になるのだったら、もう１点、これも東京都にしっかりやってもらわなくてはいけないけれども、不法係留はどかしたほうがいい。だからそこら辺も、ぜひ区が頭に入れていただいて、都に強く言っていただくとか一緒になってこういうことやっていきましょう、だから、ああいうところも整理をしていきましょうということをぜひ考えていただきたいのです。ここら辺はどうですか。","respondent":"森道路課長","answer":"なぎさ会館がこの後どうなるかも含めて、東京都としっかり協議をしていきたいと考えています。これまでの懸案事項につきましても、東京都のほうに改めて情報共有をさせていただきながら、いい方向に進めていければなと考えています。","voiceIndex":67,"id":"exchange-020"},{"speaker":"石田（秀）副委員長","kind":"質問・要望","question":"八潮のことも、この委員会の中で出てくると思うので、ぜひ八潮との連携もしていただきたいし、この地域がどこまでという範囲で、この特別委員会で、そこは入っていないと言われると困るけれども、水族館もどうするのというのがあります。品川区だけではもうできないと思っている。東京都とも連携を取って、すばらしい水辺を活かしていただきたい。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":69,"id":"exchange-021"},{"speaker":"若林委員","kind":"質問","question":"質問ではございませんが、冒頭、正副から１年間の調査日程案が出て、今日、田中委員、藤原委員を口火に、要するに八潮・勝島の全体のまちづくりを考えていきましょうという発言がありました。せっかくなので、これは正副委員長に日程をうまく調整していただいて、温かいうちに、また、議論をしたいなと思いましたので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":71,"id":"exchange-022"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"その手法として超高層再開発が中心になって進んでしまっているというところを私たちは反対しているのです。押して通るというのもあるかもしれませんけれども、そこに住む住民の皆さんが、どういう町を望むのか。にぎわうのはいいけれども、こんな感じになると思わなかったみたいなことにならないように、ぜひ、住民の声というのは、何度も聞いていただきたいなと思います。そこを確認させてください。","respondent":"森道路課長","answer":"聞いていくことは、区としてもしっかり進めていきたいなと思いますけれども、そういった中でどうやって、方法論といいましょうか、そういった部分については、今後様々な部署と検討して進めていければと思います。","voiceIndex":73,"id":"exchange-023"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"様々説明会等もあるということですけれども、そこでも出ないような声というのは、本当にたくさんありますので、ぜひ住民の声を聞いて、住民が望むまちづくりというのを進めていただきたいと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":75,"id":"exchange-024"},{"speaker":"石田（秀）副委員長","kind":"意見","question":"今いろいろ、再開発の話だとか、いろいろな話が出たので１つだけ、お願いにしておこうかな。東京都とも話をすると、運河、３ｍぐらい出してくれと、今の場所から。立会川はやると言っているわけです。３ｍぐらい出すとか。計画に入れ込んでもらうということも、すごく大切なことだと思うので、そういうことも踏まえて、ぜひそういう護岸のことは諦めずにやってほしいなという、お願いだけしておきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":77,"id":"exchange-025"}]},{"id":"topic-03","title":"新庁舎整備に向けた実施設計概要等の説明の実施結果","agenda":"新庁舎整備に向けた実施設計概要等の説明の実施結果","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"ここでもご意見、工事費の質問等も出ていたと思うのですけども、現在、結構な額になりました。５７０億円から６８０億円でしたか、３０億円でしたか、ごめんなさい。それが、今後さらに上がっていく予測。要は、今の人道橋でもありましたけれども、資材高騰と人件費の高騰等で、ここがさらに上がっていくということで、見通しというのはどのようにお持ちなのか伺いたいと思います。","respondent":"小林新庁舎建設担当課長","answer":"今回の説明等の中で、実施設計概要のほかに工期に関すること、また、工事費に関することも併せてご説明をしたところでございまして、こういったようなご質問があったところです。","voiceIndex":83,"id":"exchange-026"},{"speaker":"石田（ち）委員","kind":"確認","question":"分かりました。今、ＪＲのビルも２棟建設され、やはりいまだに、あの中に区役所が入るのでしょという意見も本当に多く出されていて、いや、その隣に少し小さい、２棟のＪＲの建物よりも小さめのものが建ちますよということでご説明しているのです。やはりそこにそれだけの工事費がかかっていく、さらに上昇していると。ごめんなさい、確認だけさせてください。ごめんなさい。そこも確認させてください。","respondent":"小林新庁舎建設担当課長","answer":"それからＺＥＢの認証ですが、現在、設計者と共に申請に向けた検討を進めているところでございまして、現在のところＺＥＢ Ｒｅａｄｙの取得を目標に、今、最終的な調整を進めているところです。","voiceIndex":85,"id":"exchange-027"},{"speaker":"石田（ち）委員","kind":"意見","question":"エコルとごしが９０キロワットの太陽光パネルというところで、やはり庁舎ですので、さらにという思いが個人としてはありますので、さらに検討していただけたらなと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":87,"id":"exchange-028"},{"speaker":"田中委員","kind":"質問","question":"私は５月から特別委員会に参加をさせていただいておりまして、それまでは無所属でしたので特別委員会には参加できず、庁舎のことの議論には、全体の会議の場でしかお伺いする機会がなかったので、各委員の皆様よりは知識がないという前提でお伺いをしたいと思います。それで、今日の質疑は、説明会で出てきた、質疑の一覧が別添１でありますけれども、このことについての質疑ということですよね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":89,"id":"exchange-029"},{"speaker":"田中委員","kind":"確認","question":"一方で、区民の立場からすると、記載されている、合同庁舎にあることで利便性を享受していただいていますので、いわゆる何というのですか、入居料というか、建物の使用料というか、そういうことの中で、区として、国なり都に対して、継続してこの場所にとどまってほしいという視点からの、何というのでしょうか、交渉することというか、例えば入居料を下げるから継続してくださいとか、ごめんなさい。","respondent":"小林新庁舎建設担当課長","answer":"現段階では、入居されないとか、あるいは完成したときに、入居後すぐ出ていくというところの前提で、今、工事が進められているものではないと認識しています。","voiceIndex":94,"id":"exchange-030"},{"speaker":"田中委員","kind":"質問・要望","question":"ご答弁としては分かりました。そのような視点で言うと、壁面に緑化することで、例えば虫がつくのではないかとか、虫を求めて鳥が来るのではないか、鳥が来ると、そこに巣を作るのではないかとかという。すみません、いい面はいっぱいあるのですけれども、また一方で、そこを維持するためから出てきてしまう課題について、どのように捉えていこうとされているのかお伺いしたいと思います。","respondent":"小林新庁舎建設担当課長","answer":"もう１点、木材の耐久性というご質問があったと思いますが、これ、直接樹木に薬剤をまくというわけではなくて、今回、外壁の一部に、いわゆる木を使う予定、意匠として木を使う予定にしてございまして、その木をそのまま使いますと、カビがあったりとか、あるいは。","voiceIndex":96,"id":"exchange-031"},{"speaker":"田中委員","kind":"質問・要望","question":"分かりました。すみません、少し細かいのですけれども、駐車場と駐輪場のことが７ページに載っていて、ここの説明が理解できないのでお伺いしたいのです。車に対する説明と自転車に対する説明について、少し整合性が取れていないような気がすると私は受け止めるのですが、どういう背景があるのかということをお聞かせいただきたいと思います。細かいことがまだあります。","respondent":"小林新庁舎建設担当課長","answer":"今回、品川区につきましてもそういった観点で、品川区というところを分かるような形で、今回、最大限表現させていただいてありますが、例えば都市ブランディングという話になりますと、広報のほうで都市ブランドデザインというのが今回、策定されてありますので。","voiceIndex":98,"id":"exchange-032"},{"speaker":"田中委員","kind":"質問・要望","question":"この建物だけではなくて、区役所を活用する方の視点に立った総合的な交通施策も、当委員会の所管事項になっていますが、いろいろな方が利用できる環境にしていただきたいと思います。最後もう１点だけ、ごめんなさい、私、何回も言っているのですが、近隣商店街の方への配慮というのは絶対にしていただきたいと思います。そこは何回も言っているので、もう１回、今後のことを確認したいと思います。","respondent":"泉広町事業調整担当課長","answer":"周辺商店街との関わりというところのご質問です。こちら、周辺商店街との関わりにつきましては、令和２年に策定いたしました大井町駅周辺まちづくり方針の中でも、しっかり周辺と取り組んでまいりますということで位置づけをしています。","voiceIndex":100,"id":"exchange-033"},{"speaker":"えのした委員","kind":"質問・要望","question":"様々ご回答ありがとうあります。ご答弁ありがとうあります。私もこの計画説明会、４月５日に参加させていただいて、地元武蔵小山商店街、パルム会館で行われた区民説明のオープンハウス方式にも行かせていただきました。私も当日、係の人に聞いたら、やはり商店街なので、チラシの受け取りもほかと比べても非常にいいようなお話もあったので、その辺、あと男女比ですとかもあれば教えていただきたいです。","respondent":"小林新庁舎建設担当課長","answer":"今まで基本設計概要ですと、お話ししても、なかなか足を止めてまで見ていただける方が非常に少なかったのかなというとこは課題でございましたので、今回、そういったようなファミリー層も含めてご説明できたというところにつきましては、１ついい結果だったと認識しています。","voiceIndex":104,"id":"exchange-034"},{"speaker":"藤原委員","kind":"質問","question":"これから新庁舎ということで、私も期待している１人なのですけれども、まず、細かいところからお伺いします。これからだと私は思っているのですけれども、現区役所の入り口の階段を降りたところに、白いパネルで計画がもう出ています。敷地が何平米でという形で。役所がやっていることですから、法令・条例に基づいてやっているとは思うのですけれども、その辺の説明をまずいただけますか。","respondent":"小林新庁舎建設担当課長","answer":"なぜ今回、早めに設置したかといいますと、先ほど申し上げたとおり、４月４日、５日に、今回、経過説明会を実施していますので、説明会をきちんと区民の方にご説明する前に、看板を設置してあわせて周知することが望ましいだろうというふうに。","voiceIndex":108,"id":"exchange-035"},{"speaker":"藤原委員","kind":"質問・要望","question":"条例に基づいてしているということで確認がまず取れました。まだできてないけれども。今日、この辺というのは、都市開発の課長がいらしていないので、答弁できないかもしれないのですけれども、そんな意味において、バーッと要望、質疑、意見を読んだのですが、その辺についてはなかったと思う。個々というよりも町全体。その辺についてはいかが考えているのか、改めてお伺いします。","respondent":"高梨都市計画課長","answer":"本特別委員会の中でもそうですし、この大井町全体のまちづくりがどうなっていくのか、社会実験等も含めて、また、特定事件調査の中でご報告する機会が設けられるものということで認識しておりますので、その中でも、また、いろいろとご提案。","voiceIndex":110,"id":"exchange-036"},{"speaker":"藤原委員","kind":"質問・要望","question":"こういうお題があって。まちづくりの特別委員会が設置されたわけですから、この全体がどうなっていくかということ、今、あそこのどんたく通りの社会実験という話が出たと思うのですけれども、もう少し再開発という意味でも、どういう絵を品川区として描いているのだ、地域も協力して描いていきたいのだと、ということを、もう少し答弁をいただきたいと思うのですが、その辺については、いかがでしょうか。","respondent":"高梨都市計画課長","answer":"この方針に従って様々なまちづくりが今までも進められてきていますし、現在、広町地区は事業中といったところでどうしても注目されますけども、そのほかの地区についても、地域の皆さんとの話合い、まちづくりに向けた様々な話合いが進められているものと考えています。","voiceIndex":112,"id":"exchange-037"},{"speaker":"藤原委員","kind":"質問","question":"課長、だからなのです。先ほど田中さんから商店街というお話も出たではないですか。まちづくりという意味で。商店街もあり、住まいのまちづくりもあり、２６号線を挟んで住まいの部分があり、町全体をどう考えていくかが、私は特別委員会の意義だと思っているのです。私はこれが大切だと思っているのですけれども、その辺についてはいかがでしょうか。","respondent":"高梨都市計画課長","answer":"新庁舎、広町のほかにも様々な動きがありますので、そういった動きの中で適宜適切に、必要に応じて委員会に報告がなされるものと認識しています。","voiceIndex":114,"id":"exchange-038"},{"speaker":"石田（秀）副委員長","kind":"意見","question":"大分違うよ。これ、建設委員会と仕分をしましょうという話です。こっちの委員会の範囲は、中小企業センター、しながわ中央公園、あそこまでいろいろあるのだけれども、この今の庁舎周辺というのはどういうふうにするのというと、跡地もあるから、そこら辺をどうするという。広さの問題もあるのだけれども、それ以外にも例えば駅とか、その周りのところとか、そういうのはここではない、建設委員会。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":117,"id":"exchange-039"},{"speaker":"石田（秀）副委員長","kind":"意見","question":"ある程度。一応そういう仕切りはどっかでしないと駄目なので。だから、特に再開発とかハードの部分は、今、委員長が言ったように、建設でやろうと。ソフトの部分でも、中でもソフトの部分はこっちで。だから、ソフトというかＥ地区のソフトの部分というのは、触れたくなるけれども、それはやめておきましょう。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":119,"id":"exchange-040"},{"speaker":"石田（秀）副委員長","kind":"質問・要望","question":"１点だけ。物事の考え方だけ、ぜひ。本当に。だからこういうことで、せっかくランドマークタワーを５０年から７０年に１回建てるわけだから、そこら辺は自信を持って、しっかりそういうものを建ててほしいなと思っています。５０年から７０年先のものをやってよかったって思われるような、それはしっかりしたランドマークタワーを建ててほしいなという思いがあるのだけれども、意気込みだけ聞きたい。","respondent":"小林新庁舎建設担当課長","answer":"委員ご案内ありましたとおり、やはり下げられるところは下げていく、レベルを保つところを保っていく、そういうところのめり張りをしっかりつけていきながら、今後も新庁舎整備、しっかりと進めてまいりたいと思っているところです。","voiceIndex":123,"id":"exchange-041"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7155#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=22&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":36026,"voices":129}},{"id":"r07-20250709-10","meetingId":"r07-cm07","date":"2025年7月9日","dateIso":"2025-07-09","committee":"議会運営委員会","time":"午前１０時３０分～午前１１時１５分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を25件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"令和７年陳情第２５号、区議会だよりの「請願・陳情の審査結果」を精密にする事を要望する陳情","agenda":"令和７年陳情第２５号、区議会だよりの「請願・陳情の審査結果」を精密にする事を要望する陳情","exchanges":[{"speaker":"せお委員","kind":"意見","question":"私が区議会だよりの編集を行っている広報会議のリーダーをもう３年目になりますが、やらせていただいているので、区議会だよりの現状というか、そういったところをまずお話しさせていただければと思います。そういった編集方針があるということ。ページ数が増えれば、予算の面でいうと１号ごとに１００万円強、約ですけれども、増えて、年間で４００万円強増えるということになります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":15,"id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"私は知らせるべきだと思うのですけれども、それとも知らせるべきではないというお考えなのでしょうか。そこら辺ですね、委員間討議という話もありましたので、皆さんに伺いたいと思います。陳情には、この情報は最重要という言葉もありますけれども、私は知らせるべき情報だと思っているのですけれども、皆さんいかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":17,"id":"exchange-002"},{"speaker":"安藤委員","kind":"質問","question":"事務局に伺いたいのですけれども、ご意見が出なかったので、そんなに難しいことかなとは思うのですが、知らせるべきである、知らせるべきでないという質問だったので、ぜひ聞かせていただきたかったのですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":19,"id":"exchange-003"},{"speaker":"あくつ委員","kind":"質問","question":"何で載っているのですかという話。それは載せるべきだから載せているのでしょう。そんなことも分からないで、今質問されたのですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":22,"id":"exchange-004"},{"speaker":"安藤委員","kind":"質問","question":"言ったのですけれども、審査結果、つまり、全議員の賛否ですね、請願・陳情は載っていないのですよ。なので伺ったのですけれども。今は載っていない。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":23,"id":"exchange-005"},{"speaker":"あくつ委員","kind":"質問","question":"さっき、それは言わなかった。全議員の賛否を載せるべきかと言っていないでしょう。言いましたか。そのための今日、あれなのでしょう。それはだから、結果とすれば、結論として採決をすると。採択にするか不採択にするかということでしょう。先ほど説明もありましたけれども、それを今問うてどうするのですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":24,"id":"exchange-006"},{"speaker":"安藤委員","kind":"質問","question":"態度のほうで示されるというお話でした。事務局に伺いたいのですけれども、現状、議案の態度についてはホームページに全議員の賛否が掲載されていますが、請願・陳情の態度については、そもそも区議会だよりに掲載とかいう以前に、ホームページへの掲載そのものがないと思うのですけれども、それで間違いないか、伺いたいと思います。","respondent":"大澤区議会事務局長","answer":"安藤委員の認識のとおりでよろしいと思います。","voiceIndex":25,"id":"exchange-007"},{"speaker":"安藤委員","kind":"質問","question":"分かりました。私は、請願・陳情というのは、少なくとも討論が行われた場合は議場で全員の賛否の態度が明らかになっているわけですから、その場合は議案と同様、ホームページに掲載するよう改善が必要だと思うのですけれども、いかがでしょうか。これは事務局にも聞きたいのですが、どうですか。","respondent":"まつざわ委員長、大澤区議会事務局長","answer":"ホームページという話は十分大切な議論だと思うのですけれども、現状の陳情の趣旨というのが、区議会だよりの請願・陳情、要は紙ですね、区議会だよりに載せる・載せないという議論ですので、これを。今委員長がおっしゃったように、ホームページに掲載するかどうかは、事務局の判断ではなく、議員皆さんの総意ということになろうかと存じます。","voiceIndex":27,"id":"exchange-008"},{"speaker":"安藤委員","kind":"質問","question":"そうなのです。結局、私たち議会がどうするかというところだと思うのですけれども、私が伺ったのは、区民に公開するかどうかという点で、物すごい共通点があるのです。議案はマル・バツで全部あります。ない状況なのですけれども、これをやはり、まずは少なくともホームページに掲載するという改善が必要だと思うのですが、皆さんのお考えはいかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":30,"id":"exchange-009"},{"speaker":"せお委員","kind":"質問","question":"安藤委員にお聞きしたいのですけれども、では、そのホームページに載せるのは誰がやるのですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":32,"id":"exchange-010"},{"speaker":"安藤委員","kind":"意見","question":"これは、議案はマル・バツを全部載せていますけれども、それと同様に、ホームページをアップする方が行うことだと思います。現にアップしている方が、事務局だと思いますけれども、行うことだと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":33,"id":"exchange-011"},{"speaker":"せお委員","kind":"質問","question":"私たちでできることはなるべくして、例えば一般質問の要約とかも、途中からそれぞれの議員がやろうという、それで負担が減ったのかどうかというのもまた別の議論なのですけれども、でも、そうやって自分たちでつくっていこうという流れがある中で、それを事務局にお願いする……、私たちができるでしょうか、ホームページに毎回載せるというのを。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":34,"id":"exchange-012"},{"speaker":"安藤委員","kind":"質問","question":"当然事務局の方にやってもらうことだと思いますけれども、問題は、先ほど局長がおっしゃったように、自分たちで判断するということではなく、議員の人がどう考えるか、議会のほうでどういうふうに、議会で行われた審議をどのように区民に伝えていくかということの考え方が示されない限りは事務局だって動きようがないわけですから、この陳情に書いてあるように、区政に関心がある。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":35,"id":"exchange-013"},{"speaker":"せらく委員","kind":"質問","question":"広報会議のせおリーダーにお伺いしたいのですけれども、広報会議で狛江市議会を視察して、ギカイガイドのお話を伺ったと承知しているのですが、品川区議会だよりにおいては、狛江市の事例のうちで、どのような点を参考にして、今後どのように取り入れていくか、お考えを伺えますでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":37,"id":"exchange-014"},{"speaker":"せお委員","kind":"質問","question":"７月末に１回目が行われるので、そこで皆さんのご意見を伺いながら、どこを取り入れていくかという。昨年の１２月に私たち広報会議でアンケートをとったので、そこでのご意見も参考にしながら、そして、狛江市も結構皆さん感銘を受けて帰ってこられたと聞いていますので、そこも参考にしながら、紙面構成を検討していく予定です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":38,"id":"exchange-015"},{"speaker":"せらく委員","kind":"質問・要望","question":"狛江市のギカイガイドを見ていても、狛江市は議員の人数が品川区と比べれば少ないので、個人名も出して、会派も分けて、意見の分かれた議案や陳情について全員の態度を表示しているのを確認させていただきましたので、そういったところを取り入れるのかなと、どんな検討がされているのかなというところをお聞きしたかったのですけれども、これからということで、分かりました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":39,"id":"exchange-016"},{"speaker":"安藤委員","kind":"質問","question":"先ほど冒頭にせお委員の理由を伺ったのですが、ページ数が多くなるというデメリットが相当あったと思うのですけれども、それは否定しませんが、先ほど何でホームページでの公開というのをしつこく言ったのかと言いますと、例えば討論が行われて、全議員の賛否が明らかになった案件については、ホームページ上に議案と同様に掲載して、ＱＲコードで飛ばすといった工夫だと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":41,"id":"exchange-017"},{"speaker":"せお委員","kind":"意見","question":"先ほどせらく委員のときにお伝えしましたけれども、せっかくアンケートを結構大々的にとったので、基本的にはそのアンケートのご意見を参考にしながら、区議会だよりのリニューアルをこれから検討していくという方向で考えていますので、またその中で、ＱＲコードを使うとか、そういったこともあれば、それは皆さんと検討していきたいと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":42,"id":"exchange-018"},{"speaker":"安藤委員","kind":"意見","question":"分かりました。アンケートもかなり集まったみたいで、大事だと思いますし、また、具体的にこういった陳情という形で区民の方から声が寄せられたということで、こちらのご意見もぜひ参考にしていただいて、よりよい区議会だよりに向けて、検討していただければと思います。私も検討しますけれども、以上です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":43,"id":"exchange-019"},{"speaker":"田中委員","kind":"質問・要望","question":"先般、早稲田大学デモクラシー創造研究所が議会改革度調査で総合評価を発表された中で、品川区は２３区の中で２位だったということで評価をいただいてはいるものの、一方で、全国レベルで比較したらば２６位なので、そういった意味では、議会改革はまだまだすべきだと思っていて、その中で主権者の参画というのが品川区は１２位だったのですけれども、１２位という位置を、これはせお委員はじめ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":46,"id":"exchange-020"},{"speaker":"あくつ委員","kind":"質問・要望","question":"まだまだというお話もありましたが、品川区はかなり進んできている、そのうちの先ほどの順位ですから、かなり進んできているという中で、当然開かれた議会というところで、あらゆる情報を本当は品川区議会だよりに載せたいけれども、どこの部分を議会としてしっかり見ていただきたいのか、限られた紙面の中で何を見せていくのかという中での先ほどのご発言だったと思いますし。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":47,"id":"exchange-021"},{"speaker":"安藤委員","kind":"質問・要望","question":"議会はその最大の任務の結果について、やはり説明責任を果たすべきだと思います。ましてや、今回ありがたいことに、区議会に関心を持っている区民の方から具体的な要望として寄せられたと。議会としてはやはりこれに応えるべきだと思います。したがいまして、採択を主張します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":48,"id":"exchange-022"}]},{"id":"topic-02","title":"令和７年第２回定例会","agenda":"令和７年第２回定例会","exchanges":[{"speaker":"松永委員","kind":"質問・要望","question":"ご説明申し上げます。当会派の木村議員ですが、現在歩行が難しいため、本会議に出席する際は車椅子での入退場を許可していただきたいこと、また、その際、介助員の方からの補助を受けること、そして、採決の際、起立が難しいため、賛成の場合は挙手によるものとしていただきたいと考えています。以上３点をご了承いただきたいと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":60,"id":"exchange-023"},{"speaker":"安藤委員","kind":"質問・要望","question":"子どもの権利条約を踏まえた教育施策の転換が必要だと訴えてきました。教員不足、教員の働き方改革についても伺いましたけれども、濱松氏は、校長・副校長のリーダーシップ、マネジメント強化を何度も強調されておりました。最後に、教育行政で最も大事にすべき子どもの権利条約についても伺ったのですが、この点について明瞭な考えは伺えませんでした。以上の理由から、今回の任命同意に賛成はできません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":67,"id":"exchange-024"},{"speaker":"石田（秀）委員","kind":"確認","question":"松永委員の、木村議員の件はよろしいのだけれども、今、毎回こういうことになるので、どこかのときに、違ったら注意してください。私はこの議運で、正副委員長が案を出して、申合せ確認事項の変更をするということであれば、この中でやれると思う。毎回こうやって言っていただくのは、それはそれで今の状況ではしようがないけれども、申合せ確認事項にそういうことをうたってもいいと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":72,"id":"exchange-025"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7117#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":14187,"voices":82}},{"id":"r07-20250728-6","meetingId":"r07-cm07","date":"2025年7月28日","dateIso":"2025-07-28","committee":"区民委員会","time":"午後 １時００分～午後 ２時３７分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を34件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"令和７年度地域振興基金を活用した区民活動助成制度の審査結果","agenda":"令和７年度地域振興基金を活用した区民活動助成制度の審査結果","exchanges":[{"speaker":"おぎの委員","kind":"質問","question":"ちょうど昨年もこの時期に、こういった報告が上がってきていまして、少し手続のところでお聞きしたいのですが、申請書の提出は事前相談終了後から４月３０日となっていますが、この事前相談というのは、マストになっているのでしょうか。今年の応募状況をお聞かせいただけたらと思います。","respondent":"平原地域活動課長","answer":"こちらの申請要件に当たりましては、その内容と助成金の方法等を説明する意味もありまして、事前相談は必須のものとさせていただいているところです。今年度、相談自体は様々なところから来たのですけれども、実際に進んだところでは、今回の６団体になってあります。","voiceIndex":9,"id":"exchange-001"},{"speaker":"おぎの委員","kind":"質問","question":"事前相談が必須ということで、もう申請を受け付ける時点で、その団体がやりたいことが明確になっているというのは、すごく審査しやすくていいかなと考えています。継続の団体もいらっしゃいますけれども、今回、応募が６団体だったということで、昨年度申請されて、今年継続でまた再度という方はいらっしゃらなかったということなのでしょうか。","respondent":"平原地域活動課長","answer":"今年度、継続というのは、先ほどご説明の中で、例えばチャレンジ助成２年目となっているところが継続ということになりますけれども、継続となっているところにつきましては、昨年度行った成果を踏まえてさらに展開を図っていく意味で、継続となっているところですし。","voiceIndex":11,"id":"exchange-002"},{"speaker":"おぎの委員","kind":"質問・要望","question":"そうですね、しにゃねこっ。の会さんとかやしおぼーずさんとか、昨年からの継続の方が今年度もいらっしゃって、申請がなかったところも、今のお話だと、もう助成金なしで自立してやっていけますという団体もいらっしゃると思いますが、引き続き相談は乗っていただきたいなと考えています。","respondent":"平原地域活動課長","answer":"続きまして、トライ助成のテーマですが、こちらにつきましては、事業所管です地域活動課でテーマ設定しているものですけれども、その年度に様々なお声、あるいは様々な区内の情勢などをこちらで勘案いたしまして、そういった中で、地域課題として困っているところ、あるいは。","voiceIndex":13,"id":"exchange-003"},{"speaker":"おぎの委員","kind":"意見","question":"様々なテーマの案というのが出てきたと思うのですけれども、今年これに決まったということで、やはり困難や生きづらさを抱えている方たちが多いのかなと考えています。引き続き、助成だけでなく、ご相談に乗っていただけたらなと考えています。成果報告会が来年２月１３日ということで、楽しみに参加します。よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":15,"id":"exchange-004"},{"speaker":"こしば委員","kind":"質問","question":"私からは、チャレンジ助成１年目の団体の事業概要についてお聞きしたいのですけれども、子育てをする保護者の方を対象にした事業といいますか、保護者支援のようなことに見受けられたのですけれども、３つ目のところで、後段ですが、「地域や子どもに関わる人材を増やす」ということで、子どもに関わる人材というのは、1)、2)のところでもよくわかったのですが、「地域や」となると。","respondent":"平原地域活動課長","answer":"そういった視点で、こちらにつきましても、「地域や」という、すみません、言葉の書き方につきましては少し分かりづらいところがあるかなと思いますが、いわゆる並列という形ではなくて、様々なものを包含した形で地域というものが入っていると私どもも理解し。","voiceIndex":17,"id":"exchange-005"},{"speaker":"こしば委員","kind":"質問","question":"様々なリスクがありますので、そういったことを防いでいく取組というのは、すごく大切なことだと思うのですけれども、その中でその一つとして、エンタメを活用した取組をしていくということですけれども、このエンタメ、いろいろとツールはあると思いますけれども、公益の観点からしても、その辺との関わり合いといいますか、エンタメというと、どうしても商業的な意味合いにも感じてしまうのですけれども。","respondent":"平原地域活動課長","answer":"そういったところを動機づけ、きっかけみたいな形で、何か興味のあるところで、幅広に興味のあるものを考えていったときに、一つ音楽というものがあったということで、この団体から聞いているところですけれども、そういったものをきっかけに集まるような場を。","voiceIndex":19,"id":"exchange-006"},{"speaker":"こしば委員","kind":"意見","question":"何か歌い手さんが来たり芸人さんが来たり、そういうのではなくて、もっと幅広く、自分たちでそういったエンタメなどを使った取組、交流をすることによって、孤独を感じている方々が、そう感じなくなるようにやるということで、かしこまりました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":21,"id":"exchange-007"},{"speaker":"こんの委員","kind":"確認","question":"要するに、品川区としても持っている課題だし、プレゼンされてくる課題も、いわゆる区とマッチングをしていくというところで採用されていくということなのですが、品川区からぜひご協力くださいという、協力関係の協働事業なのか、それとも、品川区が課題として思っていることについて、この団体のこうした活動は必要だから、どうぞご協力くださいというものなのか、それとも、いやいや、同じ土俵に立って。","respondent":"平原地域活動課長","answer":"これは別に区とその団体という形ではなくて、町会・自治会をはじめとした様々な地域の活動をやっているところと一緒になってやっていくという協働事業の一つと考えていますので、そういう団体を育成していくという方針で進めさせていただいているものです。","voiceIndex":23,"id":"exchange-008"},{"speaker":"こんの委員","kind":"提案","question":"そもそもこの事業は、とても必要な事業だと思っているのです。特にトライ助成などは、区から提案された事業に一緒に、共にやりましょうという、もう既にそういう取組になっていると思うので、そうした活動が、これまでどんなテーマがあって、どういうふうに活動をしてきて、どういうふうに今実績となっているのか、その辺のところも少し教えていただけますか。","respondent":"平原地域活動課長","answer":"あるいは、先ほどご説明させていただきました成果報告会のようなところで、どんな活動をしているのか、あるいは冊子なども作りながら、そういったところを地域にも紹介させていただいているところです。","voiceIndex":25,"id":"exchange-009"},{"speaker":"こんの委員","kind":"質問","question":"どんな状況なのでしょうか。","respondent":"平原地域活動課長","answer":"先ほど委員から、全区的になどという規模の話もございましたが、ＮＰＯとか任意団体のお話でしたら、やはり規模を広げていくというのはなかなか難しい場合もありますけれども、逆に。","voiceIndex":27,"id":"exchange-010"},{"speaker":"こんの委員","kind":"提案","question":"その担い手の一つにもこういうのはなってくるかなと想像するとなると、これは、ここの課長の所管だけでこの団体を終わらせるのではなく、所管とやり取りをして、こういう団体も提案してきていますよ、こういう団体と一緒に活動というのはどうなのでしょうみたいなのは、情報提供を他の所管と連携してというのはされるのですか。その辺はどうなのでしょう。","respondent":"平原地域活動課長","answer":"もちろんそこはＮＰＯを育成するというか、そういう活動を支援する場といったところでは、その後ということが重要ですので、様々な所管と連携しながらやらせていただいておりますし、その所管でやっているところが新たな視点での事業をやっていきたいといったときに。","voiceIndex":29,"id":"exchange-011"},{"speaker":"こんの委員","kind":"提案","question":"区民の方というか団体の方の目線で、品川区民の方が何に困っているのかという、そうしたところの提案をいただくというのは非常に大事だと思いますし、区からのお願いの課題だけではなくて、提案をしていただいたことを、その団体がやりやすいようにその活動をしていただくという、これも非常に大事なものだと思うので、ぜひ、その団体が思っている、また考えている課題を、品川区としては活用するという形で。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":31,"id":"exchange-012"}]},{"id":"topic-02","title":"臨海斎場の火葬料・使用料改定","agenda":"臨海斎場の火葬料・使用料改定","exchanges":[{"speaker":"こんの委員","kind":"確認","question":"何点か式場のことをお聞きしたいと思います。それから、２階に式場となると、式を終えて火葬場に行くときの移動というのは、２階から大丈夫なのですかというところだとか、使い勝手の部分を確認させてください。","respondent":"築山戸籍住民課長","answer":"火葬待合室が多い時間帯は昼間なのですけれども、式場の利用が終わった後は、火葬待合室として利用できるように、また貸出しを開始するので、そういったところで十分回る体制になっているところです。","voiceIndex":36,"id":"exchange-013"},{"speaker":"こんの委員","kind":"質問","question":"分かりました。昨日、私、臨海斎場でご葬儀がありまして、２階も上がったので、大丈夫なのかなと、現地も見ながらだったので思ったのですが、こういう改定を出すぐらいですから、もう当然それは稼働、また使っていけるということで、そうなっているというのは分かったのですけれども、エレベーターの工事もしながら、いわゆる出棺するときの移動も大丈夫だといったところなので、よく分かりました。","respondent":"築山戸籍住民課長","answer":"そういった状況を踏まえて、今回、式場も、家族葬ですとか小規模の方、１日で終えたい方向けに貸し出すということで、設定したものになっております。","voiceIndex":38,"id":"exchange-014"},{"speaker":"高橋（伸）委員","kind":"質問","question":"当然、ペットも家族だという方が、一定いらっしゃるわけではないですか。区にもそういった動物炉に関してのお問合せがあるかと思うのです。そういう意味合いを含めて、今質問させてもらったのですけれども、それは分かりました。既存のエレベーター工事があって、これから式場が増設になるわけではないですか。その増設に関わる５区の負担額というのは、どういう割合になっていますかね。教えてください。","respondent":"築山戸籍住民課長","answer":"負担の割合につきましては、火葬場、式場の利用割合に応じた負担という形で、負担しています。今回のエレベーターの改修経費につきましても、こういった積み立てたものから切り崩して対応しています。","voiceIndex":43,"id":"exchange-015"},{"speaker":"高橋（伸）委員","kind":"質問","question":"そうすると、令和６年度だと、この５区の割合から言うと、大田区の次に品川区ではないですか。２番目だから、負担も順繰りに大田区、品川区という考え方でよろしいわけですよね。","respondent":"築山戸籍住民課長","answer":"そのとおりです。","voiceIndex":45,"id":"exchange-016"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"すみません、最後にもう１点ですが、臨海斎場のアクセスのことです。これ、区として今後、臨海斎場の需要が増える中、これからどういう要望なり、バス事業者なり、大井ルートとかいろいろあると思うのですが、特に高齢者の方だと、やはり臨海斎場までのアクセスが悪い中、今後どういうふうに考えておられるのかというのを、ぜひお聞きしたいと思います。","respondent":"築山戸籍住民課長","answer":"アクセスにつきましては、昨年度の区民委員会でもご要望をいただきまして、組織区の品川区として、臨海斎場のアクセスについて引き続き検討してほしい旨、要望しています。","voiceIndex":47,"id":"exchange-017"},{"speaker":"おぎの委員","kind":"質問","question":"私から１点だけお聞きしたいのですが、臨海斎場は増築計画を今進められていらっしゃると思うのですけれども、品川区内のあちこちで、工事現場等でも、資材の高騰であったり現場の働き方であったりして、工期が延びる例というのが散見されますが、臨海斎場に関しては、今の計画に特に変更は今のところ出ていないのか、今の進捗等を少しお聞かせいただけたらと思います。","respondent":"築山戸籍住民課長","answer":"現在の工事の進捗です。臨海斎場からは、もともとの計画の変更があるということは聞いておりません。現在は基本設計を行っている段階です。基本設計の案ができましたら、区民委員会でもご報告させていただきたいと考えております。","voiceIndex":51,"id":"exchange-018"},{"speaker":"せらく委員","kind":"質問","question":"私からは火葬料に関してお伺いしたいのですけれども、令和８年度に料金改定は行わないことにするということで、３年を目途に定期的に見直しを図ることと書かれていますが、前回が令和５年度ということで、その令和５年度のときは料金の変更というのはどの程度だったのか、教えてください。","respondent":"築山戸籍住民課長","answer":"前回の改定のときは４万円から４万４,０００円に値上がりをしております。","voiceIndex":55,"id":"exchange-019"},{"speaker":"せらく委員","kind":"質問","question":"この火葬料金改定の概要の（２）番のところで、年間火葬経費は、年間火葬料収入に掛ける改定率となっている計算式を見ると、年間火葬料収入というのが経費を上回っているという事情であるのでしょうか。","respondent":"築山戸籍住民課長","answer":"委員のおっしゃるとおり火葬件数が増えておりますので、その分、火葬料収入も増えているというところで、前回４万円から４万４,０００円に値上げしておりますので、そこで現在の経費は賄えているという状況です。","voiceIndex":57,"id":"exchange-020"},{"speaker":"せらく委員","kind":"質問","question":"コスト削減ということも具体的に教えてくださって、理解しました。それで、今後ですけれども、令和１２年度から式場も火葬炉も増えるということで、そこに向けて区民負担というところの見通しというか、想定はいかがでしょうか。","respondent":"築山戸籍住民課長","answer":"組織区としては、区民負担が増えないようにということで考えておりますので、なるべく無駄なコストが発生しないように確認をしてまいりたいと考えています。","voiceIndex":59,"id":"exchange-021"},{"speaker":"藤原副委員長","kind":"質問","question":"他施設の比較で、民間は９万円から１６万円と出ているではないですか。臨海斎場が４万４,０００円、収骨容器を含めてだから、こういうふうに比べれば安価でしょうというお話になるかもしれないけれども、私は、東京都という意味においてはどうだったのかなと。こういうところに行政というのは、やはり富の再配分ということに関しても、私はお金を入れていくべきだと思うのですけれども、いかがですか。","respondent":"築山戸籍住民課長","answer":"ただ、先ほどのご質問でも回答させていただいたのですけれども、区民の負担が大きくならないよう、区としましてはしっかりと確認をしていきたいと考えています。","voiceIndex":62,"id":"exchange-022"},{"speaker":"藤原副委員長","kind":"質問・要望","question":"そうなのですよ。だけれども、私が言いたいのは、公営に関しては、限りなく無料にしていくべきではないかということなのです。埋葬法だと、少し細かく言えばというのがあると思うのですが、ほとんどの方が、もう１００％近く火葬を今するわけですから、その辺について、やはり根本ですよね、物の考えの。決算特別委員会でしたいので、これでこの質問はもうしませんが、その辺についていかがですか。","respondent":"築山戸籍住民課長","answer":"できれば安く火葬ができるなら、それに越したことはないと思いますので、引き続き組織区として、臨海斎場の運営状況を厳しく確認しながら、無駄なコストが発生しないよう、火葬料に転嫁されないよう、そういったところは見ていきたいと考えております。","voiceIndex":64,"id":"exchange-023"}]},{"id":"topic-03","title":"窓口の利便性向上の取り組みと日曜開庁の運用変更","agenda":"窓口の利便性向上の取り組みと日曜開庁の運用変更","exchanges":[{"speaker":"こしば委員","kind":"質問・要望","question":"その上で質問したいのですけれども、電子申請の中で転出届の割合が出ていたのですけれども、それ以外の手続の割合というのは書かれていなかったので、そのあたりを教えていただきたいと思うのですけれども、お願いします。","respondent":"築山戸籍住民課長","answer":"一方、転入・転居ですとか印鑑登録といった手続につきましては来庁が原則になっておりまして、来庁しなければできない手続となっているため、こういった電子申請に対応していないため、こちらの資料には書いていないものとなっております。","voiceIndex":70,"id":"exchange-024"},{"speaker":"こしば委員","kind":"質問","question":"そうすると、１ページ目の（３）電子申請の導入の1)の後段のところは、来庁することが原則という認識でよろしかったのですか。今の話だと、電子申請だけど来庁しなければいけないのかというふうにも捉えてしまったのですけれども。それも何か矛盾しているのかなという気がするのです。でも、来庁しなければいけませんと今おっしゃったので、おかしくないかなと。","respondent":"築山戸籍住民課長","answer":"手続の種類によって、電子申請ができるものとできないものがありまして、できるものとしては転出届、これは電子申請ができるものになっております。","voiceIndex":72,"id":"exchange-025"},{"speaker":"こしば委員","kind":"質問・要望","question":"それで、「行かない窓口」のところで、転出の話なのですが、ホームページを見ましたら、「行かない窓口」で申請をして、出来上がった書類が今度、郵送で送られてくると思うのですが、郵送代金というのはしばらくの間取らないようなことが書かれておりますけれども、その辺、恒久的というような方向なのか、当面の間なのでまだ分からないのですが、区の考えについて少し教えていただきたいと思います。","respondent":"築山戸籍住民課長","answer":"今後の考え方としましては、郵送請求の場合は、やはり遠方にいるですとか、マイナンバーカードを持ってないですとか、あとはマイナンバーカードを使えない士業の方、そういった方が使うととても便利なサービスなのですけれども、一般の区民の方につきましては。","voiceIndex":74,"id":"exchange-026"},{"speaker":"こしば委員","kind":"質問","question":"いずれにしても、こういった「行かない窓口」と、また実際に行って手続をする流れもあると思うのですけれども、そうなると、数字からでも「行かない窓口」、要は行かないで手続をする方も、大変パーセンテージも増えていく中で、職員の仕事というのも、恐らく窓口の方、会計年度任用職員の方かどうか分からないですけれども、そういった方が実際の窓口業務以外にも。","respondent":"築山戸籍住民課長","answer":"やはり亡くなられる方が増えているのに伴い、相続に関して、昔の書類、昔の戸籍が欲しいといったような相談ですとか、ＤＶですとか虐待等により住所を知られたくないという方への対応、そういった相談の対応が必要になってきておりまして。","voiceIndex":76,"id":"exchange-027"},{"speaker":"こしば委員","kind":"質問・要望","question":"平日に結構込み入った案件にきちんと対応されるケースもたくさんあると思いますが、そこに注力していただければ、また区民の利益につながってくると思いますし、またオンラインの申請も当然扱わなければいけないというところでは、統計なども取っていると思いますけれども、また、これは人事の話にかかってくるかもしれませんけれども、その辺は柔軟に取り入れていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":78,"id":"exchange-028"},{"speaker":"こんの委員","kind":"質問・要望","question":"先ほどこしば委員が質問されていた点を確認したいのですけれども、このキャッシュレス化の推進というところでの米印の案件ですけれども、そうなると、一番このことで要望されていた士業の方が、毎年予算要望などされていたと思うのですが、その方たちの負担軽減という理解でよろしいかというのが１つと、また、この士業の方たちへの周知というのは、８月１日からですから。","respondent":"築山戸籍住民課長","answer":"郵送請求のキャッシュレス化につきましてです。これについては、士業の方も負担軽減につながるものです。それから、周知につきましては、広報しながわですとかホームページ等でご案内をしていく予定です。","voiceIndex":80,"id":"exchange-029"},{"speaker":"こんの委員","kind":"質問・要望","question":"あえて今までお声を上げてきたところにお知らせをして差し上げるというところも、あってもいいのかなと思いますので、どうかお声が上がってきた、そういう要望が上がってきた士業の方たちに、直接そうしたこともアナウンスをしていただきたいなと要望いたしますが、いかがでしょうかということと、第２と第４、よく分かりました。そういうことですよねということで。先ほどの要望についてはいかがでしょうか。","respondent":"築山戸籍住民課長","answer":"要望のあった団体についての周知については、検討してまいります。","voiceIndex":82,"id":"exchange-030"},{"speaker":"高橋（伸）委員","kind":"意見","question":"荏原第一地域センター管内の１４の町会・自治会に関しては、地域活動課とも恐らく連携しないと、周知という部分でいうと、皆さんに、日曜開庁が今度月２回になるというのがやはり伝わり切らないと思うので、この周知に関して、地域センターに関してはどういうふうに周知していくのか、改めてお聞かせ願いたいと思います。その辺についてお尋ねしたいと思います。","respondent":"築山戸籍住民課長","answer":"地域センターにつきましては、地域の状況もあるかと思いますので、周知につきましてはまたどうするか検討していきたいと思います。","voiceIndex":85,"id":"exchange-031"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"やはり転入という部分が今一番というのは、おっしゃるとおりだと私は理解したのですけれども、その管内で利用される、日曜日にしか行けない人も多分来ると思うので、ぜひ地域の方にも、町会長も含めて周知徹底をお願いしたいと思います。これは要望でお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":87,"id":"exchange-032"},{"speaker":"藤原副委員長","kind":"質問","question":"今までのすばらしい質疑とは真逆になってしまうのですが、何でやめてしまうのですか。よかったのですよ。いきなりこうやって出たわけではないですか、区民委員会で、もう第２と第４しかやらないと。来庁者が減っているからといっても、これ、グラフを見て、２万人以上来ているわけではないですか。なぜかといったら、土曜開庁もどうですかと言いそうになってしまったもの。いかがなものなのでしょうか。","respondent":"築山戸籍住民課長","answer":"これを、今回、第２・第４に変更することによって、それが６位という位置づけになります。それでも２３区の中では上位というところで、やはり副委員長がおっしゃられたとおり、品川区は２３区の中でも、非常に窓口という面で充実してやってきたところです。","voiceIndex":89,"id":"exchange-033"},{"speaker":"藤原副委員長","kind":"質問","question":"入れていないのですね。日曜開庁を始めたときは、課長ではない理事者の方、歴代の方たちも、すごくこの日曜開庁ということに自信を持ち、誇りを持っていた施策の一つだと思うので、急に第２・第４にという話が出てしまうと、そうですかと何か寂しい思いがしたので、こういう質問をさせていただきました。決算特別委員会で思い切りまたさせていただこうと思いますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":91,"id":"exchange-034"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7123#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":31419,"voices":102}},{"id":"r07-20250728-7","meetingId":"r07-cm07","date":"2025年7月28日","dateIso":"2025-07-28","committee":"厚生委員会","time":"午後 １時００分～午後 ２時３４分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を37件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"令和７年陳情第２６号 重度障害者を受け入れて経営が立ち行かなくなったGHはありません 厚生委員会等において事実に基づく答弁をするよう区に求める陳情","agenda":"令和７年陳情第２６号 重度障害者を受け入れて経営が立ち行かなくなったGHはありません 厚生委員会等において事実に基づく答弁をするよう区に求める陳情","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"ここの陳情で書かれている下から２段目の、そもそも、障害者グループホームは重度対象のケアホームをほとんど整備されなかったため、国が必要性の高い重度障害者の利用を促すための助成金制度を作ったことにより、ここ数年で増えてきたもので、経営がたちゆかなくなった事例は聞いたことがありませんというふうなことで書かれているのですけれども。","respondent":"佐藤障害者施策推進課長","answer":"こういったところで重度の方の受入れを見越して、国のほうも制度づくりは進めているのかというふうに認識しています。","voiceIndex":6,"id":"exchange-001"},{"speaker":"鈴木委員","kind":"質問・要望","question":"実際に品川区もそういう形で重度の方の受入れに対して支援金を出す、それから、居住支援を出す、そういうふうなことで区独自の対策をとっていますけれども、本当に重度障害者の方々が入れるグループホームを、私も何度もここの場でも、計画的に区としても整備をぜひしていっていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":8,"id":"exchange-002"},{"speaker":"吉田委員","kind":"質問・要望","question":"国としても、一番求められている重度のグループホームがなかなか立ち上がらないとなると、やはり運営が大変だからです。誰が考えても分かる。今のお話だと、いきなり政策制度の中身に入られましたけれども、この陳情が求めているのは、過去のご答弁の根拠はあったのかなかったのか、根拠があったのだったら、それを示してほしいということだと思うのですけれども、いかがでしょうか。","respondent":"佐藤障害者施策推進課長","answer":"このときの答弁につきましては、この一文の中で、事例がということで報道でもあったというようなところで、簡潔、かつ、最初にご説明したようなところの中で、ご質問に対する答弁の趣旨として、必要な範囲で簡潔に答えるというようなところの中で。","voiceIndex":10,"id":"exchange-003"},{"speaker":"吉田委員","kind":"確認","question":"結局、その当時のご答弁の根拠はあったのかなかったのかだけ伺いたいのですけれども、その当時、答弁をなさった根拠の報道が、具体的にどの報道かということを端的にお答えいただければ、この陳情者の疑問も解けるでしょうし、私としても、やはり行政としては、きちんと根拠を持った答弁をされているのだなということが確認できるので、この陳情者にも説明できると思うのですけれども。","respondent":"佐藤障害者施策推進課長","answer":"この事例に関しましては、そういうことで根拠というか、こういった事例を踏まえてお話ししたところになりますが、こちらの陳情の方の対応につきましては、テレビや新聞、インターネット等、様々なメディアから報道されていたものということで。","voiceIndex":12,"id":"exchange-004"},{"speaker":"吉田委員","kind":"確認","question":"要するに、この当時のご答弁が、重度の方を受け入れたからというより、重度の方を受け入れた経営の何かで不正請求とかがいろいろあって、様々な要因があって立ち行かなくなったということを、すごく省略して、重度の人を受け入れたがために立ち行かなくなった事例があるというふうなご答弁をされたということなのでしょうか。ごめんなさい、繰り返しになっていますけれども、確認させてください。","respondent":"佐藤障害者施策推進課長","answer":"こちらの答弁の趣旨ですけれども、先ほど申し上げましたが、重度の受入れにつきましてご質問を受けまして、重度の受入れを進めていく一方で、重度の方を受け入れて、それから事業が廃止された施設もあるので、質の担保、チェック体制をきちんと行っていくという趣旨で。","voiceIndex":14,"id":"exchange-005"},{"speaker":"吉田委員","kind":"質問・要望","question":"分かりました。やはりそういう誤解を招くようなご答弁は、今後よく考えて答弁していただきたいと思います。その７区についても教えてくださいと、それだけのことだったと思うのです。７区をその時点でお答えいただければ、もう十分だったのではないかなと思うのですけれども、それがお答えいただけなかったのは、なぜなのかも教えていただきたいと思います。","respondent":"佐藤障害者施策推進課長、松山障害者支援課長","answer":"ということで、根拠資料等の提出ということで求められたものについては、答えを避けたということではなく、そういった形で入手した情報なので、手持ちで持っている資料としては。先ほどご説明させていただいたように、障害者グループホーム条例に関したことだけではなくて、２月２５日の厚生委員会でご審議いただきました４つの条例、心身障害者福祉会館条例、知的障害者福祉施設条例。","voiceIndex":16,"id":"exchange-006"},{"speaker":"吉田委員","kind":"質問","question":"参考資料として、その当時のひがし委員の発言が引用されていますが、グループホーム条例について質問されていると思うのです。別に７区ぐらいですから、口頭で言われても議事録に残りますから、あとでこちらで調査するとかということも可能だと思うのですけれども、それをお答えいただけなかった理由があれば教えてください。","respondent":"松山障害者支援課長","answer":"そのため、当時は、こちらのほうで概略を確認させていただきましたので、そのことがどこに対応しているのかというところまでは、あくまでもこちらの認識の中で対応させていただきましたので、回答を差し控えさせていただきました。","voiceIndex":19,"id":"exchange-007"},{"speaker":"吉田委員","kind":"質問","question":"それを契約関係は対等だからというふうに言われてしまうのは、少し納得がしがたかったというふうに思いますし、私もそれはまだ対等とは言えない、選ばれなければいけないわけですから、そこを選ぶのであれば、やはり区長の責任でそこに委任するなり、品川区が直接に関与するなり、そういう関係が必要なのではないかということが大もとの、この陳情に至る前の大もとのところなのですけれども、それについて。","respondent":"松山障害者支援課長","answer":"確かに区立は安心して入れるということで、皆さん、かなり応募が多いですので、今後もグループホームの整備につきましては、やはり重度の方も入れるようなグループホームの設置ということで整備していく所存ですし、できる限りの希望に沿って、残念ながら、今回。","voiceIndex":21,"id":"exchange-008"},{"speaker":"吉田委員","kind":"質問・要望","question":"立ち戻りますと、そもそも今回の陳情の趣旨は、そういうことがきちんと分かるような、きちんとした答弁をしてほしいということを求めておりますし、私もずっと、過去、議員になった当初に、何かそういえば、あれは障害者福祉課といったときの情報提供のことについて、やはり正確な事実に基づいた答弁を求めるということを、その当時は総務委員会にかかったのだと思うのですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":23,"id":"exchange-009"},{"speaker":"えのした副委員長","kind":"意見","question":"本日結論を出すということで、不採択です。理事者のご説明にもありましたとおり、答弁の内容が誤って受け止められないように説明をしていくと発言もありましたし、私たち会派も、区民の方には分かりやすく、誤解のないように、より丁寧なご答弁をお願いいたしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":26,"id":"exchange-010"},{"speaker":"大倉委員","kind":"質問","question":"今、一通りお話を聞いた上で、一定、私自身も理解したところと、やはり答弁等、議会の質問等、様々見ていても、多少ずれがあることが出てきてしまうというのは、過去いろいろなところでもあって、当然、答弁もより丁寧にしていただくということとあわせて、私たちもしっかり齟齬がないような聞き方をしていくということが改めて必要だなと思いましたので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":27,"id":"exchange-011"},{"speaker":"あくつ委員","kind":"確認","question":"理由としては、先ほどの質疑を拝聴していて、あと、ご説明も拝聴していて、あとは議事録を全部読ませていただいて、前後関係も確認させていただいて、一定の合理性があるということです。それと、この議論に、１月２０日もしくは次の２月２５日に参加されていた鈴木委員のほうからも、そういう、少しこの陳情の趣旨とは違う文脈の中でのお話だということも先ほどお話がありましたので、不採択とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":28,"id":"exchange-012"},{"speaker":"鈴木委員","kind":"質問","question":"本当に理事者の方の正確な答弁ということは前提であるべきだと思いますけれども、ここで取り上げられた文言が、ここの文書の一番下から３行目のところにあるような、重度障害者が入居したら経営が大変になるから、重度障害者を入居させることは困難という誤った発言であり、公正な審議をゆがめるものですというふうなことで断定されていますけれども、そういう発言ということではないと思いますし。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":29,"id":"exchange-013"},{"speaker":"吉田委員","kind":"質問・要望","question":"本日結論を出すで、採択をお願いいたします。行政が間違った情報を出してくるということは想定していないと思いますので、その点は、今も頑張っておられることは、今日の質疑の中では、一定、確認できましたけれども、やはりこれがあること自体は、あってはならないことかなというふうに思いますので、ぜひ採択とさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":32,"id":"exchange-014"},{"speaker":"やなぎさわ委員","kind":"意見","question":"本日結論を出すで、不採択でお願いいたします。ただ、やはり、この陳情にあるように、この文章だけ見てみると、正確さは欠けているのは間違いないかなというふうに思いますので、ほかの委員がおっしゃるとおり、やはりなるべく分かりやすい正確な答弁をしていただければなというところで、これを１つ教訓にしていただければなというところで、私は、不採択にします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":33,"id":"exchange-015"}]},{"id":"topic-02","title":"シルバー成年お祝い事業の実施","agenda":"シルバー成年お祝い事業の実施","exchanges":[{"speaker":"鈴木委員","kind":"質問","question":"今度、フレイル予防フェスタ内にシルバー成年お祝いブースを設けるということなのですけれども、昨年度からの新規事業ということなのですけれども、このフレイル予防フェスタというのは、どのような中身で、どういう経過でされることになったのか、その中身についても教えてください。それから、昨年の新規事業ということで、参加者がどれくらいだったのかということも教えてください。","respondent":"樫村高齢者地域支援課長","answer":"フレイル予防フェスタの中身等々についてですけれども、昨年度の実施の実績ですが、例えば、フレイル予防フェスタということで、名前がフレイルということでついておりますけれども、フレイル予防の講演会ですとか、耳の聞こえの講話、それから、体力の測定会。","voiceIndex":44,"id":"exchange-016"},{"speaker":"大倉委員","kind":"質問","question":"いろいろご説明いただいて、予算的には、どのくらい変わったのでしょうか。その辺、教えていただければと思います。","respondent":"樫村高齢者地域支援課長","answer":"その中から、今回、シルバー成年お祝い事業を実施いたしますので、そちらが約２００万円ほどを予定しておりますので、半分ほどの予算でこちらを実施できるような形で今考えております。","voiceIndex":48,"id":"exchange-017"},{"speaker":"大倉委員","kind":"意見","question":"前年度とかに比べると、増えてきているというところでは、多くの方のご参加ということなのかなと思いますので、できるだけ、これは目的としては、多くの方に参加していただくということが、フレイル予防も含めてしていただくということなので、いろいろ工夫して、また参加者数が増えるようにご努力いただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":50,"id":"exchange-018"},{"speaker":"やなぎさわ委員","kind":"質問","question":"来場者数のパーセンテージ、令和５年、６年が出ていて、私も厚生委員会だったので参加させていただいたのですけれども、それ以前とかは、コロナ禍とかも入っていたと思うのですけれども、その辺りの経過は、令和５年より前はいかがだったのでしょうか。開催していたのかということも含めてお伺いしたいと思います。","respondent":"樫村高齢者地域支援課長","answer":"令和５年度以前の参加者数ですけれども、冒頭でもご説明したのですが、記録が残っているのが平成１７年度以降になりまして、一番多いのが平成１７年度の参加者数が１,１８０名、参加率が３３.１％というのが、データが残っている中で一番多い参加率でございまして、その後。","voiceIndex":52,"id":"exchange-019"},{"speaker":"やなぎさわ委員","kind":"確認","question":"それと確認なのですけれども、去年とかに実施していた、シルバー成年式のときにやっていたシルバーフェスタというふうに会場の別室でやっていたようなものが、今回はそれをフレイル予防フェスタにして、それをメインにして、シルバー成年お祝いブースみたいなものを逆に小さくしてというような、入れ替えるような感じのイメージでよろしいですか。","respondent":"樫村高齢者地域支援課長","answer":"今、委員ご指摘のとおり、形をある意味逆に変えて、フレイル予防フェスタをメインにして、メインといいますか、会場自体をメインにしまして、その一角にシルバー成年お祝い事業のブースを設けて実施するという形で考えてあります。","voiceIndex":54,"id":"exchange-020"}]},{"id":"topic-03","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"あくつ委員","kind":"意見","question":"私も拝見したのですけれども、実は私、今年、この大府市へ行ってきたのですが、いわゆる特定目的会社をつくって跡地活用、所管は違いますけれども、おおぶ文化交流の杜というものをやっている。それもお願いしたのですけれども、それはもう視察が殺到していてと断られたのです。すみません、無理なことを言って。事前に申し上げていなかった。すみません。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":59,"id":"exchange-021"},{"speaker":"鈴木委員","kind":"質問","question":"ここは高齢者のところばかりなのですけれども、しかも、２日目は１日あるわけではないですか。そのところを１か所だけというのは、少し少ないのではないかと思うのです。だから、この愛知県の中で何があるか分からないのですけれども、障害者の福祉のところで、先進的なところがあったら、ぜひそういうものもご検討いただけないかなと思うのですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":65,"id":"exchange-022"}]},{"id":"topic-04","title":"その他","agenda":"その他","exchanges":[{"speaker":"あくつ委員","kind":"確認","question":"ご報告ありがとうございました。非常に先駆的な取組だと思うのですけれども、たしかあのときに、いわゆる配送された側が困惑をしないようにということで、コールセンターをつくるという話もあったと思うのですが、それがどうなっているのかということと、入札をされて、どこの事業者に決まったのかということと、何を配るのか、もう１回、細かく確認させてください。","respondent":"菅野高齢者福祉課長","answer":"こういった形で、ヤマト運輸に決まりましたということです。そして、コールセンターの設置ですが、予定どおり、８月１日からコールセンターは設置させていただきまして、１０月３１日までという予定で考えております。","voiceIndex":73,"id":"exchange-023"},{"speaker":"鈴木委員","kind":"質問","question":"一斉に配るといっても、どれくらいの日にち、どれぐらいの日程で、区内全域が１回目を配れるのか、どこら辺の地域からということはあるのか、その点、教えてください。","respondent":"菅野高齢者福祉課長","answer":"具体的には、２０か所の拠点があって、顔なじみの配達員が配達するというお話をさせていただいたのですけれども、それぞれの拠点で、通常の業務の中に配達を組み入れるという形になっておりますので、区内で一斉に配布が始まるという形になります。","voiceIndex":78,"id":"exchange-024"},{"speaker":"鈴木委員","kind":"質問","question":"区内で一斉に始まるけれども、大体２０か所で全ての高齢者、８万人ぐらいの高齢者に、世帯数だともう少し少なくなると思うのですけれども、配れるのが、約１か月かかるというふうに考えるという感じですか。","respondent":"菅野高齢者福祉課長","answer":"やはり不在時の再配達なども含めまして、何回か不在の場合には行ってくれるというお話もありますので、約１か月かけて、通常の配達のものの中に組み入れてという形で回ってくれるというふうには聞いております。","voiceIndex":80,"id":"exchange-025"},{"speaker":"吉田委員","kind":"確認","question":"今、通常の業務の中でとおっしゃったのですけれども、再配達のときは、こちらから連絡するではないですか、いついつならいますみたいな、そういう形になるのか。その辺について確認させてください。","respondent":"菅野高齢者福祉課長","answer":"１回不在になると、不在票が必ず入っておりますので、そこにドライバーとかサービスセンターの連絡先がありますので、そちらのほうに連絡していただいて、再配達してもらうという形になります。","voiceIndex":84,"id":"exchange-026"},{"speaker":"吉田委員","kind":"確認","question":"分かりました。カメラつきのインターホンとかをお使いだと、割とそういうものをカメラの前に出すとかということもあると思うのですけれども、その辺について、周辺ではみんな心配しているのですけれども、もし、こういうことで信頼をきちんと確認しますみたいなお答えがあれば、伺いたいと思います。","respondent":"菅野高齢者福祉課長","answer":"この中で、それプラス、やはりこれだけ宅配便がすごく地域に定着しているという部分で顔なじみ、できるだけ限られた担当エリアに同じ宅配の配達員が行くというような仕組みになっていて、より顔なじみだというところが一番、決め手の１つとなりましたので。","voiceIndex":86,"id":"exchange-027"},{"speaker":"やなぎさわ委員","kind":"質問","question":"この宅配事業に併せてアンケートも実施するというふうに伺っておりますけれども、アンケートの内容とか、アンケートのとり方とかという、具体的にもし、事業者の選定が決まったということで、何か進んだことがあれば、御報告をお願いします。","respondent":"菅野高齢者福祉課長","answer":"このアンケートの内容は、今ちょうど事業者と最終的に詰めているところではあるのですけれども、こちらからお願いしたい内容としては、例えば、「夏の間にクーラーを使用していますか」というところで、「毎日使用している」とか。","voiceIndex":89,"id":"exchange-028"},{"speaker":"やなぎさわ委員","kind":"意見","question":"分かりました。ヤマト運輸、２０か所ほど拠点があるというようなお話しだったと思うのですけれども、大体ですけれども、どれぐらい、この事業で動く人員の方が、人数とか、職員の方が、ヤマト運輸で関わってくれるのか、もし大体でお分かりになれば。","respondent":"菅野高齢者福祉課長","answer":"具体的な人数はというところはあるのですけれども、ただ、品川区内におけるヤマト運輸の事業規模としましては、ドライバーが３３７名、稼働車両数が１７０台、年間取扱個数が１,２００万個、営業所が２０拠点ということですので、通常の業務の中で。","voiceIndex":91,"id":"exchange-029"},{"speaker":"やなぎさわ委員","kind":"意見","question":"分かりました。１回目が８月１日から始まって、２回目が９月１日からだと思うのですけれども、再配達とかの兼ね合いも出てくると思うので、１か月丸々かけて１回目の配達を行うというよりは、ある程度、２週間とか３週間とかにするのかなと思うのですけれども、そういうことを考えている、１か月かけて１周を回るというような想定でいらっしゃるのか。","respondent":"菅野高齢者福祉課長","answer":"その辺りのところは、配達状況に応じてというところもあるとは思いますが、一応、うちの仕切りとしては、１か月、８月は第１回目、２回目が９月からというふうに、配布の開始をしてくださいねというふうにお願いをしているので、その仕様の中で対応してくれるのだと思います。","voiceIndex":93,"id":"exchange-030"},{"speaker":"やなぎさわ委員","kind":"質問","question":"少し細かいことを聞きます。例えば、１回目が８月の下旬ぎりぎりに配られて、２回目がもう９月の上旬で、物すごい短いスパンで１回目と２回目がという可能性もあるのか、その辺はいかがですか。","respondent":"菅野高齢者福祉課長","answer":"もちろん１回目と２回目が期間があまりに短いと、２回目のところで「この事業が効果的だったか」とか、「熱中症を気をつけてくれたか」とか、そういうようなこともお聞きする項目があるので、短いとあまり意味がないので、二。","voiceIndex":95,"id":"exchange-031"},{"speaker":"大倉委員","kind":"質問","question":"荷物が受け取り拒否とか、結局、再配達を何度してもという場合のことも課題の１つだったかと思うのですが、その辺はどういうふうになったのか、決まっていれば教えてください。","respondent":"菅野高齢者福祉課長","answer":"受け取り拒否というふうにコールセンターのほうに、そういったお問合せがあった場合には、そういった方には、無理にお届けするのもなというところで、せめて飲料だけでもというような臨機応変な対応はしつつ、無理にアンケートをとるとか。","voiceIndex":99,"id":"exchange-032"},{"speaker":"大倉委員","kind":"質問","question":"分かりました。そのとき、コールセンター等に来たときには、そういった、例えば、受け取りはいいですというときに、電話をいただけるので、アンケートだけでも協力とかということをしていくということも考えられるのですかというところと、余った飲料とか、残った飲料はどうなるのでしたか。","respondent":"菅野高齢者福祉課長","answer":"余った飲料ということで、今、約３万６,６００世帯にということで、そういった数の飲料の確保をしておりますので、何回か再配達の訪問をしてくれるとはいえ、一定数、やはり住基上あるけれども、もうそこには居住実態がないとか。","voiceIndex":101,"id":"exchange-033"},{"speaker":"大倉委員","kind":"意見","question":"分かりました。コールセンターのところも、答えてもいいよという方とか、コールセンターにこちらだけでも答えていただけますかとか、そういうような促しに取り組んでいただければというところと、あと、飲料については、効果的に活用ということなので、どうしても受け取ってもらえないで余った場合には、ぜひいろいろなところで、廃棄にならないで使っていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":103,"id":"exchange-034"},{"speaker":"あくつ委員","kind":"確認","question":"今の大倉委員の質問に少し重なるのですけれども、もう１回確認。","respondent":"菅野高齢者福祉課長","answer":"今回の事業が熱中症予防と見守り支援という両面の側面がありますので、なかなかこういった場で、そういった場合には置き配も可能というのは、なかなか言いづらいところはありますが、実態としては、そういうご希望の方には。","voiceIndex":104,"id":"exchange-035"},{"speaker":"えのした副委員長","kind":"質問・要望","question":"一応やはりドアを開けるときも心配で、チェーンをしながら、どうしようかなと、「どちらのあれなのですか」と言ったら、「委託業者です」という話だったので、ヤマトは、そういった委託にお願いしているケースがあるのか、今回そういうものがあるのか、やはり顔見知りというので、私も地域だと顔見知りの方で、歩いているだけでも「お疲れさま」などと挨拶ができるので安心感はあるのですけれども。","respondent":"菅野高齢者福祉課長","answer":"インターホン越しのやり取りというお話がありましたけれども、例えば、先ほどのアンケートも、インターホン越しでアンケートに答えたいという方も、その辺りも対応はしたいなと考えています。","voiceIndex":108,"id":"exchange-036"},{"speaker":"えのした副委員長","kind":"意見","question":"これで私も安心して、電話だけではなく。そうすると、今度、インターホン越しではなくて、ドア越しでも、例えばインターホンがないご自宅ですとか、そういったところでも、やはりせっかくのアウトリーチで、お会いはできなくても、お声を聞けて、健康だなとか、お元気だなということが分かればと思いますので、ご対応していただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":110,"id":"exchange-037"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7121#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":28410,"voices":113}},{"id":"r07-20250728-8","meetingId":"r07-cm07","date":"2025年7月28日","dateIso":"2025-07-28","committee":"建設委員会","time":"午後 １時００分～午後 ２時４０分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を40件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"令和７年８月都営住宅入居者募集","agenda":"令和７年８月都営住宅入居者募集","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"参考のところなのですけれど、募集回によって倍率に随分差があると思うのですが、その理由について区としてはどんなふうに考えていらっしゃるのか伺いたいと思います。","respondent":"川原住宅課長","answer":"この辺りの倍率は不明ということで、分かるもののみを記載している形です。必然的に単身者の希望に対しては、当然落選の方が多くなりますので、民間賃貸住宅の単身者向けのあっせんというところも引き続き支援を行っているところです。","voiceIndex":7,"id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"分かりました。確かに募集戸数によるというのはそのとおりなのですが、単身者向けの募集戸数が少なめだという傾向にある。戸数が少ないということなのでしょうけれども、希望する単身者の方が多い、単身者向けの住宅の倍率が高い、特にそういう認識ではないということなのでしょうか。もう一度だけ聞かせてください。","respondent":"川原住宅課長","answer":"単身者向けの倍率についてのご質問です。過去の、前回、また、前々回のところを遡ってみますと、当然募集戸数が１戸ないし２戸に対し、倍率が高いというところは区としても認識をしています。","voiceIndex":9,"id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"区営住宅もありますけれども、こういった応募の状況などを、分析と言うと大げさかもしれませんが、把握した上で、適切に今後の住宅政策に反映していただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":11,"id":"exchange-003"},{"speaker":"中塚委員","kind":"質問・要望","question":"都営住宅の倍率の話がありましたけれども、改めてこの狭き門の実態が浮き彫りになっているわけですから、品川区として東京都に区営住宅の増設を求めるべきだと、冒頭で述べておきたいと思います。単身者向けの倍率がなぜ高いのか、そこの理由を伺いたいと思います。","respondent":"川原住宅課長","answer":"高齢の世帯の方もどちらかの方がお亡くなりになってしまうと、当然世帯ではなく単身者になってしまいますので、そういった単身の高齢者の支援というところ、一定数、入居の支援というところでつなげていきたいと考えています。","voiceIndex":13,"id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"なぜ単身者が高倍率なのかということを改めて伺いたいと思います。先ほど課長は、民間の賃貸が借りづらいとおっしゃっておりましたけれども、現在借りている人が申し込んでいるわけですから、なぜこの申込者が多いのか、要するに倍率が高いのか、申込者の実態というものをどのように認識しているのか、改めて伺いたいと思います。なぜそのような認識に立てないのか伺いたいと思います。","respondent":"川原住宅課長","answer":"２点ご質問をいただきました。現在、民間賃貸に住んでいる高齢者の方が、都営住宅の募集に応募をしているところへの認識をどのように把握しているかというご質問が１点目です。","voiceIndex":15,"id":"exchange-005"},{"speaker":"中塚委員","kind":"質問・要望","question":"都営住宅の増設ですけれども、その考えはないということで、これだけ都営住宅を申し込める方が増えているのに、なぜ考えがないのか、そこに思いが寄せられないのか、そのサポートを支援していくとおっしゃいますけれども、現在民間のアパートに住んでいる方が民間のアパートに引っ越すことが難しく、それは家賃の問題、さらには更新の問題、それで都営住宅に申し込まれているわけですから。","respondent":"川原住宅課長","answer":"増設についての区の考えというところでは、現時点では都営住宅増設の要望はありませんが、引き続き民間賃貸住宅の支援とあっせん、あとは、セーフティーネット専用住宅、そして居住サポート住宅というところをしっかりと推奨していって。","voiceIndex":17,"id":"exchange-006"},{"speaker":"中塚委員","kind":"提案","question":"去年の建設委員会のやり取りの中で、森澤区長は生成ＡＩを使って様々な事業を立ち上げているけれども、この住宅分野については生成ＡＩは特に使われていないというご説明があっただけに、区の窓口でどのような声が多いのか、どういう問合せやどういった区民の暮らしの実態が多いのか、そこをしっかりつかんで、発表していく、区議会にも報告していくと、そうした取組はとても大事になってくると思いますので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":19,"id":"exchange-007"}]},{"id":"topic-02","title":"公園における花火の使用","agenda":"公園における花火の使用","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"声が多数届いていたということでお話がありましたけれども、この５つの公園の選定理由をお伺いしたい。今後は今年の試行結果を踏まえてということでした。当日の苦情等への対応体制などはどうなっているのか伺いたいと思います。","respondent":"大友公園課長","answer":"当日に苦情等があった場合なのですけれども、こちら、管理事務所がある公園というところで、基本的には常駐時間帯というところで対応していくという形になってあります。","voiceIndex":24,"id":"exchange-008"},{"speaker":"安藤委員","kind":"意見","question":"親子などで少人数単位ではありますけれども花火を楽しめるというのが、すごく大切な幼少期の経験にもなりますし、いろいろ、様々なレベルでの交流にもなりますので、ぜひそういったことができる区になってほしいなという思いがありますので、今年いろいろあるかもしれませんけれども、きちっと分析して、維持、継続、発展も含めて、今後もできるといいなあというふうな思いを私は持っているです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":26,"id":"exchange-009"},{"speaker":"中塚委員","kind":"質問","question":"伺いたいことは２つあるのですけれども、まず、冒頭の説明で、しながわ花海道以外の区内の公園では花火禁止ということで、品川区内全てで花火は禁止なのだということについて、改めて説明を伺いました。同時に、道路上、道路といっても私道と公道と様々あるでしょうが、家の前の道路上での花火というのはどういう取扱いになるのか、これを機にお伺いしたいと思います。","respondent":"大友公園課長、森道路課長","answer":"他区の状況というところなのですけれども、昨年度ぐらいから試行実施する区が増えてきておりまして、隣接する区でいきますと、５区のうち、今年度試行するのが、品川区入れて２区で。基本的に公道上は、危険な行為であったり、道路を汚損するような行為についてはしないようにというふうに書かれてありますので、それに該当してくるのかなとは考えております。","voiceIndex":28,"id":"exchange-010"},{"speaker":"中塚委員","kind":"質問・要望","question":"公園であっても道路上であっても公共の空間ですから、もちろん危険な行為はあってはならないと思います。この家族単位という表現の趣旨を伺いたいと思うのですが、大人同士のカップルと言えばいいのか、お付き合いされているカップル、異性同士でも同性同士でも、結婚していなければ花火もできないのかと、そういうことを言いたい議論ではないということであってほしいと思います。","respondent":"大友公園課長","answer":"今回、実施をしまして、その状況を見て、来年度必要とあれば子どもの定義を決めていかなくてはならないのかなと思いますし、今回はあくまでも試行というところで、実際にまずはやってみてというところで考えていきたいと考えています。","voiceIndex":31,"id":"exchange-011"},{"speaker":"中塚委員","kind":"提案","question":"子どもの年齢のほうは試行ということで今、ご説明ありました。家族単位について、家族を基本としたということですけれど、私の趣旨が伝わらなかったのか、家族のありようって様々だと私思うのです。これまでジェンダー平等、森澤区長も様々条例を提案してきて、議論もあって進めてきて、という状況に照らすと、こういう表記でいいのかと問題提起をさせていただいたのですけれども、改めていかがでしょうか。","respondent":"大友公園課長","answer":"実際に、具体的な家族の在り方というところを提起して書いているところではございませんので、明確に、籍を入れていなくては駄目とか、そういうような形での縛りを設けての書き方、受け取りということではないと、誤解のないようにして運用していきたいと考えています。","voiceIndex":33,"id":"exchange-012"},{"speaker":"中塚委員","kind":"質問・要望","question":"これで最後にしますけれども、やはり、家族単位という表現を見直したほうがいいと思います。自分のことを振り返れば、これから家族になりたいと思う人との過ごし方としても花火は結構いいツールだなと思うわけで、その趣旨が少人数ということであれば、２人の表記が家族単位というのではなくて、別の表記にここはやはり見直したほうがいいと要望して終わりたいと思います。ぜひご検討ください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":35,"id":"exchange-013"},{"speaker":"ゆきた委員","kind":"質問","question":"概要の（２）、（３）の実施期間と時間の決められた理由についてお聞きできればと思います。","respondent":"大友公園課長","answer":"実施期間というところなのですけれども、花火、季節を限るのも少しあれなのですが、夏に実施することが一般的なのかなというところと、あと、お子様が、学校等々がお休みの期間というところで、実施しやすい期間ということで絞って試行実施の期間を定めさせていただきました。","voiceIndex":37,"id":"exchange-014"},{"speaker":"ゆきた委員","kind":"確認","question":"実施期間は夏休み期間ということ確認できました。それで、確認したところ、大田区では１８時から２０時半、世田谷区では２０時半までで終了、２１時までに片づけも含めて全て終了というふうになっていました。治安の問題とか、近隣の騒音などの関係もあると思われますが、一概に遅くまではできないとも思われますが、改めてこの辺についてお聞きできればと思います。","respondent":"大友公園課長","answer":"他区の状況、２０時で設定しているところ、２０時半、２１時と大体３パターンあるかなというところですけれども、今回はこの形、２０時で実施をしてまいりたいと考えているところです。","voiceIndex":39,"id":"exchange-015"},{"speaker":"ゆきた委員","kind":"確認","question":"近隣の状況を鑑みてということで確認できました。もう一点なのですけれども、試行実施した意見や区民のお声をどのようにして集約していくかというところをお聞きできればと思います。","respondent":"大友公園課長","answer":"地域の声、実際にやっている人の声等々を拾っていき、我々のほうで集約して、それを来年度に向けて反映していく、また、今年度の実施の改善点があればそこに反映していくという形で考えてあります。","voiceIndex":41,"id":"exchange-016"},{"speaker":"ゆきた委員","kind":"確認","question":"現場の声を確認してということで確認できました。私も、品川区のホームページで、公園の花火利用についてというものを見させていただきました。より多くの区民のお声を効率的に集約していければと思いますが、この辺についてもお聞きできればと思います。","respondent":"大友公園課長","answer":"ご提案ありがとうあります。利用者のみならずほかの様々な方々の声をいただく手段として、幅広くいただける手段を考えてまいりたいと考えています。","voiceIndex":43,"id":"exchange-017"},{"speaker":"松永委員","kind":"質問","question":"私からは４点あります。１つは、このルールというのがあると思うのですが、もしルールを破った場合どうなるのでしょうか。こうしたところで、区はどう対応されるのか。そうした場合はどう対応されるのでしょうか。３番目になります。先ほどの質問の中で、対象は管理事務所がある公園ということでしたが、なぜ西大井広場公園がないのか、その理由についてお知らせください。以上、４点です。","respondent":"大友公園課長","answer":"こちら西大井広場公園につきましては、今選定しているほかの公園と比べますと、管理上いろいろなお声をいただく機会が多い公園というところがございまして、今回実施をするのにはなかなか難しいのかなというところで考えさせていただいたところです。","voiceIndex":46,"id":"exchange-018"},{"speaker":"松永委員","kind":"質問","question":"ぜひそうした、ルールをしっかり明確にしてホームページに掲載していただければと思います。先ほどの、例えばルールを破った場合ということで、ＳＮＳとかに上げた人、投稿者がいるではないですか。投稿された人に対しては、何か注意ではないけれど対応というのはされたのでしょうか。そのまま放置されるのでしょうか。それだけ教えてください。","respondent":"大友公園課長","answer":"そのルールが、花火を持って走り回らないという程度のものであれば、これを見逃すとかという話は裁量になってくるかと思うのですけれど、ケース・バイ・ケースになるかと考えています。","voiceIndex":48,"id":"exchange-019"}]},{"id":"topic-03","title":"（仮称）しながわ防災区民憲章の制定","agenda":"（仮称）しながわ防災区民憲章の制定","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"今回、憲章ということで、条例と憲章なのですけれど、この違いです。憲章をつくるという、この独自の憲章をつくる意味というのは何なのでしょうか、伺いたいと思います。","respondent":"羽鳥防災課長","answer":"憲章につきましては、品川区、区民憲章等ありますが、区民の皆様の総意でつくり上げるものというふうに認識しています。そういったこともありまして、今回、防災区民憲章をつくるに当たり、幅広く様々な機会を活用して、ご意見を募ってまいりたいと考えています。","voiceIndex":54,"id":"exchange-020"},{"speaker":"安藤委員","kind":"質問","question":"何か、今のご説明ですと、条例とか憲章をつくるに当たっての、つくり方についてのご説明だったように聞こえたのですけれど、それ以外に条例と憲章の違いというのはないのか、もう一度伺いたいと思います。","respondent":"羽鳥防災課長","answer":"つくり方以外の違いですけれど、まず、品川区に関しましては、平成２６年の３月３１日に品川区災害対策基本条例というものをまず、制定をいたしまして、この中で、自助、共助、公助の役割と、区民、事業者、あと、区、防災区民組織などの努めというのを定めております。","voiceIndex":56,"id":"exchange-021"},{"speaker":"安藤委員","kind":"質問","question":"これは意見なのです。２つお伺いしたいのですが、まず、憲章なのですけれど、先ほどからありますように、条例の前文の理念を活かし制定と、資料にもあるのですが、具体的には前文のどのような点を活かすということなのか伺いたいと思います。２つ目は、資料の方針で、品川区らしさというのがあると思うのですけれど、この品川区らしさというのは何を指しているのか伺いたいと思います。","respondent":"羽鳥防災課長","answer":"品川区らしさにつきましては、こちらは、これから皆さんに意見を募ってまいりたいと考えています。","voiceIndex":58,"id":"exchange-022"},{"speaker":"安藤委員","kind":"質問・要望","question":"建設委員会の報告というのは結局いつになるのかというのをお伺いしたいと思います。デジタルプラットフォームで意見集約するということと併せて、説明会というのですか、要するにこれがある意味パブリックコメントみたいなものだと思うのですけれど、説明会というのをどこかでやらなくてはいけないのではないのかと思うのですが、それについてのお考え、やるのかやらないのかを伺いたいと思います。","respondent":"羽鳥防災課長","answer":"説明会につきましては、今回、３月１１日制定という短い期間の中で対応しているため、なかなか大規模なものというのが期間的に難しい部分もありますが、各地区の町会長会議など、対応できるところは個別に出向いてご説明差し上げるというところでは、現在。","voiceIndex":60,"id":"exchange-023"},{"speaker":"安藤委員","kind":"質問","question":"これかなり固まったあとなのではないのかと思ってしまうのです。もっと早く報告してくださいよと思うのです。普通だったらいわゆるパブリックコメントとかやるではないですか。もう、８月の防災会議の委員への意見集約のときにはその案みたいなものは示されているものなのか、９月の広報紙にて区民に周知する場合にはもう既に案が載っているものなのか、そこら辺が少し分からなかったのでお伺いしたいのです。","respondent":"羽鳥防災課長","answer":"それで、案として大体つくられてくるのが年明けぐらいかなというふうには考えております。これは、今後進めながら、状況見ながら、委員会報告につきましては、途中、進捗報告もさせていただきたいと考えておりますので、適宜対応してまいりたいと考えています。","voiceIndex":62,"id":"exchange-024"},{"speaker":"安藤委員","kind":"質問・要望","question":"そうですね、やはり大事な憲章というところで、しかも、これから引き継いでいくということで、今後、長きにわたって影響が大きいものだと思います。もともとの基本条例のところで、私たちは少し異議があります。これは区民憲章なわけですから、しっかりと多くの方々の意見を聞いて、それを反映したものにしていくべきだと改めて意見を述べさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":64,"id":"exchange-025"},{"speaker":"中塚委員","kind":"質問・要望","question":"何をもって制定と、公に定めるのか、そこを伺いたいと思います。概要にも書いてありますが、阪神淡路大震災から３０年、能登からも１年、東日本大震災から１５年、そのほかにも、新潟中越から、熊本から、千葉もそうですけれども、毎年のように大きい災害がある中で、品川区は自助・共助が薄いから被害が拡大したという認識なのか、つまりは区民の自助・共助の意識の向上とは何なのか伺いたいと思います。","respondent":"羽鳥防災課長","answer":"議会の区長答弁でもご説明させていただいた内容になりますが、過去に明治、昭和と２回大きな津波の被害を受けている田老地区では、避難路の整備であったり、防潮堤の整備、そういった公助の部分のハードの整備はある程度進んでいたという中で。","voiceIndex":66,"id":"exchange-026"},{"speaker":"中塚委員","kind":"質問","question":"そうしたら、本会議でも何か少しそんな議論があったような気もしているのだけれども、第２回定例会なのかな、その割には、今日からもう、来年の３月１１日には決めるというのはすごく拙速だなというのをまず、感じました。もう一度この、何がどう大丈夫だと思って、思ってしまったから被害が起きてしまったと、だから自助・共助なのだというのがよく分からなかったので、伺いたいと思います。","respondent":"羽鳥防災課長","answer":"自助・共助の重要性のところ、区長がどのように認識されたかです。","voiceIndex":68,"id":"exchange-027"},{"speaker":"中塚委員","kind":"質問","question":"区長がそうお感じになったと。そこにこそ、大事な教訓があるわけで、どうしてそれが自助・共助の再認識が、しかもこの区民憲章の肝になる部分につながるのか、改めて伺いたいと思います。何か、自助・共助の重要を再認識、これが震災の最大の教訓だと、これを今度区民憲章に盛り込むのだと、一体何を見てきたのだという思いにどうしてもなってしまうのですけれども、いかがでしょうか。","respondent":"羽鳥防災課長","answer":"公助のところで、災害関連死を防ぐために様々な取組をしておりますので、やはり自助、共助、公助、それぞれがそれぞれ高め合うということで、首都直下地震に向けて、区の地域防災力がさらに高まるというふうに認識しています。","voiceIndex":70,"id":"exchange-028"},{"speaker":"中塚委員","kind":"質問・要望","question":"自助、共助、公助と言いますけれども、それぞれの担い手の役割の明確化をしたりとか、あと、誰が何をするかという役割分担が不徹底だったから被害が起きたのでは決してないのだというところを分かっていただきたいのです。この自助・共助の重要性の再認識ではなくて、被害の想定、それを防ぐための対策、こうした予防対策こそ第一に考えるべきだと思いますが、最後にいかがでしょうか。","respondent":"羽鳥防災課長","answer":"被害を想定して計画、訓練をするということの重要性に関しましては、区としてもそれは認識しています。そういった訓練を踏まえて公助の力を高めるというのはもちろんですけれど、訓練を踏まえて自助・共助の意識も高めるという役割もあると考えています。","voiceIndex":72,"id":"exchange-029"},{"speaker":"中塚委員","kind":"質問・要望","question":"被害を想定してやっていますとおっしゃいますけれども、何をどう被害を想定するかというところで被害の想定から外れているものはあるわけです。果たして品川区の防災計画で、この夏の暑いときに電気・ガス・水道が止まって、避難所での生活をするとなったら、どうでしょう。ただ、実際の被害の深刻さに比べて追いついていないという点で、予防対策を第一にした計画を重ねて要望して終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":74,"id":"exchange-030"},{"speaker":"ゆきた委員","kind":"質問","question":"有識者インタビューのメンバー４名をどのような角度から選んだのか、理由について教えてください。この中でインタビューとありますが、誰がインタビューするのか、４名それぞれ別の場所でヒアリングを行うのか、それとも４名によるディスカッション形式の中で意見集約していくのか、インタビューの回数は何回を想定しているのか、この辺についてお聞きできればと思います。","respondent":"羽鳥防災課長","answer":"今後インタビューに関しましては、まずは１回を予定しています。今後必要に応じて、ご意見等いただければというふうには考えております。","voiceIndex":76,"id":"exchange-031"},{"speaker":"ゆきた委員","kind":"確認","question":"様々確認できました。ここについてもお考えをお聞きできればと思います。事業内容の方針で、品川区民の意見を聴くとありますが、防災会議でも品川区民は、先ほどの中で一部ですし、有識者の中でも品川区民は少ないです。対象年齢を、このデジタルプラットフォームでどのぐらいの年齢を対象としているのか教えてほしいと思います。この辺についてお考えがあればお聞きできればと思います。","respondent":"羽鳥防災課長","answer":"３つ目の質問にもなりますが、イメージが分かりづらいというところがありますので、デジタルプラットフォームで意見を募る際もそういったものを提示していきたいというふうには考えてあります。デジタルプラットフォームをどのように活用するのか。","voiceIndex":78,"id":"exchange-032"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"先ほど、似通った議論もありましたけれども、釜石市では意見交換会、審議会、ワークショップを計１３回行って市民の声を集めています。ですので、例えば著名な詩人とか作家、作詞家などから言葉の力、伝える力を駆使することができる人に、最終的に憲章素案に手を入れてもらってはどうかと思いますが、ここについてもお考えをお聞きできればと思います。","respondent":"羽鳥防災課長","answer":"ワークショップに関しましても、デジタルプラットフォームの機能の中で、そういった活用ができる可能性があるかもしれませんので、そういったところも視野に入れながら、幅広く意見を聴取してまいりたいと考えています。","voiceIndex":80,"id":"exchange-033"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"品川区らしさ、特色として、マンション防災とか在宅避難をしなければいけないところ、木密地域があることとか、トイレ問題で、空白地帯も出てきているところなど、そういったところもできる限りの災害時に想定し得る区の特徴を参考として、区民や有識者の意見交換の俎上に上げていただきたいと思いますが、こちら最後にお聞きできればと思います。","respondent":"羽鳥防災課長","answer":"そういったところも参考にしつつ、区民の方から意見を聞く場合は、そういった細かなところまで拾い上げて、それを全体的にどういうふうに理念として、防災憲章として表現していくかというところは考えていきたいと思います。","voiceIndex":82,"id":"exchange-034"},{"speaker":"せお副委員長","kind":"提案","question":"今、ゆきた委員からもあったように、本当にこれ幅広く聞いてほしいなあとも思ったのです。スケジュールがすごいタイトだなと思っていて、例えば今、ゆきた委員から提案あったように、幅広く聴いていくとか、ワークショップとかやっていくというのは、これは間に合うのかなというところもお聞かせいただけますか。","respondent":"羽鳥防災課長","answer":"１点目の目的についてですけれど、目的はぶれないほうがいいと思いますので、もうこのまま、特に追加はしないで、自助・共助の意識向上ということで進めていきます。","voiceIndex":85,"id":"exchange-035"},{"speaker":"せお副委員長","kind":"質問・要望","question":"ではその中でも、具体的なところは幅広く取っていただきたいなと、そこは要望しておきます。ぜひ、ではもうこのスケジュールが変わらないのであれば、できるだけ幅広く意見は聴いてほしいし、いろいろな聞き方、本当に顔を合わせてワークショップとかで話していくというのはすごく大切だと思うので、ぜひ、時間ないですけれど、検討していただきたいなと要望いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":87,"id":"exchange-036"}]},{"id":"topic-04","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひ、正副で進めていただきたいと思うのと、次回の委員会で決定でいいのですけれども、日程だけ、見通しがついた時点で、この２泊３日で行くよと。日程は見通しがついた時点で教えていただけたらなと思いますので、よろしくお願いいたします。","respondent":"新妻委員長","answer":"日程は、これから検討を、相手先とのやり取りをした上で、日程が見えた段階で早めにお伝えをするように、また、事務局の書記とも打合せをしたいと思います。","voiceIndex":92,"id":"exchange-037"}]},{"id":"topic-05","title":"その他","agenda":"その他","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"２つだけ伺いたいのですけれども、去年の河川大会のときに、目黒川と立会川のライブ映像がスマホで見づらいということを指摘させていただいて、少し考えてみますということだったのです。あの映像は私も衝撃的だったので、品川区で同様のことがないように十分警戒をしていただきたいと思うのですけれども、区内のマンホールの状況はどうかということ、この辺、２つ伺いたいのです。","respondent":"羽鳥防災課長、関根河川下水道課長","answer":"そこに、品川区の気象状況が見えるリンクが張られています。そちらからアクセスしていただければ、ライブ映像、見ることが可能ですので、ぜひ、防災ポータル、防災アプリ、ダウンロードしていただけると助かります。そうした中で、引き続きそういった形でしっかりと、マンホールの飛散がなるべく起こらないような形で施工等も行ってまいります。","voiceIndex":97,"id":"exchange-038"},{"speaker":"中塚委員","kind":"質問・要望","question":"毎年のように雨の降り方が尋常ではなくなっています。ある程度構造的に予測ができるのであれば、そこのエリアのマンホールの空気の逃がし方を確認していただきたい。もちろん日頃からの点検などをきちんとやっていることは承知していますけれども、やはり７月１０日のマンホールの映像を見ているだけに、もう一度点検をして、十分な警戒を取っていただきたいと思いますが、改めてこの点だけいかがでしょうか。","respondent":"関根河川下水道課長","answer":"区としては、新しく造る下水道管は受託はしておりますが、日常的な点検ですとか維持管理は東京都のほうで実施をしておりますので、東京都のほうに、そういったところを引き続きしっかりと取り組んでいただくように、機会を捉えてお話をしていきたいと考えています。","voiceIndex":100,"id":"exchange-039"},{"speaker":"松永委員","kind":"確認","question":"すみません、少し確認です。土のうについてなのですけれども、７月１０日の件で土のうを使用させていただきました。その際、使用してその後また、同じところに戻すというのが基本だと思うのですが、そうしたことで合っているのか確認させてください。その土のうを使ったときに、減っている箇所があるかもしれませんけれども、基本どういった形で確認をされているのでしょうか。","respondent":"森道路課長","answer":"それぞれの土のうを戻していただいた後に、こちらのほうで、最低年に一回、土のうの管理委託というのを行っておりまして、その委託の中で土のうの整理をしていただいたり、あるいは規定の個数を設置できているか、乱雑になっていないかというようなことを確認し。","voiceIndex":103,"id":"exchange-040"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7157#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":31779,"voices":106}},{"id":"r07-20250728-9","meetingId":"r07-cm07","date":"2025年7月28日","dateIso":"2025-07-28","committee":"文教委員会","time":"午後 １時００分～午後 ３時１９分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を46件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"令和７年陳情第２７号、未就学児のいじめ対応に関する陳情","agenda":"令和７年陳情第２７号、未就学児のいじめ対応に関する陳情","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"今回、未就学児でのいじめということで、いろいろ被害に遭った子どもがいたという状況です。この中で、園がどのように対応したのかを伺いたいと思います。そうした中で、園としてどのような対応をしてきたのか、園として、子どもたちも含めてなのか、話合いをどのようにやってきたのかということを伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":14,"id":"exchange-001"},{"speaker":"のだて委員","kind":"質問","question":"最後の「さらなる改善が必要だった」というのは、区の意見ですか。私はこの陳情が出された中で、陳情者の方にもお話を伺いました。年長クラスで、対立が生まれる時期だとは思います。そうした取組が園になぜできなかったのかを伺いたいと思います。子どもたちの成長、発達を保障していくのが保育園だと思いますので、そうした協働性なども育んでいく必要があると思うのですけれども、いかがでしょうか。","respondent":"佐藤保育事業担当課長","answer":"個別の発達状況の違いというのがありますので、そうしたところもより丁寧に理解しながら実施していく必要があったと園としては考えているところです。","voiceIndex":19,"id":"exchange-002"},{"speaker":"のだて委員","kind":"質問","question":"やってはいけないこと等を子どもたちに教えていかなければいけなかったというお話なのですけれども、実際、陳情者の方にお話を伺ったときに、お子さんも一緒に来られて、話を聞いたのですけれども、お子さんも言っていたのは、園には３つの約束事みたいなことが掲げてあって、１つが、されて嫌なことは相手にはしない。２つ目が、優しい言葉で伝える。","respondent":"佐藤保育事業担当課長","answer":"お話しいただきましたように、園で掲げている目標というのはしっかりと達成されるべきものであると考えていますので、区といたしましても、指導検査や巡回支援といった取組の中で、しっかりと園に対して指導や支援というのを実施していく必要があると考えているところです。","voiceIndex":21,"id":"exchange-003"},{"speaker":"のだて委員","kind":"質問・要望","question":"書かれている事案の中でも、色鉛筆で目頭を負傷させられたということで、一歩間違えば目が傷つけられる、失明という可能性もあったということで、これは本当に重大なけがだと私は思うのですけれども、区が報告を求めたのに、園では報告義務がないということで、これは実際、報告する義務がないのかどうか、区としてもこうした事案は報告しなくていいと考えているのかどうか伺いたいと思います。","respondent":"佐藤保育事業担当課長","answer":"１点目のご質問、研修について、園で実施していたかですが、園でも研修というのは行っておりました。","voiceIndex":23,"id":"exchange-004"},{"speaker":"のだて委員","kind":"質問","question":"園からは、経過について報告は受けているということ、義務はないけれども、区が伺って話は聞いているということですね。","respondent":"佐藤保育事業担当課長","answer":"事故に関する報告の義務というのはございませんが、園で発生しました保育に関する事案ですので、そこにつきましては、区で経過を知る必要があると思ったものに関しましては、提出いただくものと認識しております。","voiceIndex":25,"id":"exchange-005"},{"speaker":"のだて委員","kind":"質問・要望","question":"今後の区としての対応を伺いたいのと、あと、園でこれまでも研修されてきたという中で、なぜこうした事態が起こってしまったのかと思うのですけれども、区と園で分析しているところを聞いていれば伺いたいのと、実際はこういうことが起きた中で、今後どういった対応をしていくのか伺いたいと思います。","respondent":"佐藤保育事業担当課長","answer":"より適切な早い段階で、園児同士の間にしっかりと園が関与して、やっていいこと、悪いこと、相手の気持ちを考えることなどを多くの園児に理解してもらうような保育をしていく必要性があると考えてございまして、これも一部重複してしまいますが。","voiceIndex":27,"id":"exchange-006"},{"speaker":"のだて委員","kind":"質問・要望","question":"区でも監査を実施していくということ、あるいは第三者委員会、園でも行っているという話でしたけれども、実際この間、機能していたのかというところも、こういった事態が起こると問われてくると思うのですが、いかがでしょうか。実際どのぐらい第三者委員会が行われたのか、また、区の監査というのはどれだけ入っていたのかというのを伺いたいと思います。","respondent":"芝野保育入園調整課長","answer":"その前後に巡回支援ということで、園のサポートという意味合いもありますが、そちらの巡回支援が２回入っておりまして、１回目が８月１９日、指導検査が終わった後の２回目に１２月２３日、こちらに巡回支援という形で入っております。","voiceIndex":29,"id":"exchange-007"},{"speaker":"のだて委員","kind":"質問・要望","question":"実際、起きた中身が不適切保育に当たるかと思うのですけれども、区の見解を伺いたいのと、実際こうしたことが起こっているということ、いじめという言葉ではないとしても、それを把握していくということが必要であると。それが子どもたちの健全な成長、発達を保障していくということにもなると思うのですけれども、いかがでしょうか。","respondent":"佐藤保育事業担当課長","answer":"区といたしましては、今回のように保護者の方や事業者の方から個別にご相談があった際には、しっかりと内容を把握する必要性があると考えまして、状況に応じまして、園への訪問やヒアリング、今回でありますと代表の方との面談というのを実施していますので。","voiceIndex":33,"id":"exchange-008"},{"speaker":"のだて委員","kind":"質問","question":"個々に対応する、個別に対応するというお話ですけれども、こうした声が上がってこない事案もあるかと。そうした中で子どもが傷を負ってしまったということは、本当に重大なことだと思いますので、そうしたことが不適切保育に当たらないというのは、どういう定義などがあるのか、そこを伺いたいのと、実際に被害を受けている中で、そのまま１か月以上は過ぎている状況です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":35,"id":"exchange-009"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ、二度とこうしたことがないようにしていただきたいと。子どもたちの健全な成長、発達を保障するという立場で、区としても園の指導をしていただきたいと思います。すみません、１点聞き忘れたのですけれども、冒頭の説明で、１番の速やかに転園できるようにしてほしいというところは、途中入園も可能になるというお話だった気がするのですが、そこを改めて確認させていただきたい。","respondent":"芝野保育入園調整課長","answer":"最初にご説明させていただいたとおり、やむを得ない事情による転園については、児童の福祉を最優先に考えまして、可能な限り速やかに入園いただけるように今後努めてまいります。","voiceIndex":38,"id":"exchange-010"},{"speaker":"のだて委員","kind":"質問・要望","question":"今後、速やかな転園ができるようにということでしたので、ぜひ子どもたちが傷を負うことがないように、それを少なくともできるだけ低減するように、区としても柔軟な対応をしていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":42,"id":"exchange-011"},{"speaker":"まつざわ委員","kind":"質問","question":"それを今回のケースだと、お調べしたら、連絡先が分からなかったというのがあって、先ほどの質問だと、もう会社にいなかったりするケースが見受けられるという部分をお聞きしたのですけれども、これについて、区として何かできるということはあるのですか。","respondent":"佐藤保育事業担当課長","answer":"区といたしましては、本案件を受けまして、様々な機会を捉えまして、連絡先であったり、その方がしっかりと届出と同じような状況でいらっしゃったりするのかについて、改めて調べるように指示をしていきたいと考えております。","voiceIndex":46,"id":"exchange-012"},{"speaker":"筒井副委員長","kind":"質問・要望","question":"ぜひ、今後こうした事態が起きないように、くれぐれも区として取組をしていただきたいと存じます。確認させていただきたいのですけれども、オンラインの相談窓口というのは、品川区のホームページで確認をすると、保育所等での不適切保育等の相談窓口というページでよろしいのかということと、あと第三者評価は、東京都福祉サービス第三者評価ということでよろしいのですか。この２点をお伺いさせてください。","respondent":"佐藤保育事業担当課長","answer":"今、委員がお話しいただきました窓口で、両方とも正しいものです。","voiceIndex":49,"id":"exchange-013"},{"speaker":"筒井副委員長","kind":"質問","question":"分かりました。今回、陳情の要旨の３番で、経営層までの強い指導ということで、区としても面談をされたとのことですけれども、面談の際、経営者の方はどのようなご反応というか、ご回答があったのでしょうか。その点をお願いします。","respondent":"佐藤保育事業担当課長","answer":"代表の方ですけれども、本案件については理解をしてございまして、まず、何度かお話していますが、法人として、通われている認可保育園で、通っていただいている児童の方に悲しい思いをさせてしまったという点、しっかりと対応していかなければならないと考えています。","voiceIndex":51,"id":"exchange-014"},{"speaker":"若林委員","kind":"確認","question":"そうすると、こういういわゆるトラブルというのは、私の考えだと日常茶飯事といいますか、どの園でも、いつでもどこでも起こり得る。集団生活というのはそういうものだろうということで、今までこういう問題に対して、区がどこまで責務を負っているのかを１つお聞きして、今までこういう園の中で、また、区当局に相談があった場合のこれまでの対応とかはどういうものだったか、一回確認させてください。","respondent":"佐藤保育事業担当課長","answer":"区における責務ですが、保育所につきましては、健全な成長を行うための施設であるというところがありますので、その中において、園児同士の関わり合いがエスカレートしてしまうような案件であっても、しっかりと園としては、そうしたトラブルが起きないように実施していくこと。","voiceIndex":54,"id":"exchange-015"},{"speaker":"若林委員","kind":"質問・要望","question":"年に数件ほどあるということで、今回の事例、陳情の内容が、その中でどの辺りのレベルにあるかというのは、一つ一つ聞かないと分かりませんけれども、そういう中で、今回は1)、2)、3)という具体的なご要望、陳情があって、今回はあえて言えば1)の、転園の時期については柔軟に対応するということになったのですけれども、年に数件ある中で、今回特にこの陳情によって。","respondent":"芝野保育入園調整課長、佐藤保育事業担当課長","answer":"私のほうは１点目、柔軟な対応に至った経緯ですが、年に数件そのような相談があるというところの中で、両課でしっかりと連絡、調整をいたしまして、本当に重大な、転園が必要だという判断が下された場合には。保育園長会等で出てくる区に対する要望ですけれども、こうした同様のケースがあった際に、まず園からは、どのような対応をしていけばいいのかというご相談と、あとは、そうした対応が分かるような研修。","voiceIndex":56,"id":"exchange-016"},{"speaker":"若林委員","kind":"質問・要望","question":"今回は極めて重大な案件というところで、品川区もそういう判断に至ったということで理解をしております。１点だけ、2)の実態調査については、今までのご答弁で理解いたしました。年に１回実態調査をやって、それで終わりとなってもいけませんので、常に門戸を広げておく、オンラインも含めて、そこも柔軟に対応していくという区の取組は、今回の事例も含めて、そういう考え方だと理解します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":59,"id":"exchange-017"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"今回の陳情というのは、１つ目、２つ目、３つ目とも、未就学児におけるいじめの早期発見の必要性であったり、緊急時の対応であったり、言うならば子どもの安心・安全を願う、親としては当たり前の陳情であって、とても大切な観点だと考えています。３つ目の仕組みの部分に関しても、保育園の運営に対する行政の関与というのは、実際の現状の法制度の枠内でやるべき、それは私も理解します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":61,"id":"exchange-018"},{"speaker":"筒井副委員長","kind":"質問・要望","question":"陳情の要旨１番につきましては、今後は可能な限り速やかに対応されるということ。２番につきましては、東京都の第三者評価や、またオンラインの相談窓口など、実態調査に代わり得る措置を取られるということで、３番につきましては、個別の事案に対しては、経営層まで強く指導できる体制は既にあるということで、また、今回実施されたということであります。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":62,"id":"exchange-019"},{"speaker":"若林委員","kind":"質問・要望","question":"本日結論を出していただきたいと思います。先ほど質疑を何点かさせていただきました。質疑の中で、園からは、保育士を増やすための補助金のお話とか、また、研修については、私としては、質疑の中でも言いましたけれども、初動の大切さというのも重きを置きながらの研修もしっかりやっていただきたいというご要望もお伝えしながら、区の一定の対応というところで、本日は不採択で結果を出すと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":63,"id":"exchange-020"},{"speaker":"のだて委員","kind":"意見","question":"本日結論を出すということで、採択です。子どもの健康を守るということ、心身のケアもしていくということで、実際にこうした被害が出ているという中で、しっかり対応できるような仕組みをつくっていくということが必要だと考えますので、採択です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":64,"id":"exchange-021"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"本日結論を出すで、不採択でお願いします。最後は、このお子さんと保護者の傷ついた何か月かというのはもう取り返すことができないので、今後、先ほど十分なケアというお話がありましたけれども、これからの保育園、そして小学校の生活でフォローしていくような形を、区でしっかりとケアしていっていただきたいというのが要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":65,"id":"exchange-022"}]},{"id":"topic-02","title":"学校選択制の運用等","agenda":"学校選択制の運用等","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"聞きたいのが、ぜひ地図をつけていただきたかったと。この間も説明があったとは思うのですけれども、この学区域の変更については、保護者の方とか地域の方とかに意見を聴きながら、それを反映させてやっているのかどうかというところを伺いたいのと、先ほども少し説明があったかもしれないのですが、浅間台小学校と立会小学校が出てきている理由、関係性というのを伺いたいと思います。","respondent":"石井学務課長","answer":"その後、通学区域の変更を行った後も、７月に地域への説明を行い、８月には保護者説明会も実施したという運びとなっており、この間、様々な説明を図ったところです。","voiceIndex":73,"id":"exchange-023"},{"speaker":"のだて委員","kind":"質問・要望","question":"いろいろ地域の方と保護者の方と、説明してきたというところで、その方々は納得されているということでいいのか、確認させていただきたいと思います。","respondent":"石井学務課長","answer":"そのご質問に回答するような形で、丁寧にして、ご理解をいただいてきたと考えています。","voiceIndex":75,"id":"exchange-024"},{"speaker":"まつざわ委員","kind":"質問","question":"今度、城南第二小学校というのが増えていくわけではないですか。そうすると、今と全く反対のことが起こるのです。そうすると、今ある城南小学校の教室が減っていく、城南第二小学校は増やしていかなければいけないということが、この表では見えてくるのですけれども、そういった話合いとかもどれだけするのか、喫緊でやってもどうにもならないことなので、その辺りの見込みを教えてください。","respondent":"石井学務課長","answer":"令和６年３月に学事制度審議会の答申がございました。答申の審議会としての考え方は、まず就学人口推計において、数年の間、学級増が継続している、または見込まれる場合。普通教室の転用元として特別教室を活用する際に、その移転先を既存校舎内に確保することができない場合。","voiceIndex":78,"id":"exchange-025"},{"speaker":"まつざわ委員","kind":"質問","question":"昔は大崎中学校だったのが、今、豊葉の杜学園になってきました。これは本当にすごいショック。このパターンは結構あるのです。だからこそ、１年生のときに、特に保護者にはよく理解してもらわなければいけない部分で、周知のお願いをずっとしていましたけれども、周知をしてきていて、そういった学区変更の難しい説明というのを、具体的にどう工夫して分かりやすくしてきているのかというのを教えてください。","respondent":"石井学務課長","answer":"今後そういった説明をどうしていくかとか、周知についてどうしていくかということに関しましては、もちろん、学事制度審議会の中で出てくる答申はさることながら、そういった状況も踏まえた上で、今後発生することについては備えていかなければならないと考えているところです。","voiceIndex":80,"id":"exchange-026"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"小学校１年生のときに聞いていて、だんだんやっていくと、親も聞いている途中で忘れてしまうのです。だから、どこか３年生、４年生ぐらいでも、学校でもこういう制度を改めて説明などいずれしていただけると、すごくありがたいので、要望でよろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":82,"id":"exchange-027"}]},{"id":"topic-03","title":"令和６年度品川区立学校における体罰等の実態把握","agenda":"令和６年度品川区立学校における体罰等の実態把握","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"体罰等の実態把握は、この間の傾向を伺いたいのですけれども、増えているのか減っているのかというところです。それと、今回は中学校で暴言が１名あったということで、その後の対応というのはどうされているのか伺いたいと思います。","respondent":"酒川指導課長","answer":"品川区における体罰等の増減ですけれども、過去１０年間ですと、令和３年に体罰が１件ございまして、過去１０年間、体罰に該当するものはこの１件のみです。","voiceIndex":87,"id":"exchange-028"},{"speaker":"のだて委員","kind":"質問","question":"傾向については、そうすると、体罰は１回しかなかったと。指導、暴言は年間１０件ほどあったり、３件だったりということでしたけれども、減っているのか増えているのか、それとも横ばいなのか、伺いたいと思います。","respondent":"酒川指導課長","answer":"今のところ、なくなっているということは言えるかと、教員の意識が高まっていると判断できると思いますけれども、不適切な指導や暴言については、グラフにしたときに波が少しできてしまうという形で、年度を追うごとに。","voiceIndex":89,"id":"exchange-029"},{"speaker":"のだて委員","kind":"質問・要望","question":"体罰以外のところは、減っているとも言えないということでした。体罰も令和３年ということは４年前、結構最近だという感じがするのですけれども、そうしたことがないように、取組をしていっていただきたいと思います。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":91,"id":"exchange-030"},{"speaker":"若林委員","kind":"確認","question":"確認で、今回、暴言等が１人ということなのですが、相談シート等を配布して、児童・生徒から上がってきたものを、一旦教員等に確認して、本人が認めたものを１とか２とかとカウントするという理解でよろしいでしょうか。","respondent":"酒川指導課長","answer":"相談自体は、小学校で１４件、中学校で１０件、計２４件、相談自体はこれだけの数があります。東京都が作成した相談シートによる相談が、小学校で１０件、中学校で３件という実態となっております。","voiceIndex":93,"id":"exchange-031"},{"speaker":"まつざわ委員","kind":"質問","question":"今の話の中で、そうなると、不適切な指導、行き過ぎたと言っているのは、相談を受けたときに校長先生がヒアリング、聞き取りをして判断するということは、例えばそういった線引きといいますか、そのガイドラインというものはそもそもないわけですか。","respondent":"酒川指導課長","answer":"ガイドラインは区教委が持っておりまして、当然、学校現場の管理職も知っていてよいものではありますけれども、校長が聞き取りをして判断して上げてくるものではありませんで、校長はあくまで聞き取りを客観的にしてもらって、それを区教委に上げてもらう。","voiceIndex":98,"id":"exchange-032"},{"speaker":"横山委員","kind":"質問・要望","question":"分からないところ等があったので、ご説明をいただきたいと思うのですけれども、まず、３番の（６）の取組事例のところに、教員同士の声がけ、ヒヤリハットへの指摘などが増加しているという一文があるのですが、例えばどういったお声がけですとか、ヒヤリハットが増加しているのかというところが分かれば教えていただけたらと思います。","respondent":"酒川指導課長","answer":"ヒヤリハットの指摘が増加しているという３点目ですが、これはある小学校の取組でございまして、校長の意識が非常に高く、通常、年に３回程度、自らの取組、例えば体罰とか暴言とか性暴力とか、そういうものにつながる行為はないですかというような。","voiceIndex":101,"id":"exchange-033"},{"speaker":"横山委員","kind":"質問・要望","question":"理解いたしました。今回の発生した暴言等というものの事例に対しては、しっかりと事後のケアというのはされているのかというところを確認させていただければとの質問だったのですけれども、その辺りをご説明いただけたらと考えています。","respondent":"酒川指導課長","answer":"暴言が発せられた背景ですけれども、避難訓練では安全第一ということで、迅速に行動させるとか、安全に細心の注意を払わせるために、厳しいというか、そういった指導が行われることが多いのですが、今回は何か教員に負担がかかっていたとか、忙しい時期であったとか。","voiceIndex":103,"id":"exchange-034"},{"speaker":"横山委員","kind":"質問","question":"別の質問になってしまうのですけれども、先ほどほかの委員の議論でもありましたが、昨年度ですとか、ここ１０年くらいと比較しまして、今回は暴言等が１件ということで、かなり少ないと思っていまして、これの受け止め方についてなのですけれども、様々ご努力をしていただいている、また、声がけであったりとか、人権感覚みたいなところであったりとか、意識の高い先生方が増えてくださっていて。","respondent":"酒川指導課長","answer":"学校での校長先生たちの指導ですとか、先生方の人権意識の高まりですとか、繰り返し行ってまいりました教育委員会による研修等々が功を奏してきたと受け止めることができなくはないのですけれども、令和７年、８年、９年と継続的に見ながら。","voiceIndex":105,"id":"exchange-035"},{"speaker":"横山委員","kind":"質問","question":"子どもたちも先生方も、先ほどもお伝えしたのですけれども、人間ですので、幾ら適切な指導をしていただいているということがあっても、性格のマッチングみたいなところはどうしようもないところもあるので、それはいろいろな複数の目で、今、学校現場でもやっていただいているとは思うのですけれども、目の前の子どもたちの利益といった本来の目的をしっかり軸にしていただいて。","respondent":"酒川指導課長","answer":"保護者の相談に丁寧に対応していくこと、それから、学校ごとに必要に応じて学校公開等を行っていくこと、それから保護者会ですとか、個人面談とか、そういった機会で丁寧に情報公開していくこと。","voiceIndex":107,"id":"exchange-036"},{"speaker":"高橋（し）委員","kind":"質問","question":"その一方で、教員以外で学校の教育に関わっている方がたくさんいらっしゃって、発達障害教育支援員とか、あるいは校内別室指導の方とか、そういう方へも、体罰までいかなくても、言葉遣いとかいろいろあると思うのですが、その辺りの指導について、どうかということが１つ。もう１つは、中学校で、いわゆる体罰だったり暴言だったりが出やすいのは部活だと思うのです。","respondent":"酒川指導課長","answer":"他の職員ということで委員おっしゃいますとおり、様々なボランティアですとか、会計年度任用職員とかが入っております。正規の教員と会計年度任用職員なのですけれども、年間３回、都教委が区教委を通じて、各学校に研修を義務づけております。","voiceIndex":110,"id":"exchange-037"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"これは要望で、終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":112,"id":"exchange-038"},{"speaker":"筒井副委員長","kind":"確認","question":"私から相談シートについての確認なのですけれども、趣旨が児童・生徒向けでお配りするということは、体罰等の調査ですから分かるのですが、対象に児童・生徒と記載されていますけれども、この結果、相談シートを受けて、児童・生徒に聞き取りとかをするから、今回の対象ということにしているのかどうかということの確認と、相談シートを見させていただきましたけれども、これは匿名の場合。","respondent":"酒川指導課長","answer":"子どものプライバシーを侵さないように匿名で行われたものですので、ぜひそれは匿名で学校でも取り扱ってくださいということで、この人にやられましたという行為者に対しては、同様の聞き取りをするということになると考えています。","voiceIndex":114,"id":"exchange-039"}]},{"id":"topic-04","title":"子育て世帯へのお米支援プロジェクト申請状況","agenda":"子育て世帯へのお米支援プロジェクト申請状況","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"今回、高校生に拡大したということで、申込み数は高校生でどれぐらいだったのか、小・中学生でどれぐらいだったのかが分かれば伺いたいのと、前回と比べてどうかも伺いたいと思います。それと、配付に当たって子どもたちへの声かけや目視をすると。それで必要な支援につなげるということなのですけれども、この間、何か支援につながった部分があるのか、どういった効果が出るのかを伺いたいと思います。","respondent":"柏木子育て応援課長","answer":"今年度につきまして、まだ児童センターからは報告が上がってきておりませんので、まだ状況については把握してございませんが、昨年度につきましては、１館当たり１０件程度、支援につなげることがあったという報告は受けてあります。","voiceIndex":120,"id":"exchange-040"},{"speaker":"まつざわ委員","kind":"質問","question":"そういった中で、やる運営側に余裕がないと、例えば子どもの目視もそうです、声かけもそうですけれども、実際にやる余裕がないというのも、若干現場の声でも聞いているので、私もこうやって見ていて、これは相当大変だというのが私の肌感覚で、そういった部分で行政として、区として、例えば現場の人数がどうなるか分からないから、ばたっと来るのでしょうけれども。","respondent":"柏木子育て応援課長","answer":"ただ、今回、当初から昨年よりは申込み数が増えるだろうということで、昨年度と変えましたのが、事前に申し込む際に、受け取りをする週、どの週に取りに来るというのを選んで申請していただくようにしてございまして、ある程度、その週に来る人数が把握できるような形。","voiceIndex":125,"id":"exchange-041"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"昨年度より申請が上がったのは、うちもそうでしたけれども、学校にしっかり配付していただいて、どなたが言ったか覚えていないのですけれども、周知漏れが大分なくなって、数字が上がってきたというのがあったのですけれども、その中でも半分近くが未申請の中で、支援が必要な家庭があるかもしれないという部分で、今回ではしようがないにしても、今後そういった支援が届きにくい家庭への接触というか。","respondent":"柏木子育て応援課長","answer":"ただ、より支援が必要な家庭に支援が行くように、今回またやって、申請率は増えていますけれども、高校生も今後出てくると思いますので、お米の支援の中では、任意になりますけれどもアンケートも取ってありますので、そのアンケート結果も参考にしながら、次年度実施する際には。","voiceIndex":127,"id":"exchange-042"},{"speaker":"横山委員","kind":"質問","question":"１週間ぐらいとかで超過したのでしょうか。これは申込み順で、多分ホームページに書いてあるのであれなのですけれども、６月１７日以降の方が９月以降という形になっていると思うのですが、例えば食の支援がどうしても夏休み中に必要でという方がいた場合というか、そういったお問合せとかに対しては、どのように対応されているのかを教えてください。","respondent":"柏木子育て応援課長","answer":"当初予定を超過したタイミングですが、少し細かく言いますと、６月１７日の夜にもう超過をする見込みが立ちましたので、そのときの夕方の５時段階で、それ以降の申込みの方については９月以降配付ということでのお知らせと。","voiceIndex":130,"id":"exchange-043"},{"speaker":"まつざわ委員","kind":"質問","question":"アンケートとか、１０件のお話が今、支援につながったという話というのは、今後、文教委員会で報告というのはあるのですか。","respondent":"柏木子育て応援課長","answer":"今後、ご報告につきましては、中のほうでも検討させていただきたいと考えております。","voiceIndex":134,"id":"exchange-044"},{"speaker":"高橋（し）委員","kind":"意見","question":"高校生のことで、高校生に拡大したときに、どのように周知するかというのを私は始まるときに心配して、課長にもご相談したのですけれども、これは在学者のご家庭全員にメールを出すわけにいかないし、下に小学校・中学校のお子さんがいれば、高校もというのが分かるのですけれども、そこのところで、この数字をどのように判断するのか、もちろん支援を必要とする方が少なかったのかもしれないのですけれども。","respondent":"柏木子育て応援課長","answer":"高校生への周知ですけれども、６月の文教委員会の事務事業概要の説明以降、委員を含めて、ほかの委員からもお問合せをいただいております。その後、区内の都立・私立の高校に、本事業のポスターの掲示を各高校に依頼しています。","voiceIndex":139,"id":"exchange-045"},{"speaker":"高橋（し）委員","kind":"意見","question":"ほかの委員の方もおっしゃっているように、支援が届かないということや、あるいは区民の方全体に対して周知も必要ですので、今の高校生のところは、ぜひまたいい方策を考えて、より周知を徹底するようにお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":141,"id":"exchange-046"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7119#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":40868,"voices":147}},{"id":"r07-20250728-5","meetingId":"r07-cm07","date":"2025年7月28日","dateIso":"2025-07-28","committee":"総務委員会","time":"午後 １時００分～午後 ３時２８分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を43件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"令和７年陳情第２８号、「品川に城南空襲の碑を」の陳情","agenda":"令和７年陳情第２８号、「品川に城南空襲の碑を」の陳情","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"今年は戦後８０年、また、非核平和都市品川宣言４０周年ということで、「平和を考える」、また、「戦争とは」ということを大きく考えていく上で大事な年であると思っています。その上で、陳情では、城南空襲の碑、モニュメントを造ってくださいと。これは共産党としても、３月の予算特別委員会で同様に求めておりまして、区の考えとしても、今、ご答弁されたように、否定するものではなかったと思っています。","respondent":"藤村総務課長","answer":"どういった形の碑を造ると、どういった効果があるというお話をいただいたところですが、陳情者の方と、考え方というところは同じところもあるかとは思っておるのですが、区としての手法としては、今のところ少し違うところがあるのかというところで。","voiceIndex":14,"id":"exchange-001"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"これはやはり案内してくれる人がいなければ、詳細が分からなかったということが書かれております。それで、こうした会の皆さんと直接懇談していただいて、やはり１０年も活動を続けておりまして、３年前からはそうした城南空襲の足跡を見つけ、平和を考えるためにまちを歩いているということですので、取組を活かしていく方向でぜひ直接懇談していただきたいと思うのですけれども、いかがでしょうか。","respondent":"藤村総務課長","answer":"そういったところも一つの課題というところですとか、実際の戦争というところと区の平和事業がリンクしていったほうがいいのではないかというお話もそのとおりかと思いますので、会の方と直接の交流とか、そういったところも含めて、どういった形がいいのかというのは。","voiceIndex":16,"id":"exchange-002"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ぜひご検討いただいて、どういう形で残していくことを望まれているのかというのを詳しくお話ししていただいて、それで、やはりそういう町なかにそうした戦争の空襲の足跡等を見つけていくというのは、子どもたちのフィールドワークみたいな、そういうのにも使えますし、まち歩きなども、今、暑いさなかは大変ですけれども、それ以外の季節には、そういったまち歩き等もやられることも多いので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":18,"id":"exchange-003"},{"speaker":"西本委員","kind":"確認","question":"確認なのですが、子どもたちへの教育という意味でいうと、ここの担当ではないと思うのです。現状として、城南空襲を含めた教育というか、生涯学習でもいいのですけれども、そういうのはどこかでやられているケースがあるのですか。分からなければ、教育委員会に聞いてくださいと言われればそれまでなのですけれども、そういうのはあるのでしょうか。あまり聞いていないのです。位置づけを知りたいです。","respondent":"藤村総務課長","answer":"城南空襲に限ってというと、現在の取組については、教育委員会に聞いていただいたほうがというところはあるのですが、平和学習本体という形で考えると、広島に毎年中学生を派遣しておりまして、帰ってきた子どもが学校で報告を行うというところはありますので。","voiceIndex":19,"id":"exchange-004"},{"speaker":"西本委員","kind":"意見","question":"他区では、どうしても平和というと、広島・長崎という形になるのですけれども、ただ、品川区の中で何が起きていたのだということは、何かしらでまとめたほうがいいのかという、思いとしてはあります。なので、教育委員会に別途聞かないと分かりませんけれども、もう少し区民の皆さんに品川区の歴史の一つとして知ってもらうという活動が必要なのかと感じました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":21,"id":"exchange-005"},{"speaker":"須貝委員","kind":"質問・要望","question":"品川区としては、平和事業に対しては様々工夫をされ、区民に知らしめているかと考えております。それを、広島もそうですが、学生を派遣したり、平和を考えてくれと。今後も、地道な努力でしょうが、分かりやすいような文章、文面をつくって、それを知らしめる努力をしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":22,"id":"exchange-006"},{"speaker":"山本委員","kind":"意見","question":"本日結論を出すでお願いいたします。中身について申し上げます。戦後８０年の節目に当たり、城南空襲の記憶を次世代に伝えるために、長年活動を続けてこられた陳情者の皆様に心から敬意を表します。理由を申し上げます。結論として不採択といたしますが、皆様の活動は平和の継承に不可欠であり、今後、区民の皆様の理解が深まる中で、その在り方について議論が進むことを期待しております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":25,"id":"exchange-007"},{"speaker":"塚本副委員長","kind":"質問・要望","question":"この陳情者の方々が陳情に述べられている内容については、その思いや考え方ということについてはもちろん共鳴をするところでありますけれども、やはり区からのお話もありましたが、具体的な事業として、碑を建てるなどという個別具体的に何がいいのかということになると、それはやはりいろいろなところとの調整とか、いろいろなところとの合意形成とかといったことを踏まえながら。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":26,"id":"exchange-008"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"本日結論を出すで、採択でお願いします。マップに記していくというのは本当にいいことだと思いますので、ぜひ進めていただきたいと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":27,"id":"exchange-009"},{"speaker":"松本委員","kind":"意見","question":"本日結論を出すで、不採択でお願いいたします。これも思っています。同じモニュメントでも、何か物をどこかに造設するというだけではなくて、例えば、東日本大震災のときの一本松。ただ、いずれにしても、モニュメントという具体的なものについて、その手法が適切かどうかというのは、この中では私からは建てようということはなかなか申し上げられませんので、不採択といたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":28,"id":"exchange-010"},{"speaker":"須貝委員","kind":"質問・要望","question":"本日結論を出すということと、不採択でお願いしたいと思います。品川区にお願いしたいことは、城南空襲を語り継ぐ会の皆さんとぜひ話し合う機会を設けていただいて、区でも進めておりますけれども、品川の戦争の記憶を伝え、平和を願う取組について、よりよい方法を私は進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":29,"id":"exchange-011"},{"speaker":"西本委員","kind":"質問・要望","question":"本日結論を出していただきたいということと、不採択でお願いします。なので、品川区の歴史を語るという中に、こういうのをしっかり取り込んで入れていただきたいという思いがあります。なので、できれば、今回、取組をされている方と一緒に、どういうことがあったのかというのはまとめておくべきことなのではないかと思いますので、ご検討のほどよろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":30,"id":"exchange-012"},{"speaker":"須貝委員","kind":"質問","question":"今回の工事に対して、多数のＪＶ、業種が違う外壁工事と電気工事に入っていると思うのですが、本来、ここの事業所に頼むならば、電気事業所は事業所でまた頼むのが通例なのかという気がするのですが、今回は一切そういう手法ではなくて、１社に入札、決定となっているのですが、その辺について、三木小学校も宮前小学校の両方ともそうですね。それについて教えてください。","respondent":"佐藤経理課長","answer":"今回、工事の中、概要書にありますけれども、電気あるいは設備の工事も含んでおりますが、あくまで外壁工事をする中で設備を一旦外したり、あるいは取り付け直したりというところの工事ですので、新たに設備をつけるですとか、設備自体の改修をするですとか。","voiceIndex":37,"id":"exchange-013"},{"speaker":"須貝委員","kind":"質問","question":"すみません。質問が悪かったのかもしれないですけれども、電気工事というのは資格が必要ではないですか。そうしたら、やはり電気事業所に依頼するというのが通例だと思うので、ここの会社にしても、資格がなければ取り外せないのですから、それは少し違うと思うのですが、その辺、おかしいと思うのですが、どのようにお考えでしょうか。","respondent":"佐藤経理課長","answer":"１件の工事で発注いたしますけれども、そういった資格が必要ですとか、専門的な部分というのはどうしても出てきますけれども、その場合は、いわゆる下請といいますか、協力会社の協力を仰いで工事を行っていくと聞いておりますので、今回の工事についても同様かと思います。","voiceIndex":39,"id":"exchange-014"},{"speaker":"西本委員","kind":"質問","question":"今さらということかもしれないですけれども、三木小学校の３ページのところに入札状況調書というのがあって、令和７年６月２３日執行と書いてあるのです。宮前小学校のほうは、同じところに令和７年６月２５日になっているのです。これはタイミング的にはどういう感じなのですか。これ、どういう意味なのか、教えてください。","respondent":"佐藤経理課長","answer":"執行日ということは、この前に電子入札で区のほうは発注および入落札をやっていますけれども、開札をする日が執行日ということで載せしています。","voiceIndex":41,"id":"exchange-015"},{"speaker":"西本委員","kind":"質問","question":"三木小学校のほうは、落札したのが加地建設ですよね。宮前小学校のほうは、４番目に加地建設が辞退されているのですよね。これ、同じ時期に出されているということなのですかね。これ、同じタイミングで２つの三木小学校と宮前小学校と入札というのをかけているのですか。それで加地建設は両方にかけた形という理解でよろしいのでしょうか。","respondent":"佐藤経理課長","answer":"事業者が両方に手を挙げられるかというお話なのですけれども、これについては、参加表明自体は両方できるというところですが、この後、詳細な設計図をもらって、それぞれ見積もるわけなのですけれども、その中で事業者が実際どちらの工事に札を入れるかというところは。","voiceIndex":43,"id":"exchange-016"},{"speaker":"西本委員","kind":"質問","question":"本来は自分たちの余力として、力として１つの工事しかできないのに、手当たり次第にやって、そこが落ちてしまった場合に、不調になってしまうのですかというような状況を私は心配してしまうのですけれども、そういう規制とかはかけられないものなのですか。そこの兼ね合いはどうなっているのでしょうか。全くついていないから、取りあえず改修はしようかというところなのですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":45,"id":"exchange-017"}]},{"id":"topic-02","title":"品川区入札監視等委員会の設置","agenda":"品川区入札監視等委員会の設置","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"これは適切なのか入札の段階で審議したときに、専門的な知識がなくて、その方たちが判断できるのですか。なぜ私がそう言うのかというと、先ほど三木小学校の場合には、落札者と第２位の方の金額を見ると、入札価格の差が０.４％の差しかないのです。そういうことをチェックしなければ、入札監視等委員会を設置する意味はないのではないですか。どうなのですか。その辺、ご見解をお聞かせください。","respondent":"佐藤経理課長","answer":"最後、３点目ですけれども、専門、学識を有する方として３人に入っていただいておりますが、手続に関するところを議論いただくというところですので、その基準をお示ししまして、それがそれぞれの分野の知見からどうなのかということを検討いただいて。","voiceIndex":52,"id":"exchange-018"},{"speaker":"須貝委員","kind":"確認","question":"企画課でも財政課でもそうですけれども、１円単位で細かく事業に対して予算を立てて動いているわけではないですか。今、手続を見るだけだったら、申し訳ないですけれども、どなたでもできるのではないですか。経理課長、違いますか。手続がいいか悪いか確認するなら、職員だけで大丈夫ではないですか、それだったら。何かおかしいから改革しようとして、区でも今、何かやろうとしているのではないのですか。","respondent":"佐藤経理課長","answer":"もう１点の、繰り返しになってしまいますけれども、入札の金額の具体的なところですが、やはり人件費、あるいは資材費が高騰しているという中で、事業者の努力する幅もなかなかなくなってきているというところは、意見として事業者からもいただいているところですし。","voiceIndex":54,"id":"exchange-019"},{"speaker":"須貝委員","kind":"質問・要望","question":"やはり専門職員というのは、専門家が入らなければ駄目ではないですか。工事費というのは、年間何百億円という金額を品川区でも使っているわけではないですか。やればやるほど、私はきちんとした契約制度、会計制度になると思いますので、ぜひそういうところはこういう名前だけ、入札監視委員会とか、こんなきれいな名前をつけないで、つけるなら、きちんと私はやっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":56,"id":"exchange-020"},{"speaker":"西本委員","kind":"質問・要望","question":"透明性というのはどういうことで透明性を目指していくのですか。今と何が違ってくるのでしょうか。公正な競争を促進するというのは、今までもやっていると思うのですけれども、何が変わるのでしょうか。意味がなくなってしまうような状況にはならないように、何が変わってくるのかということもきちんと示していただきながら進めていただきたいと思いますが、いかがでしょうか。","respondent":"佐藤経理課長","answer":"契約事務は執行していると認識しておりますけれども、透明性の確保というところは、同じところでも、こういった学識の方に入っていただいて、その方々にきちんと説明をして、その上でご意見をいただくということですので、より透明性が高まるということだと思います。","voiceIndex":57,"id":"exchange-021"},{"speaker":"西本委員","kind":"質問","question":"なおかつ、透明性を確保と言う以上は、何かがあるから、もっとさらによくしていかなければいけないという課題がなければ、お金を使ってやる必要はないのではないですか。課題があるから、それをよくしようということなのではないですか。何で専門家の方が必要なのですかという。その認識というか、これからこれをどのように活用していくのかというところを教えてください。","respondent":"佐藤経理課長","answer":"いわゆる第三者の方が我々の行政の説明を聞いた上でご意見を言っていただくということで、我々としては問題ないという意見だとしても、それをいただいたということで、先ほど委員からもありましたけれども、公表していくということで、より透明性が高まって。","voiceIndex":59,"id":"exchange-022"},{"speaker":"西本委員","kind":"質問・要望","question":"お願いというか、要望といいますか、積算値ですよね。示しますよね。私たちの中に。そこはあれですけれども、トータルでしかできないのかもしれないのですけれども、でも、そこのどれぐらいのそういう細かい数値というところも必要になってくるのではないかと思うのですが、今後、これを設置することによって、そういう積み上げの積算値みたいなものは出さないのですか。出すのですか。","respondent":"佐藤経理課長","answer":"工事の積算のところですけれども、これまでもご説明はしておりますが、最新の単価に基づいて積算しているというところですが、これを全部公表といいますか、委員会でご議論いただくというのは、少しそこの場面ではないかなと考えますので、入札に関するところ。","voiceIndex":61,"id":"exchange-023"},{"speaker":"西本委員","kind":"質問","question":"なので、どういうところにどれぐらいのお金がかかってという、だからトータルこれぐらいになりますと。いろいろ今、契約案件と言っていましたけれども、全てに関してここで議論し、報告をするという方向なのかというのを教えてほしいのです。そういうのもあったので、細かいものも全部これにかけて報告という形で上げられるのか、あと、一定のこれ以上とかという制限がかかるのか、そこだけ教えてください。","respondent":"佐藤経理課長","answer":"いわゆる標準服の無償化というところについては、今、教育委員会のほうでスキーム含めて検討しているというところで聞いておりますので、今後、どういったスキームになるかによって、それが対象になるかどうかということになってくると思います。","voiceIndex":63,"id":"exchange-024"},{"speaker":"松本委員","kind":"意見","question":"今、議論を聞いていて、いろいろあると思ったのですけれども、まず１つ、評価するべきところは、対象が公共工事だけではないというところは、これは他自治体との比較で、売買まで入れているところも比較的出てきているとは思うのですけれども、場合によっては２３区みたいに公共工事だけというところもあるので、そこは後発というところで入れていただいていればいいのかと思います。","respondent":"佐藤経理課長","answer":"実際の委員会のどこを対象にするかというところは、第１回のときに、どのように委員会を進めていくかということを委員の中でご議論いただくということを予定しておりますけれども、委員のほうで、今ご指摘あったように、他区の事例ですと、委員あるいは委員会が。","voiceIndex":65,"id":"exchange-025"},{"speaker":"松本委員","kind":"意見","question":"そうすると、多分、委員の選定がすごく大事になってくるかと思っています。なので、弁護士ということで、１つの職種を挙げましたけれども、それに限らず、できるだけこの入札の制度を専門とされている方を選任していただくようにお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":67,"id":"exchange-026"}]},{"id":"topic-03","title":"令和７年７月２０日執行参議院議員選挙の結果","agenda":"令和７年７月２０日執行参議院議員選挙の結果","exchanges":[{"speaker":"西本委員","kind":"確認","question":"そういった場合に、本人確認というのは難しいといえども、品川区で何ができるかといったら、どういう言い方か、よく考えなければいけないところではありますが、本人が行ってくださいみたいな啓発は、注意喚起ぐらいはできると思うのです。そういうことを少しやっていただくことによって、抑止力にもなるのではないかと思うのですが、この点はいかがでしょうか。","respondent":"今井選挙管理委員会事務局長","answer":"ただ、あくまでもやはりスムーズに運用するために、不在者投票の裏面に宣誓書を書いていただくなどしておりますので、それは職員が疑義を感じたときに対応していくものと考えております。","voiceIndex":72,"id":"exchange-027"},{"speaker":"西本委員","kind":"質問・要望","question":"だから、広報で出すではないですか。選挙がありますよみたいな広報があるので、そこに小さくてもいいから、他人を装っての投票は公職選挙法に違反しますみたいな、そういう一般的な考えでいいのですけれども、そういうのも入れることによって注意喚起になるのではないかと思うのですが、そこのところは工夫をしていただきたいと思いますが、いかがでしょうか。","respondent":"今井選挙管理委員会事務局長","answer":"選挙特集号の広報などのお話をされていると思うのですが、やはり今回の場合でも、２票あって、順番はこのように投票していただきますという、まずはきちんと選挙をしていただく、投票していただくための説明を、なるべく紙面できちんとすることから。","voiceIndex":74,"id":"exchange-028"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"要件の緩和というのですか。そういうところを国にも引き続き求めていっていただきたいと考えていますが、いかがでしょうかということをお願いします。","respondent":"今井選挙管理委員会事務局長","answer":"２点目の不在者投票の中の病院や老人ホーム等における投票ですが、こちらは必ず選挙ごとに病院や老人ホームの方に説明会を実施しておりまして、こちらは期日前投票期間は、病院のほうでは、老人ホームでは、ご申請があれば、たとえ全体で投票を済ませたとしても。","voiceIndex":76,"id":"exchange-029"}]},{"id":"topic-04","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"須貝委員","kind":"質問・要望","question":"自分自身としても、このような場所にもし行くようならば、私は辞退したいと思います。もう一度、委員長、副委員長にお任せしたとはいえ、やはり競馬事業に対して帯広競馬場に行くということは、今のこの時代で、品川区議会総務委員会としては、私はやめるべきだと。もう一度再考していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":81,"id":"exchange-030"},{"speaker":"石田（秀）委員長","kind":"質問","question":"これは私から答弁というわけでもない。伺っておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":82,"id":"exchange-031"},{"speaker":"石田（ち）委員","kind":"意見","question":"私も競馬については、公営ギャンブルと言われますけれども、やはりギャンブルというところである以上、依存症の方も多くおられると。そこで苦しまれている、また、そのご家族等々もあると思うのです。そこも含めた対策というのも調査するとかでしたら分かるのですが、競馬だけということになりますと、私も若干の、大丈夫なのだろうかという思いはあります。意見です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":83,"id":"exchange-032"},{"speaker":"山本委員","kind":"質問・要望","question":"ここまで行政視察先のご選定、ありがとうあります。というのは、競馬事業も全国様々、ほかにもある中で、この帯広市が視察にふさわしいと思われたということと、あと、市町村交流というところも、いろいろな可能性があるところで沼田町を選ばれたというので、やはりそのお考えというところをお伺いしたいです。調整中なのかどうかというのも分かれば、教えていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":85,"id":"exchange-033"},{"speaker":"須貝委員","kind":"質問","question":"我々、やはり総務委員会として、品川区議会できちんと認定されている総務委員会ですから、品川区でやはり発展とか区民サービスの向上に私たちは貢献するようなことをできるような、そういう事業、また、政策とかそういうことを議論する、私はそういう場だと考えています。ですから、私としては、先ほども申し上げましたけれども、もしこういうことならば、総務委員会の視察には参加いたしません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":87,"id":"exchange-034"}]},{"id":"topic-05","title":"その他","agenda":"その他","exchanges":[{"speaker":"澤田委員","kind":"質問・要望","question":"今回の件についてですけれども、行政側の皆様も、周知啓発や研修などによって、そもそもハラスメントの被害者、加害者を生み出さない取組ということについてより一層力を入れていただきたいということと、今後、ハラスメントを受けて苦しむ職員の方が相談する際に、不利益を被らないよう、苦情処理委員会の外部人材の……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":90,"id":"exchange-035"},{"speaker":"澤田委員","kind":"意見","question":"今回の件ですけれども、周知啓発や研修などによって、そもそもハラスメントの被害者、加害者を生み出さないという取組に今も取り組んでいらっしゃると思うのですが、より一層力を入れていただくとともに、今後、ハラスメントを受けて苦しむ職員の方が相談をする際に不利益を被らないよう、苦情処理委員会の外部人材の登用など。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":92,"id":"exchange-036"},{"speaker":"山本委員","kind":"質問・要望","question":"石田委員長、議題としてお取上げいただきありがとうあります。体制が整備されているとされながら、相談件数がゼロ件というのは、まさに相談できない環境になっていることを意味しているのではないでしょうか。以上の思いから、今後の対応として、特に次の２点を強く要望いたします。以上の２点を確実に進めることで、真に働きやすい職場環境の整備を強く求めます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":93,"id":"exchange-037"},{"speaker":"石田（ち）委員","kind":"意見","question":"ですが、部長級の３割がハラスメントを受けたことがあるということで、それ自体は大変なことなのですけれども、それをもって加害者は区長や副区長だと決めつけることはできないと思います。議員からということもあるかもしれません。こうした調査を基に、今さらに進めるべきことは、安心して相談ができ、適切に被害者に寄り添った対応がされる、そうした仕組みをつくることこそ必要だと思っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":94,"id":"exchange-038"},{"speaker":"松本委員","kind":"質問・要望","question":"どちらも、多分、行政側も認識があると思いますので、我々議会としては、こうした体制整備が行われたら適宜ご報告いただいて、それで我々としても、具体的な被害状況ではなくて、体制のほうをご報告いただいて、我々としても、改善点があるのであれば、ご指摘させていただきたいと考えていますので、情報公開のところをしっかりとしていただくよう、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":95,"id":"exchange-039"},{"speaker":"須貝委員","kind":"質問","question":"４月２５日。それに準じて恐らく区のほうも、これは調べなければいけないのだということで私は動いたと思うのですが、実際、まだその段階で、それが実態なのか、実際どうなのかというのは、もう一回アンケートなり意見をいただかないと分からないのではないのですか。でも、すみません、それ、どういう内容なのですかというのをもう一度お聞きする場が私は必要ではないかと思うのです。意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":96,"id":"exchange-040"},{"speaker":"西本委員","kind":"質問・要望","question":"安心できるような相談機能を見直すべきだとか、それから、今回のアンケートの内容をもっと広く調べるべきではないのかとか、あとは、個別のきちんと話ができるような、そういう体制が取れるのだろうかとかということを、私たちの今までの意見も、大半、まとめるとそんな感じだと思いますので、それに対して誠意のある行動を示していただきたいと強くお願いしたいと思って、私の考えといたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":97,"id":"exchange-041"},{"speaker":"塚本副委員長","kind":"質問・要望","question":"今回の結果を踏まえて、区として対応しなければいけない課題とかというのをいろいろ認識しているということは、恐らくそうなのだろうと思いますし、それに対しての対策ということもしっかり取り組んでいっていただきたいというところで、一番大事なのは、ここは皆さんと同じところだと思いますけれども、安心して相談できるというのですかね。この状況も非常によくない状況だと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":98,"id":"exchange-042"},{"speaker":"須貝委員","kind":"意見","question":"すみません。前も委員長がおっしゃっていたかもしれないのですが、こういう話を品川区議会としていろいろ議論をして、総務委員会に出たわけですが、品川区議会としても、何かそれに対する、職員を守る、職員を支えていくという意味で、委員長のほうから議長のほうに、区議会としても何らかの対応策を考えられたら、職員に対する支援、それを考えられたらどうかと。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":102,"id":"exchange-043"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7125#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":43750,"voices":104}},{"id":"r07-20250729-21","meetingId":"r07-cm07","date":"2025年7月29日","dateIso":"2025-07-29","committee":"子ども若者支援・共生社会推進特別委員会","time":"午後 １時００分～午後 ４時１８分","status":"正式会議録","sourceType":"formal","overview":"子ども若者支援・共生社会推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を29件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"西村委員","kind":"質問・要望","question":"ご説明、ありがとうございました。視察もありがとうございました。現地でも質問させていただいたのですけれども、小学校との接続を含めてすばらしい幼児教育をされてきたということが確認できましたし、ほかの施設でまねができるものではないので、本当にそっくりそのまま別の園でも実施していただきたいなと個人的には感じるところでした。","respondent":"染谷保育施設運営課長、石井学務課長","answer":"現状のそういったところと、実際に時間延長をすることによって幼稚園教諭もそうですし、それから会計年度任用職員の加配というのは当然必要になってくる部分もありますので、ニーズをきちんと確認させていただいた上で。現行、小学校の校長と幼稚園の園長を兼任している状況ですけれども、本日視察に行かれた城南幼稚園、あとは浜川幼稚園、続いて第一日野幼稚園、そして台場幼稚園の４校となっています。","voiceIndex":8,"id":"exchange-001"},{"speaker":"西村委員","kind":"質問","question":"資料の中に区立幼稚園が担うべき役割を踏まえた方向性の検討とありまして、視察の中で園長先生から受皿になっている部分があるというお話があったのですけれども、区として区立幼稚園の担うべき役割というのは様々な時代背景があると思いますので、現状においてどのように捉えておられるかをお聞かせください。","respondent":"芝野保育入園調整課長","answer":"近年では特別な配慮を要する児童への対応とか、幼稚園、小学校への接続もニーズとして出てきておりますので、そちらは幼保一体施設のほうでしっかりと受け止めて進めていきたいというふうに考えております。","voiceIndex":11,"id":"exchange-002"},{"speaker":"西村委員","kind":"質問・要望","question":"障害児のお子さんに関しては、特に区立園に安心感を持つという保護者の方が多いのだなということを改めて感じておりますので、幼保一体を含めて障害児の受入れ体制というのをしっかりとやっていただきたいなというのと、やはり保護者にとって区立であるということがすごく安心感につながっているのだなというのを改めて感じたところです。","respondent":"芝野保育入園調整課長、石井学務課長","answer":"城南小の件につきまして、文教委員会のほうで出された件ということで、こちらに私も出席しておりましたので拝見させていただきまして、需要についてはあくまで予測ということですので。最新の人口推計ですと一定程度それまでに行っていた人口推計よりもピークが後になってくるというふうな現状もありますので、そういった動向も踏まえながら丁寧に他課としっかり連携していきながら進めていきたいと考えているところです。","voiceIndex":13,"id":"exchange-003"},{"speaker":"鈴木委員","kind":"質問・要望","question":"視察を組んでいただいて、ありがとうございました。あれだけお話を伺って熱心に取り組まれているという姿を見たときに、閉園という方針が区のほうで出されていますけれども、これは改めてもう１回検討し直すということが必要ではないかなというふうに思ったのですが、もう決定ということで進めていくということは変えられないのか伺いたいです。","respondent":"芝野保育入園調整課長","answer":"２つ目の文教委員会の中で城南幼稚園、浜川幼稚園の検討のですが、こちらは毎年検討のほうはさせていただいておりまして、これは１１月に毎年新規入園の申込みをされる方が統計上出てきますので、こちらのほうで入園状況を見させていただきながら検討をしております。","voiceIndex":16,"id":"exchange-004"},{"speaker":"鈴木委員","kind":"質問・要望","question":"毎年入園の状況を見ながら検討していくというのは、入園の希望者がここまでだったら具体的な検討に入るとか、そういうものがあるのか。それから、伊藤保育園のその後の状況を見ながらということですけれども、それは具体的にどういうことなのかということもお聞かせいただきたいと思います。あったら具体的に教えていただきたいと思います。","respondent":"芝野保育入園調整課長、佐藤保育事業担当課長","answer":"公立だからできる支援ですが、もちろん私立でも同じような支援ができないかどうかというのはきちんと私立のほうに伺って進めていきたいと考えていますが。先ほどの説明に少し補足をさせていただきたいのですけれども、私立幼稚園におきましても障害のあるお子さん、特別な支援が必要なお子さんをお預かりいただきましたときに。","voiceIndex":18,"id":"exchange-005"},{"speaker":"鈴木委員","kind":"質問・要望","question":"城南で言えば台場。それから、地域の方々に支えられながら地域としても本当に継続していただきたいという思いがあっていろいろと連携されているんだなという思いがしましたので、ぜひともこれは廃園の方向を改めて検討し直すというところも視野に入れていただきたいということも要望として改めて出させていただきたいと思います。","respondent":"染谷保育施設運営課長","answer":"子ども家庭支援センターを含む関係機関との連携のお話があったかと思うのですけれども、例えば今日の視察の中で話がありましたグループウェアが共通で使えるとかという、そういうツールの部分の話に関しては一定あるかと思うのですが。","voiceIndex":21,"id":"exchange-006"},{"speaker":"澤田委員","kind":"質問","question":"幾つか質問があるのですが、伊藤幼稚園が閉園となりましたけれども、閉園に向かって、終了に向けてというか、いろいろと工夫を凝らしてこられたと思いますが、閉園が決定したときの職員の皆さんのキャリア形成、いつぐらいに閉園しますよというのが決まったときの辞めるまでの、閉園までのキャリア形成だったり、閉園後の身の振り方というか。","respondent":"石井学務課長","answer":"そうしたことも含めて、もし仮に区立幼稚園が閉園したときの教員の処遇に関しましては、区立幼稚園全体の退職者数とかの状況も踏まえながら、幼稚園の教員として区内の幼稚園で引き続き勤務できるような形で。","voiceIndex":23,"id":"exchange-007"},{"speaker":"澤田委員","kind":"質問","question":"次の質問ですが、現在の城南幼稚園について先ほどいろいろと質疑がありましたけれども、行政として考えていらっしゃる城南幼稚園の運営上の課題、ソフト面での課題についてもし考えていらっしゃることがあれば教えてください。","respondent":"染谷保育施設運営課長","answer":"運営上の課題ですが、幼保一体施設の部分とも関連するところであるのですけれども、年齢区分型で実施している幼保一体施設に比較して、やはり園児数が少ないというところが一つあるかと思います。","voiceIndex":25,"id":"exchange-008"},{"speaker":"澤田委員","kind":"質問・要望","question":"分かりました。人数がやはり年々減少してきて、ほぼ横ばいなのか、減ったり増えたり移動はあってもというところで、先ほども１０人がボーダー、半分がボーダーというところでお伺いしましたけれども、そこについてはちょっと難しいのかなと思います。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":27,"id":"exchange-009"},{"speaker":"せらく委員","kind":"質問","question":"先ほどの澤田委員の質問に関連してですけれども、今は区立幼稚園、単独園で城南幼稚園と浜川幼稚園については人数が減ってきているところが課題というお話だったと思うのですが、人数が減ってきて教育活動が思う存分できないといいますか、そういったところは子どもにも影響する部分だと思うのですけれども、費用的にも影響してくるものでしょうか。","respondent":"染谷保育施設運営課長","answer":"ただ、園児１人当たりとして見た場合につきましては、やはりそういった施設のほうが園児数は多くなっているような状況がありますので、園児１人当たりで見た場合については当然ながら園児数が少ない園のほうがコスト的にはかかっているという状況にあるかと思います。","voiceIndex":28,"id":"exchange-010"},{"speaker":"せらく委員","kind":"質問","question":"分かりました。視察でお話を聞いていた中で、私立と区立の単独園ですけれども、違いとしてはやはり３歳は預かることができないので私立を選ぶ方もいらっしゃるというようなことが出ていたと思いますが、単独園に限り例えばモデル的に３歳を受け入れて人数を増やすだとか、そういったことは考えられたことはありますでしょうか。","respondent":"芝野保育入園調整課長","answer":"３歳児の受入れですが、先ほども少し答弁させていただいたとおり、私立幼稚園の補完ということで始まっている区立幼稚園ですので、現状ではその考えは持っていないです。","voiceIndex":30,"id":"exchange-011"},{"speaker":"せらく委員","kind":"質問","question":"私立のほうが長く経営されているだとか、そういった事情も以前からお聞きしていますので、そういったところの受皿という意味で区立園をやっているということが分かりましたので、ありがとうあります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":32,"id":"exchange-012"},{"speaker":"澤田委員","kind":"確認","question":"今もお話がありましたように、区立幼稚園というのはあくまで私立幼稚園の補完であるというところですけれども、特別支援の受皿に今はなっているというところで、私立幼稚園には加配を区からというのはできないかと思うのですが、人を雇う際に助成を出していらっしゃるではないですか。私立幼稚園の中で特別な支援が必要なお子さんを預かっている園は何園あるのか、もう一度確認させてください。","respondent":"佐藤保育事業担当課長","answer":"特別な支援が必要なお子様をお預かりいただいている私立幼稚園の数についてですが、こちらは入園されている状況が年度によって異なってきますので、一概に何園だとお話しできないところもあるのですけれども。","voiceIndex":33,"id":"exchange-013"},{"speaker":"澤田委員","kind":"質問","question":"例えば、台場幼稚園でなくてもほかの近くで入れるような私立園で、もし「うちは受入れをしていないよ」みたいなところがあるのであれば、そういう園にも特別な支援が必要なお子さんに対応する方を入れるとこういう助成が出ますよみたいな形で進めていただくことで、台場幼稚園まで行かなくても城南幼稚園が閉園になった際に近くの幼稚園で通える場所があるという安心感をつくるためにもそういう活動というか。","respondent":"佐藤保育事業担当課長","answer":"大前提といたしまして、どういったお子さんであっても私立幼稚園にお預かりいただくというのが基本であります。ただ、私学助成の園になりますと園の方針等々というものがありますので、そうした方針と保護者の方がご納得いただいて入園になっているというものがあります。","voiceIndex":35,"id":"exchange-014"},{"speaker":"澤田委員","kind":"意見","question":"八潮幼稚園のことをしっかり理解できていなくて、申し訳ありません。でも、仮に城南幼稚園が閉園になったとしても、特別な支援が必要であってもなくても通える幼稚園は台場幼稚園もそうですし、ほかにもいろいろとあるというのが分かったので安心しました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":37,"id":"exchange-015"},{"speaker":"大倉委員","kind":"質問","question":"先ほど来お話があった閉園後の地域課題とかニーズに沿ってということで、今区が考えている地域課題とかニーズというのはどういったものになるのでしょうか。その地域課題とかニーズというのはどうやって根拠というか、アンケートなのか、どういったもので示していけるのか教えてください。","respondent":"芝野保育入園調整課長","answer":"地域課題、ニーズの件のお尋ねですが、閉園が決定しました段階で保護者、地域の方にしっかりとお話をお聞きさせていただきまして、その中でその前提として活用が決まっていればそれをお伝えするですが、そうでなければそこでしっかりとニーズを拾わせていただきまして。","voiceIndex":38,"id":"exchange-016"},{"speaker":"大倉委員","kind":"質問","question":"もう１つ疑問に思っていることは、まさに今言っていたように何になら活用できるのかというのは学校施設になるのか分かっていないのですけれども、そこはどういう施設なら活用できるとか、そういったルール、本部のほうとも連携するというお話もあったと思うのですが、その辺の活用ができるものは限られているというふうに思ってはいるのですけれども、どういったものが活用として想定されていたり。","respondent":"佐藤子ども未来部長","answer":"したがいまして、企画部門のほうでは各地域でのニーズでありましたり、区民のお声でありましたり、要望というのは常に把握しておりますので、その辺でどういった施設が少ないかというのはリサーチしているところでありますが。","voiceIndex":40,"id":"exchange-017"},{"speaker":"大倉委員","kind":"質問・要望","question":"分かりました。相談しやすい体制というのが何度もお話の中で出てきたかなという、園としての取組としてそういう体制をつくっていくというところでもあったかなと思いますけれども、そういったところも含めてぜひ様々検討していただければと思いますので、要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":42,"id":"exchange-018"},{"speaker":"つる委員","kind":"質問","question":"そういう意味では、既存のニーズ。その上で大きい方向性というのは、単独園の方向性は示されているのですが、その上で例えば今日の資料でいただいている経緯の２行目の後半に就学前人口についてあって、就学前人口が減少に転じ今後も減少傾向が続くと見込まれるというふうにあるわけですが、これの期間というのはどのぐらいの想定を見て、推計を見て前提としてあるのか改めて教えてください。","respondent":"芝野保育入園調整課長","answer":"就学前人口の減少等々のこれからの考え方ですが、この４月に子ども計画を策定させていただきまして、就学前人口につきましては令和７年が一番少ない状況で、そこから緩やかな増加に転じるということで、令和１１年度までの推計値のほうが出ております。","voiceIndex":43,"id":"exchange-019"},{"speaker":"つる委員","kind":"質問","question":"今のご答弁の中に企画という表現もありましたけれども、区全体の人口の取り方と子ども計画上の人口の取り方、これは住民基本台帳より作成ということであるわけですが、その前提が減少なのか増加なのかということで方向性は決まっているわけですがあくまでも推計なので、これは先ほど現場でもいろいろ伺って、質疑ではないところでもいろいろな声としては、例えば勝島ですとかいろいろなエリアでのまちづくり。","respondent":"芝野保育入園調整課長","answer":"申し訳ございません。この資料の前提をご説明することが漏れておりました。こちらの資料につきましては、令和３年、４年に検討が進められました当時の資料を一部加工させていただいていますので、この背景につきましては令和３年、４年当時の状況が記載されております。","voiceIndex":45,"id":"exchange-020"},{"speaker":"つる委員","kind":"意見","question":"だから、減少なのか増加なのかそもそものところがあるわけですけれども、あくまでも推計で増加傾向の中で行政、ニーズ、行政の財産の管理上の幼稚園の課題という観点でこの間ずっと、特に令和４年は集中的にという中にあっての前提だということですね。そこは、整理していくことが必要と思います。今後またいろいろな質疑をやっていくときに前提が違ってしまうといけないのかなと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":47,"id":"exchange-021"},{"speaker":"西村委員","kind":"質問","question":"２回目で申し訳ありません。２点、伺いたいです。過去の議事録で廃園後の活用で、例えば学校に転用というようなことになった場合に幼稚園から学校というのは転用ができない形になっており、費用的なところはもしやるとしたら返還という形になるという議事録がありました。ちょっと分からないと思いましたので、この部分を教えていただければと思います。","respondent":"芝野保育入園調整課長","answer":"学校への転用の件ですが、幼稚園施設から学校施設に転用する場合には用途が変わるですので、それに対して一定の補助が出ております。そちらのほうを返還するというようなことです。","voiceIndex":48,"id":"exchange-022"},{"speaker":"西村委員","kind":"質問","question":"理解しました。ですから、返還したら転用できるという認識でよろしいですか。","respondent":"芝野保育入園調整課長","answer":"返還したらできるということで、今は考えております。","voiceIndex":50,"id":"exchange-023"},{"speaker":"西村委員","kind":"質問・要望","question":"保育ですとか教育は大変目に見えづらくて、子どもが育ってからでないとその成果が分かりづらい部分があったりしまして、このノウハウは財産ですので必ず何かしらの形で踏襲をしていただきたいというのはぜひともお願いをさせていただきたいと思うのですが、一方で園長先生もおっしゃっていましたが。","respondent":"佐藤子ども未来部長","answer":"その辺は我々といたしましても強く心に思っておりますので、その辺と行政財産の有効活用も含めてしっかり進めていきたいと考えています。","voiceIndex":52,"id":"exchange-024"},{"speaker":"鈴木委員","kind":"質問・要望","question":"基本的なことを教えていただきたいのですけれども、預かり保育の保護者負担というのはどういう状況になっているのですか。今は保育園にしても保育料の無償化というのがどんどん進んで、基本自己負担がなく預けられるというのがどんどん進んでいると思うのですが、そういう中で預かり保育がどういう状況で、区としても今後どう考えられているのか、その点を教えていただきたいと思います。","respondent":"染谷保育施設運営課長","answer":"具体的には、１日当たり４５０円が上限というような形で現状はなっているところです。","voiceIndex":54,"id":"exchange-025"},{"speaker":"鈴木委員","kind":"質問・要望","question":"利用料は１日４００円、一定の条件を満たし区の認定が下りた場合は無償化となりますとここには書かれているのですけれども、４５０円までは無償化になるということでしょうか。その点をお聞かせいただきたいです。それから、預かり保育が基本的に単独園は９時から１７時までということで、幼保一体は７時半から１８時半までという状況になっているのか、そこが実際はどうなっているのかを教えてください。","respondent":"染谷保育施設運営課長","answer":"具体的には、先ほどちょっとご説明させていただいた年齢区分型と言われる御殿山すこやか園と二葉すこやか園の２園については預かりの時間が長く、夕方１９時半までという時間設定になってあります。","voiceIndex":56,"id":"exchange-026"},{"speaker":"鈴木委員","kind":"質問・要望","question":"単独園だから１７時までというわけではなくて、そこの地域の状況、なぜそういうふうに園によっての違いがあるのか。例えば、地域の中で要望が多ければ拡大されるというふうなことも検討できるのか、そこら辺のところはどうなっているのかも教えてください。","respondent":"染谷保育施設運営課長","answer":"時間帯の設定につきましては、実際にご要望も受けながら必要に応じて設定の変更自体は可能であるというふうには考えておりますけれども、先ほどご説明させていただいたとおりで、時間延長をすることによってかかってくる経費の部分もありますので。","voiceIndex":58,"id":"exchange-027"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そういう中で、先ほども廃園の検討というところはクラス編成が１０人以下でできなくなるとか５０％以下になるというふうなところが基準と言われましたけれども、今日視察でいろいろなお話を伺う中でこの園がどれだけ大きな役割を果たしているのかというのを実感したのですが、そういうところでは実際に通われている方ですとか、地域の方がその幼稚園をなぜ選んでいるのかだったり。","respondent":"芝野保育入園調整課長","answer":"なので、まず一義的にはクラス編成ができる人数が集まるのか、在園率が５０％を超えているのかどうか、こちらのほうで判断させていただきながら、ご理解のほうは丁寧に各地域のほうを回らせていただいてやっていきたいというふうに考えておりますが。","voiceIndex":60,"id":"exchange-028"},{"speaker":"鈴木委員","kind":"質問・要望","question":"なので、地域にとっての財産というふうなこともあると思いますし、利用者にとっての財産というふうなこともあると思いますので、私はぜひ当事者の声も聞きながら、これがどれだけ豊かな、大きな財産なのかというところも検討の中にぜひ入れていただきたいということは要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":62,"id":"exchange-029"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7127#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=21&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":20674,"voices":64}},{"id":"r07-20250729-20","meetingId":"r07-cm07","date":"2025年7月29日","dateIso":"2025-07-29","committee":"ＳＤＧｓ推進・行財政改革特別委員会","time":"午後 １時００分～午後 ４時３６分","status":"正式会議録","sourceType":"formal","overview":"ＳＤＧｓ推進・行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を21件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"委員会も変わったということで申し訳ないのですが、改めて現在の方式です。ＢＴＯ方式を選択した理由を伺いたいというのと、それとサウンディング調査に参加した２８の事業者名なのですが、それぞれ教えていただきたいと思います。","respondent":"吉岡政策推進担当課長","answer":"２８社の個別のところはまだ公表する予定はないのですけれども、参加事業者数で載せさせていただいたところをもう少し細かくご説明しますと、２番の参加事業者数、資料に載せております設計、建設、こちらは当然ながら設計業者、建設業者になるのですけれども、運営、維持。","voiceIndex":6,"id":"exchange-001"},{"speaker":"安藤委員","kind":"質問・要望","question":"もう１つは、基本計画検討委員会の中の有識者の方から出ていたようですけれども、よりよい施設整備を目指すためにはこのＳＰＣというところのモニタリング体制をしっかりと構築してもらいたいという意見も出ていたと思うのですけれども、昨年度の行財政改革特別委員会の中ではそういったＰＦＩの手法の採用に対しての懸念の質問に対して区も指定管理のようにどうモニタリングしていくかと。","respondent":"吉岡政策推進担当課長","answer":"今、指定管理施設のほうでも年間でモニタリングをさせていただいて、議会にもご報告をさせていただいているところですけれども、そういったやり方については当然変わらないのですけれども、新たな業務を付加するというのは。","voiceIndex":8,"id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"調査に参加した事業者名なのですけれども、これってやはり区の施設です。冒険広場は参画が難しい。どこに可能性があるか伺いたいのと、どこをもって十分な可能性があることを把握したと言っているのかというのを伺いたいのと、あと、もう１つ、事業参画する上での課題をこれから把握していくとありますが、どういうところにこの課題があると現時点では品川区として考えているのかも伺いたいと思います。","respondent":"吉岡政策推進担当課長","answer":"今後の課題ですけれども、こういった事業をいろいろなコンセプトを含めて導入機能を出していくところではありますけれども、なかなかこういった事業者の声をこれから深掘りしていく中でやはり課題感というのをどれだけ担保すれば、機能が運営できる。","voiceIndex":10,"id":"exchange-003"},{"speaker":"安藤委員","kind":"質問・要望","question":"ビオトープのことについても書かれているのですが、このやめたほうがいいと事業者は答えているのですが、今、去年の質疑などを見てみますと、こういった掲げられている機能というのはなくすことは検討していませんと答えているのです。それで、これをなくしてほしいという要望が出てしまっているわけですけれども、それに対して区はどう答えるのですか。","respondent":"吉岡政策推進担当課長","answer":"ビオトープについてなのですけれども、こちらは令和５年度に実施をいたしましたワークショップ、あるいは跡地活用方針策定委員会の中でこういったものができたらいいねというところで、緑だとか、そういう生き物に囲まれた自然を身近に体験。","voiceIndex":12,"id":"exchange-004"},{"speaker":"安藤委員","kind":"質問・要望","question":"それと、ＰＦＩについてはやはり今の時点で聞いても、私は必ずしも区民要望と、方向が合致するのかというのはかなり疑問がありますので、公共施設管理計画に基づいてＰＦＩありきで進めるのはやめるべきであり、一応検証等はしたようではありますが、今回、資料の冒頭にＰＦＩ事業での実施を目指していると書いてありますけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":14,"id":"exchange-005"},{"speaker":"あくつ委員","kind":"質問・要望","question":"少し細かいことで今日の資料で教えていただきたいのですけれども、参加事業数が先ほどご説明あったとおり、様々な業種で２８社だったのですけれども、確認ですけれども、設計のところは３社というのは設計会社で、建設というのはいわゆる開発事業者、デベロッパーと言われるような方たちなのか。サウンディングですから、そういうのは当然あり得べきだと思うのです。はその辺りを教えてください。","respondent":"吉岡政策推進担当課長","answer":"これは無理だというような話のところは、特段ないのですけれども、やはり今、建設業者、建設業界というところで、非常に人手不足ですとか、いろいろな公共施設の工事以外に民間の工事の受注の機会があるので、少し時期の検討はしてほしい。","voiceIndex":18,"id":"exchange-006"},{"speaker":"あくつ委員","kind":"提案","question":"調査結果の導入機能のところからお伺いしていきたいのですけれども、詳細な理由を知りたいので、体育館、グラウンドのところで図書館とのイベントの共同実施は難しいという、そういうご意見があったりするのですけれども、ということはこちらからこういうのはどうでしょうかという、品川区役所、発注側からのそういう意向を示していただいたかと思うのですけれども。","respondent":"吉岡政策推進担当課長","answer":"一方でやはり体育館・図書館を一括で運営していないような施設を経験してきた民間事業者からは図書館、体育館、いわゆる静と動といいますか、なかなか考え方が思いつかないということで。","voiceIndex":20,"id":"exchange-007"},{"speaker":"あくつ委員","kind":"提案","question":"私も、私たち会派でやはりＳＰＣのところを視察してきましたけれども、先ほど安藤委員が示されていた懸念に関しては特に問題なく、モニタリングというか、どこも含めてＳＰＣたちがしっかり責任を持って運営をされていて、そこに関して何かこう、区が目の行き届かないところで何かとんでもないことが起きているというようなことはないと確認はしてきましたけれども。","respondent":"吉岡政策推進担当課長","answer":"一方で、今ご案内いただいたＳＰＣの中に地元のそういった事業者が入っていただいているところもあれば、一方でそういったところの条件をつけると厳しいといった両方がありますので、引き続き検討していきたいと考えています。","voiceIndex":22,"id":"exchange-008"},{"speaker":"あくつ委員","kind":"意見","question":"最後最後って申し訳ないのですけれども、今のお話をいろいろ聞いていると、本当に非常に今後、区役所側も事業の絞り込みとか確定とか、いろいろ難しいと、すごくご苦労だと思います。課長も本当、大変だと思うのですけれども、そういうところのコンサルというのは入れているのか入れていないのか、最後、そこだけ、お願いします。","respondent":"吉岡政策推進担当課長","answer":"このＰＦＩ事業についてはアドバイザリー業務という形で委託事業者を入れております。当然、経験豊富な事業者が入っておりますので、連携・相談しながら、事業内容を固めていきたいと考えています。","voiceIndex":24,"id":"exchange-009"},{"speaker":"まつざわ委員","kind":"質問","question":"参画が難しいという業者の話の中でも、でも、地域の話も入れたい、区があって、そういうときってもうそういうリスクの分散だとか、そういう枠、それでもやはりやってほしいというこの思い、願いというのをどうリスクを分散しながら区として提言していくのかというのが聞きたいのです。","respondent":"吉岡政策推進担当課長","answer":"ただ一方で、考えないといけないのは維持管理が大変だという話をいただきましたけれども、そういった部分の投資した費用に対してどう考えていくかということも非常に重要な部分ですので、まずはこの機能という形は令和５年度からワークショップによりますと。","voiceIndex":27,"id":"exchange-010"},{"speaker":"まつざわ委員","kind":"質問","question":"だからこそ、地域にどう落としていくのかとか、特にここの地域は防災、防災という部分がすごい強い中で壊した後に防災の拠点がなくなってしまうから、では、どうする、私たちはどこにいて、もうそれこそ課長もよく知っていますけれども、そういう課題がすごく残っている中でやはり意見の交換会、しっかりやっていかないといけない施設だと、それこそプレッシャーをかけるようで申し訳ないですけれども。","respondent":"吉岡政策推進担当課長","answer":"そういった中で、そのステージステージでしっかり地域の方にもお話をさせていただいたというのもありますので、こういった進捗を含めて引き続き地域の方には説明をしていきたいと考えています。","voiceIndex":29,"id":"exchange-011"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"最後に要望ですけれども、今日行ってつくづく思ったのが、やはり旧荏原第四中学校の跡地でぱっと見たときに校章があったのです。今度、複合施設になる。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":31,"id":"exchange-012"},{"speaker":"新妻委員","kind":"質問・要望","question":"説明、ありがとうございました。行政視察もありがとうございました。主な意見ということで。ここに出されていない部分がもっとあると思うのですが、そこの部分というのは今後、ここは公表されていくのか、それともいろいろな意見があるので、全部が出すことがいいことではないとも思いますので、例えば、ここに載っていない部分で品川区が参考にしていくというようなところがあるのでしょうか。","respondent":"吉岡政策推進担当課長","answer":"このサウンディング調査につきましては、６月１０日から７月１０日で、一気にやったということではなくて、パラパラご意見いただいたです。","voiceIndex":33,"id":"exchange-013"},{"speaker":"新妻委員","kind":"質問・要望","question":"ただ、だけれども、やはり声としてはカフェのあるということでは、人が集まれるというところもありますし、何か飲食ができるというのは大きな魅力だと、そういう声がやはりあるわけなのですけれども、こういうサウンディング調査の結果があることで、区は、では、やはりここはやめておこうと寄っていってしまうのではというのが心配するところなのですが、そこら辺は。","respondent":"吉岡政策推進担当課長","answer":"ただ、これをＰＦＩ事業にすることで、いわゆる事業の中での費用として採算が取れるようにという位置づけにしてもらうのは事業者としてはなかなか厳しいというご意見です。そういったあくまでＰＦＩ事業に関しては課題があるということでご意見いただいたです。","voiceIndex":35,"id":"exchange-014"},{"speaker":"新妻委員","kind":"質問・要望","question":"一応、ここの導入機能として当初品川区が示している中の部分というのを基本的にはやってほしいという、そういう思いがあります。その調査の中で少し難しいと思っている部分でも区がやるという方向性を示すのであれば、そこは何かしらの手法でやはりやっていただきたいという要望をさせていただいて終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":37,"id":"exchange-015"},{"speaker":"山本委員","kind":"質問","question":"私からも何点か質問します。設計３社、建設７社、それから運営維持管理が１８社ということのサウンディング事業者数というのは区として、社数としても十分聞いているお考えなのかご見解を教えてください。","respondent":"吉岡政策推進担当課長","answer":"今回、事業者数の捉え方ですけれども、昨年度、１０社に、本当に安易なサウンディングではありますが、行いました。今回、３０前後の事業者からこういったお話を聞けたというところで、今後も見識も深めていけるので事業者数としては十分増えたと考えているところです。","voiceIndex":39,"id":"exchange-016"},{"speaker":"山本委員","kind":"質問・要望","question":"デベロッパーが何社かと私がお聞きした趣旨としては、ご答弁にもありましたとおり、複合事業なものですから、それを束ねる事業者の役割はすごく大きいと思っていまして、その代表格がデベロッパーと思っていたので、そういったところからしっかりと話を聞くことが大事かとお聞きしたのですけれども、デベロッパーはいないものの。","respondent":"吉岡政策推進担当課長","answer":"これを受けたからこそ、事業として全てこの整理していくというわけではございませんで、引き続きサウンディング調査を深めながら、また、これから実施方針、要求水準書というのを固めていきながら、一方で先ほど申し上げたように事業費とのバランス、これが整備費。","voiceIndex":41,"id":"exchange-017"},{"speaker":"山本委員","kind":"質問・要望","question":"個別の中身のところでお伺いしたいのが、体育館、グラウンドのところで書かれている体育施設として収益事業の実施の有無によりＳＰＣの事業者構成も変わってくるというコメントが気になりまして、私の理解ですと、体育館・グラウンドというと、区民の方や事業者の方が時間を区切って低額で借りると思っていて、その利用料も割とＰＦＩと言いながら、区民の方が利用できる。","respondent":"吉岡政策推進担当課長","answer":"今、区では体育館、それから貸出し施設として行っております。そういったところでの利用料、支払ってもらうというのはここでの収益事業に当たらないと考えています。","voiceIndex":43,"id":"exchange-018"},{"speaker":"山本委員","kind":"確認","question":"要は、それだけ今は建設コストが上がっているので、事業者が出してくるのをそのまま言うと、例えば、スポーツ施設を利用するのも結構高額になってしまうし、何が何も高くなってしまうというのを危惧しているのですけれども、当然、区の予算は単年ですから、そう簡単にはそういう話にはならないと思うのですけれども、方向感としてどうかというのをお伺いしたいのと、続けて聞いてしまいますけれども。","respondent":"吉岡政策推進担当課長","answer":"一方で、先ほどの建設費のスライドの話ですとか、指定管理が始まった、事業が始まったときにどうやって費用を払っていくかというのはあるのですけれども、基本的にはそのＰＦＩ事業というところで。","voiceIndex":45,"id":"exchange-019"},{"speaker":"山本委員","kind":"質問・要望","question":"先ほどの話とも繰り返しになるところもあるのですが、丁寧に進めていただきながら、サウンディングを繰り返しながら、精度を高めていって課題をより認識しつつ、クリアして進めていただいているということで理解をいたしましたので、その期間や進めていく中での課題感をこうやって聞いていくことですごく分かってくるというのもあると思いますので、それに合わせて計画も修正しながら。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":47,"id":"exchange-020"},{"speaker":"あくつ委員","kind":"提案","question":"なぜかと言うと、私どもの会派も幾つか見て、空間利用については非常にデザインが大事というところ、ご提案もさせていただいていたものですから、そこだけある程度教えていただけるところがあれば、教えてください。","respondent":"吉岡政策推進担当課長","answer":"意匠、デザインについてですけれども、特にこういったのはないのですけれども、やはり事業者自体、非常に参画意欲を示すというわけではないのですけれども、我々の企業はこういったところを手がけてきた、こういうコンセプトを手がけてきたというような説明だとか。","voiceIndex":51,"id":"exchange-021"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7129#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=20&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":23521,"voices":57}},{"id":"r07-20250730-22","meetingId":"r07-cm07","date":"2025年7月30日","dateIso":"2025-07-30","committee":"まちづくり・公共交通推進特別委員会","time":"午後 １時００分～午後 ５時０２分","status":"正式会議録","sourceType":"formal","overview":"まちづくり・公共交通推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","hasFullText":true,"topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7131#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=22&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":850,"voices":5}},{"id":"r07-20250731-10","meetingId":"r07-cm07","date":"2025年7月31日","dateIso":"2025-07-31","committee":"議会運営委員会","time":"午後 １時００分～午後 １時３１分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を9件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"令和７年第３回定例会","agenda":"令和７年第３回定例会","exchanges":[{"speaker":"安藤委員","kind":"提案","question":"決算特別委員会の審査日程（案）ということですので、少し意見を述べさせていただきたいのですが、改めて、今回難しくても、決算、予算とこれから続いていくわけですから、予算特別委員会などでの検討を含めて、ご検討いただければと思っているのですが、改めて提案したいのは、国保と後期高齢者医療と介護のこの３つの特別会計なのですが、民生費と一緒になっているのですけれど、これをやはり。","respondent":"まつざわ委員長","answer":"審査日程をさらに増やすことは、年間のスケジュールの調整を踏まえて、直ちには難しいというお話をさせていただきまして、それで安藤委員のほうから、検討をお願いしますということで、昨年度私も、議会改革のほうで進めて。","voiceIndex":6,"id":"exchange-001"}]},{"id":"topic-02","title":"品川区給付型大学奨学金運営委員の推薦","agenda":"品川区給付型大学奨学金運営委員の推薦","exchanges":[{"speaker":"あくつ委員","kind":"質問","question":"それで結構なのですけれど、その前提として、新しく立ち上がるこの奨学金運営委員会の構成というのはどうなっているのか。何名で、どういう構成なのかというのを教えていただければと思います。","respondent":"大澤区議会事務局長","answer":"今回依頼を受けているのは資料ナンバー３にあるものだけで、それ以外の情報は今、持ち合わせておりません。すみません、記憶が少しあれなのですけれど、総務委員会でもしかすると内容的な説明があったかに思いますが、すみません、分からないです。申し訳ございません。","voiceIndex":14,"id":"exchange-002"},{"speaker":"あくつ委員","kind":"質問","question":"これしか来ていないということですけれども、議会から２名ということでの推薦依頼ということで、要するにその２名というのはどれぐらいの配分の重さなのかというところを受けての同意だと思うので、今後もしこういう依頼があった場合には、その内容についてはもう少し詳しく教えていただけるように、申し訳ないですけれど、議長なのか委員長なのか、あとは事務局からも少し問合せをした上で。","respondent":"大澤区議会事務局長","answer":"今分かる範囲で、委員が１０人以内ということになっていて、選出区分は議員、学識経験者、区職員というふうになっているようです。","voiceIndex":16,"id":"exchange-003"}]},{"id":"topic-03","title":"令和８年度予算（議会費）","agenda":"令和８年度予算（議会費）","exchanges":[{"speaker":"石田（秀）委員","kind":"質問・要望","question":"これは区議会事務局、いつもこれ、何度もいろいろなお話をさせていただいているけれども、品川区は部長級の局長がいらっしゃって、課長級の方がいらっしゃらないというようなこともありますが、事務局機能を、我々議会のほうもしっかりそういう対応をしていかなくてはならないと思いますが、しっかり次長というか、課長級の方を増やしていただいて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":21,"id":"exchange-004"},{"speaker":"松永委員","kind":"提案","question":"初めに、若者など幅広い層の皆様に区議会のことを知ってもらって、関心を持ってもらうために、区議会の報告等の動画をＹｏｕＴｕｂｅ等で作成して展開してはどうかということでご提案しています。そのほかにも、区議会だよりの内容を動画で１分か２分程度で作って、各会派の紹介、議員の紹介の動画を作成してホームページから閲覧できるようにということで、ご要望しています。以上の５点になります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":22,"id":"exchange-005"},{"speaker":"あくつ委員","kind":"質問・要望","question":"１点目です。２点目は、これも昨年も要望しましたが、これも全く未来と一緒で、いわゆる年４回の区議会の定例会の開催通知チラシ、ポスターついて、区民への効果的な周知のために、掲示場所を公共施設のみから、ふれあい掲示板、町会掲示板に拡大する費用を計上すること。ただこれ、結構準備も負担もかかるので、例えば年に１回ぐらい、そういったところでの会議でやっていただきたい、こういう要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":23,"id":"exchange-006"},{"speaker":"安藤委員","kind":"質問・要望","question":"１番目は、これは議事録の作成をやはり早めるということで、毎回言っているのですけれども、第２回定例会とか第４回定例会とか、最終本会議と、委員会審査の近いところですと、実際に討論を行うときの議事録ができていないというような状況がありますので、これは実態からいっても早める必要があるということで、議事録を早めてほしいということです。それはお金をかけてほしいということにもなります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":24,"id":"exchange-007"},{"speaker":"せお委員","kind":"質問・要望","question":"先ほど行われました広報会議で、来年度区議会だよりの内容の見直しを行っていて、特集記事の制作などを進めていこうという方針、予定ということになりました。これに伴って、区議会だよりリニューアルにおける特集記事等に係る経費を要望したいと思います。どうぞよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":26,"id":"exchange-008"}]},{"id":"topic-04","title":"その他","agenda":"その他","exchanges":[{"speaker":"田中委員","kind":"質問・要望","question":"議長のご報告で、２番目のふるさと納税に関連してなのですが、ぜひオール東京、また、オール２３区で対応していただきたいと思いますが、せっかく吉住区長とも連携取ってということの中で、地方税の偏在を是正するために、特別区も、東京独り勝ち論を変えるというか、方向性をそらすためという要素があったと思うのですけれど、２３区で特別区全国連携プロジェクトをやっていて、それは。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":32,"id":"exchange-009"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7133#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":10939,"voices":39}},{"id":"r07-20250807-8","meetingId":"r07-cm08","date":"2025年8月7日","dateIso":"2025-08-07","committee":"建設委員会","time":"午前１０時００分～午後 ４時１７分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","hasFullText":true,"topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7135#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":1323,"voices":7}},{"id":"r07-20250825-6","meetingId":"r07-cm08","date":"2025年8月25日","dateIso":"2025-08-25","committee":"区民委員会","time":"午後 １時００分～午後 ２時４１分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を31件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"特別区区民葬儀における助成制度の創設","agenda":"特別区区民葬儀における助成制度の創設","exchanges":[{"speaker":"おぎの委員","kind":"質問","question":"交付率なのですけれども、令和６年度が６.８％で交付率が低いと感じるのですが、こちらに関して以前、おくやみハンドブックをお渡しするタイミングで、こういった制度もお知らせしてチケットもお渡しできるということだったのですけれども、おくやみハンドブックを渡すのが死亡届の提出時で、死亡届提出時に家族が提出してくれば、家族の方にお渡しできるのですけれども、業者が代行で出してくると。","respondent":"築山戸籍住民課長","answer":"２点目の業者の内訳になるかと思いますが、死亡届を出される際に、どの業者を使うかという把握はしておりませんので、それぞれのご利用者が事業者を選んでいるというところで、その実態については分かりませんが、ただ、区民葬儀の交付の現状というところでは。","voiceIndex":5,"id":"exchange-001"},{"speaker":"おぎの委員","kind":"質問","question":"そうしますと、死亡届をどの方が出してきたというのは、特に分からないといったことなのでしょうか。","respondent":"築山戸籍住民課長","answer":"死亡届を出される方がどのような方かというご質問につきましては、現状は葬儀会社の方が出すことが多い状況です。","voiceIndex":7,"id":"exchange-002"},{"speaker":"おぎの委員","kind":"質問・要望","question":"そうしますと、１０事業者以外の方に最初からお願いしてしまっていると、後で変更が利かないので、区民葬儀が使えなくなってしまう方が出てくるのかなと思いますので、この辺りの順番をもう少し交通整理したほうがいいのかなとは思っています。","respondent":"築山戸籍住民課長","answer":"当面の間という件についてなのですけれども、今回の件はあくまで当面の措置ということで、特別区といたしましては、今後、利用状況等を踏まえまして、助成事業の在り方を検討していく必要があると認識をしています。","voiceIndex":9,"id":"exchange-003"},{"speaker":"こしば委員","kind":"質問・要望","question":"８月１日に東京博善から、区民葬の離脱の発表が公式に出されまして、いろいろとニュース等でも報じられているわけですけれども、これまで行ってきた区民葬が、これは東京博善が公式に発表しているものを見させてもらったのですが、そもそも論、戦後の低所得者の支援を目的に始まった制度であるにもかかわらず、最近では審査なしで葬祭券が配付をされて、低所得者支援以外でも利用されてしまっているという。","respondent":"築山戸籍住民課長","answer":"区民葬儀の経緯ですけれども、区民葬儀はもともと昭和２３年に都民葬儀として運営が開始されまして、昭和４０年に当時の東京都民生局から特別区に事務移管されたものです。","voiceIndex":12,"id":"exchange-004"},{"speaker":"こしば委員","kind":"質問・要望","question":"今、課長からお答えいただいた内容というのは、まさにそのとおりだと思います。家族が亡くなって苦しいときに、例えば所得制限を証明する証明書の提出だとか、おつらいときにそれを求めるというのは、本来の在り方としてはおかしいと思います。一方で、区民葬の利用状況が全体の数に比べて少なく見えたのです。","respondent":"築山戸籍住民課長","answer":"区民葬儀の案内についてです。周知の問題は非常に難しいと考えておりまして、まだご存命の方に対して葬儀についてのご案内をするというのは、非常に慎重に行わなければいけないというところで、積極的な働きかけが難しいものだと認識しております。","voiceIndex":14,"id":"exchange-005"},{"speaker":"こしば委員","kind":"質問","question":"とすると、今後を含めて、広報・周知によっては利用率も変わってくるという見立てでよろしいでしょうか。","respondent":"築山戸籍住民課長","answer":"おっしゃるとおり、今回、補助制度も創設いたしますので、そういったことも含めて周知をしてまいりますので、利用状況は影響が出るだろうと考えております。","voiceIndex":16,"id":"exchange-006"},{"speaker":"こしば委員","kind":"質問・要望","question":"今後、これは令和８年度、来年度の予算の中で編成をする中で、一つの形となって表れてくる助成の中身はまだ分かりませんけれども、そういうときに恐らく、決まった金額が補助されるとして、その一方で、全額補助などというのはなかなか難しいと思うのですけれども、そもそもの火葬代が、今、一時的に３,０００円ほど東京博善が値下げはしていますが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":18,"id":"exchange-007"},{"speaker":"こんの委員","kind":"質問・要望","question":"今、お二人の質疑をお聞きしながら、少しかぶるところもあるかもしれないのですけれども、まず、現状を確認させていただきたいのですが、区民葬儀の現状として、交付率です。亡くなった方が３,５８２名いる中で、６.８％が葬祭券を使われているといったところの、まずこの６.８％をどのように区としては捉えていらっしゃいますでしょうか。","respondent":"築山戸籍住民課長","answer":"今後、変化があると思いますので、そういった中で、先ほど助成制度につきましては当面の間ということで、今後利用状況を踏まえて検討していくとありますけれども、こういった葬儀の状況を踏まえまして、今後の制度について検討していきたいと考えております。","voiceIndex":20,"id":"exchange-008"},{"speaker":"こんの委員","kind":"質問・要望","question":"３つの理由ということでお聞きいたしました。協力事業者が１０事業者で、品川区内には葬儀会社がもっとたくさんいらっしゃる、そこが協力店にはなっていないといったところも気になるところなので、協力をされていないというか、何か要因があって１０事業者だけになっているのか。その辺りはどうなっているのでしょうかというところをお聞かせください。","respondent":"築山戸籍住民課長","answer":"ただ一方、区民葬儀も、低廉な形で簡素な葬儀をするという形になっているのですけれども、その中には通夜の実施も含まれておりますので、人によっては、一日葬だけでいいですよという人がいれば、区民葬儀よりももっと安い価格での提案はできるかもしれないですし。","voiceIndex":22,"id":"exchange-009"},{"speaker":"こんの委員","kind":"質問・要望","question":"そうしたときに、一つの葬儀を皆さんの思いでされる、お金を幾らでもかけられる人は別ですけれども、そうではない、お金をかけなくても心ある葬儀をといった方が大半だと思いますので、そうした区民葬儀の在り方、それから、こういう助成制度のつくり方といったところは、２３区共通で、当面の間ということになっておりますが、当面の間の中で、どれだけそれの検討が進められていくのか。","respondent":"築山戸籍住民課長","answer":"こちらの火葬自体は広域的なものですので、一つの区だけでというよりは、２３区で一緒に検討していったほうが好ましいかなと考えております。","voiceIndex":24,"id":"exchange-010"},{"speaker":"こんの委員","kind":"質問・要望","question":"そうなると、やはり葬儀が必要といったところだと思うので、区としても葬儀の在り方というのは、今後きちんと区民の死をどのように迎え、どういう形で弔っていくのかといったところを、これを機に区としても方針を定めていただきながら、ご検討に当たっては２３区ということですけれども、それは共通のものとして、だけれども。","respondent":"築山戸籍住民課長","answer":"委員おっしゃるとおり、区としても、どうあるべきかということは考えて取り組んでまいりたいと思います。","voiceIndex":26,"id":"exchange-011"}]},{"id":"topic-02","title":"住民票の写しへの同性パートナーの続柄の記載開始","agenda":"住民票の写しへの同性パートナーの続柄の記載開始","exchanges":[{"speaker":"こんの委員","kind":"確認","question":"そこで確認なのですけれども、事実婚の場合と同様に、同性パートナーの方の続柄がそうなるということですが、この対象者、「以下の全ての条件を満たすものとする」という条件は、例えば事実婚の方も同じような、こうした全ての条件を満たして、続柄がそうなっていたのでしょうか。基本的なところですが、確認をさせてください。この２点をまず確認させてください。","respondent":"築山戸籍住民課長","answer":"周知についてですが、事前にお伝えするというのは、発行する証明書の写しの記載内容がこれから変わってくるですので、既に同性パートナーシップ宣誓制度を活用されている方が、これから住民票の写しを発行するに当たって、「（未届）」の住民票が欲しいと希望される場合に。","voiceIndex":32,"id":"exchange-012"},{"speaker":"こんの委員","kind":"確認","question":"それはそれ、これはこれという理解でよろしいでしょうかという確認です。もう一つは、コンビニ交付はできませんというところが、私も理解ができていなくてすみません、システム上、続柄が「同居人」から「夫ないし妻（未届）」に変更できないので、その変更は窓口しかできませんという理解でよかったですか。なぜコンビニ交付ができないのかというところも確認させてください。","respondent":"築山戸籍住民課長","answer":"その関係で、システムを勝手に仕様変更して操作することはできなくて、システム上は「同居人」のままになっております。ただ、これを住民票の写しとして交付する際には、品川区が独自に写しの続柄の部分を「（未届）」に変えて、紙でお渡しするという形になっております。","voiceIndex":34,"id":"exchange-013"},{"speaker":"こんの委員","kind":"確認","question":"同性パートナーたちが今後のご自分たちの立ち位置というか、そういったところが住民票上でもそのように認められるといったことは、すごく大きなことにつながると思うと、取得するときの手間といったところも、できるだけ簡素にしていただける形がいいのかなと思いましたが、一定の確認は必要なのだということが確認できましたので、運用してみて。","respondent":"築山戸籍住民課長","answer":"あくまで品川区としてできることから進めていくというところでございまして、今回、この運用に踏み切ったところです。課題等も今後出てくるかとは思いますので、いろいろ検証しながら考えてまいりたいと思います。","voiceIndex":36,"id":"exchange-014"},{"speaker":"こんの委員","kind":"確認","question":"それとともに、長崎県の大村市でもこういう一件があって、でも国からは、取扱いとしては標準にしてくださいという見解が出された中で、１０区で申入れをして、今回これに区が踏み切ったといったところは、１０区の申入れを国としても認めたというところで品川区としては踏み切れたのか、それとも、この間何があって踏み切ったのかというところを、ごめんなさい、最初にこれを確認したかったので。","respondent":"築山戸籍住民課長","answer":"先ほど委員がおっしゃられたとおり、品川区は令和６年１２月に、同性パートナーの方が事実婚の方と同様の権利が得られるよう、各種社会保障制度等の改正についての検討と、パートナーシップ制度の適用を受けた方の住民票の続柄表記について。","voiceIndex":38,"id":"exchange-015"},{"speaker":"おぎの委員","kind":"質問","question":"今回、品川区でできることということで、条例の理念に基づいて始めますということですが、これは同様に品川区以外でもされている区が、またはほかの自治体があるのでしょうかというのが１点と、コンビニで出せないのは国の全体の標準化のシステムだから、そこは区だけのものは対応できないということですが、区内でこの表示をする場合は、経費はどれくらい、今回システム変更でかかられたのかというのを。","respondent":"築山戸籍住民課長","answer":"品川区以外の自治体の状況ですが、全国で、現時点で１２自治体が同様の取組をしていると聞いております。２３区ではそのうち世田谷区と中野区が導入しております。２点目です。今回の運用に当たっての経費ですが、これは職員が行うものですので、経費はかかっておりません。","voiceIndex":41,"id":"exchange-016"},{"speaker":"おぎの委員","kind":"質問","question":"職員が窓口で、条件が合う方に印字して出すということで合っていますでしょうか。","respondent":"築山戸籍住民課長","answer":"そのとおりです。","voiceIndex":43,"id":"exchange-017"},{"speaker":"こしば委員","kind":"質問・要望","question":"実際、住民票の「夫（未届）」または「妻（未届）」といったものも、記載された住民票の写しというのがどの程度のメリットが出てくるのかというのが分からなくて、例えば生命保険の受け取りだとか、住宅を購入したときに、夫婦であれば一定のサービスを受けられるとか、一緒に生活をすると特典があるような、まさにそれぞれたくさんあると思いますけれども。","respondent":"築山戸籍住民課長","answer":"今回の証明書ですが、先ほどご説明したとおり、事実婚としての法的効果が生じるものではございません。","voiceIndex":46,"id":"exchange-018"},{"speaker":"こしば委員","kind":"意見","question":"提出先の判断に最終的に委ねられるとか、そういう意味では懸念することがどれほどあるか分かりませんけれども、逆に住民票を申請するときに、窓口とかオンラインとかでも申請できるのですし、ある程度そういった当事者の方には、事前に説明できるような環境というのはつくっておいたほうが、その後のトラブルだとか、そういったものが未然に防ぐことができると思いますので、その辺りはお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":48,"id":"exchange-019"}]},{"id":"topic-03","title":"ウーマンズビジネスグランプリｉｎ品川２０２６キックオフサミットの開催","agenda":"ウーマンズビジネスグランプリｉｎ品川２０２６キックオフサミットの開催","exchanges":[{"speaker":"おぎの委員","kind":"意見","question":"今回のこういった事業、（２）番の目的のところにもあります社会課題解決のために、女性起業家でという女性ならではの視点で、社会課題が解決につながったらいいなとは思っております。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"継続的な支援ですけれども、ファイナリストは全部で８名を予定しているのですが、この方たちについては、終わった後、武蔵小山創業支援センターのインキュベーションマネージャーがおおむね３回程度、相談に応じるといった支援を行っています。","voiceIndex":53,"id":"exchange-020"},{"speaker":"おぎの委員","kind":"質問・要望","question":"ですので、条件が整えば２人、３人ともうけてもいいなというご家庭とか女性もいらっしゃると思いますので、専業主婦でもいいのだという、専業主婦が輝くという視点からも、何か発信を同時にしていただきたいと思うのですが、そういったことについてはどうでしょうか。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"今私たちがやっている施策とすると、その中での創業という一つの選択肢ではありますけれども、このコンテストではなくて、日頃行っている支援の中では、キャリアプランを見直そうということで、人生の自分の年表の中からどんなライフステージがあって。","voiceIndex":55,"id":"exchange-021"},{"speaker":"おぎの委員","kind":"質問・要望","question":"品川区、誰もが自分らしくということですので、女性の方も一生懸命勉強されて、自己実現のために社会で活躍して働くという、それもすごく輝ける方で、頑張っていただきたいと思うのですけれども、一方で、本当は子育てしたいのだけれども、仕方なく働いている方とかもいらっしゃるのでしたら。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":57,"id":"exchange-022"},{"speaker":"こんの委員","kind":"確認","question":"２つお聞きします。１点目は、今回のキックオフサミットは初めて開催するものでしょうかというところの確認が一つと、協力自治体ですが、ここに記載の５つの市を今回参加自治体としていますが、協力自治体への呼びかけはどのようにされているのでしょうか。この２点をお願いします。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"２点目の協力自治体につきましては、これまで武蔵小山創業支援センターに視察に来ていただいたり、それから都市間交流ということで、起業支援を行っている中で職員同士のコネクションがあったり。","voiceIndex":59,"id":"exchange-023"},{"speaker":"こんの委員","kind":"意見","question":"品川区としてこれまでウーマンズビジネスグランプリをされてきたので、こういう取組を品川区はしていますというアピールにもなりますし、また、ほかの自治体ではどういったことをしているのかという交流というのにもなるので、非常にいい企画だなと思います。先ほど少しお話がありましたが、女性の生き方は様々だと思います。ですので、第１回目が大成功で終わることを祈っております。頑張ってください。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":61,"id":"exchange-024"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"それで、質問は１点なのですけれども、後援の企業なのですが、今まではさわやか信用金庫が随分前から後援されておりました。今回、さわやか信用金庫が後援になっていない代わりに、日本政策金融公庫が、代わりといいますか、入れ替わって金融公庫になったという認識でよろしいですか。さわやか信用金庫が撤退をしたとか、そういうことではないのですか。その経緯等々を教えてください。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"さわやか信用金庫につきましては、ビジネスグランプリそのものにさわやか信用金庫賞ということでご協力いただいているのですけれども、まだキックオフということで、あえてそういった後援の企業に、今回は初めてということで。","voiceIndex":63,"id":"exchange-025"},{"speaker":"高橋（伸）委員","kind":"質問","question":"そうすると、先ほど課長からご説明あったように、キックオフサミットのチラシがあるではないですか。第１５回のウーマンズビジネスグランプリもキックオフの中に当然入っているものだと私は理解していたのだけれども、ウーマンズビジネスグランプリは来年の２月ですよね。そのチラシも今後作って、後援はさわやか信用金庫が入るとか、そういう考え方でよろしいのですか。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"今のご質問のとおりでございまして、ウーマンズビジネスグランプリのチラシは別途作成しまして、そこに掲載することになっております。","voiceIndex":65,"id":"exchange-026"},{"speaker":"高橋（伸）委員","kind":"質問","question":"分かりました。なぜ私がそういう質問をしたかというと、さわやか信用金庫は本当に地域密着で、個店なり個人でもすごくまめに動いてくれていたから、それで女性起業家にも一緒にリンクできたらという、さわやか信用金庫もそういう考えがあったと思うので、その辺りはどうなったのかなと思ってお尋ねしました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":67,"id":"exchange-027"},{"speaker":"せらく委員","kind":"質問・要望","question":"これまでのお話を聞いていても、女性が輝けるような選択肢の一つとして、すごくいい企画だなと思っていて、応援したいと思っています。今回、キックオフサミットということで、ビジネスグランプリと併せて開催するということですが、キックオフサミットを開催することで、例えば次のエントリー数が増えるとか、そういったところの数値的な目標、それに限らず何かあれば教えていただきたいと思います。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"今回このキックオフサミットを実施する副次的な効果といったところです。現在、申込みについては、例年大体８０から９０ぐらいの応募があるところです。","voiceIndex":69,"id":"exchange-028"}]},{"id":"topic-04","title":"その他","agenda":"その他","exchanges":[{"speaker":"こんの委員","kind":"質問","question":"要するに、学校で林間学校として使えなくなってしまったといったこともさることながら、保養所として、そもそも運営事業者が、トコジラミという今回の事案ですけれども、運営としてはどうだったのでしょうかという率直な区民の方の声がありますので、その辺りは、今回のトコジラミという案件ですが、そもそもの運営自体、運営事業者の設備管理、維持管理といったところは日常どうだったのでしょうかという。","respondent":"平原地域活動課長","answer":"ただ、それまでに至る対応等が果たしてどうだったかというのは、まだ調査中ですので、今後そういったところを区でしっかりと詳細を確認しながら、今後どういう対応を求めるかなどについて、しっかりと内容を詰めてまいりたいと考えているところです。","voiceIndex":81,"id":"exchange-029"},{"speaker":"こんの委員","kind":"質問・要望","question":"運営としては大丈夫だったと。そうしたところから見ると、運営事業者の対応はどうだったのかというところが、どうしても区民の皆さんは、大丈夫なのですかという声が多く入ってきたので、今のような質問をさせていただいたわけなのですけれども、３回の駆除をされたということで、３回しても、まだ再開できるまでになっていないということで、かなり状況は厳しいというか、そういう感じなのですか。","respondent":"平原地域活動課長","answer":"そういった中で、委員ご指摘のとおり、トコジラミについては昨今いろいろな関係で、これもはっきりと原因の特定は難しいと思いますけれども、巷間、ネット上などではいろいろな理由に結びつけて、そういう話が進んでいるというか、出ているということは。","voiceIndex":83,"id":"exchange-030"},{"speaker":"こんの委員","kind":"質問・要望","question":"要望で終わります。お願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":85,"id":"exchange-031"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7141#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":29849,"voices":88}},{"id":"r07-20250825-7","meetingId":"r07-cm08","date":"2025年8月25日","dateIso":"2025-08-25","committee":"厚生委員会","time":"午後 １時００分～午後 ２時４４分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を24件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"令和７年度高齢者福祉行事","agenda":"令和７年度高齢者福祉行事","exchanges":[{"speaker":"鈴木委員","kind":"質問","question":"社会福祉協議会で出されるお祝いが１００歳の方のみということになったわけですけれど、社会福祉協議会というのは、品川区もすごい密接な連携で、区の職員の派遣もしながら、品川区と本当に一体で進めるというのが社会福祉協議会のそういう状況になっていると思うのですが、社会福祉協議会がなくす、こういうお祝い事業を今までは１０１歳、それから白寿、卒寿、米寿に対しても全て。","respondent":"東野福祉計画課長","answer":"社会福祉協議会といたしましては、経営の状況、それから、他区での実施状況を踏まえて、他区ではやはり、１００歳以上というところ、１００歳の方にのみというところが多いという実態を踏まえて、見直しを行ったということで、令和７年度。","voiceIndex":5,"id":"exchange-001"},{"speaker":"鈴木委員","kind":"質問","question":"そういう中で、社会福祉協議会がなくしたというのは、一部のそういう意見だったりとか区民からのそういうふうなことも影響したのか、また、そういう、なぜ今、ずっと長い間やってきたところが今回こういう形になったのか、そこら辺のところは、かなりこの委員会の中でも、本当に長寿をお祝いする、そういう、みんなで長寿を喜び合うような。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":7,"id":"exchange-002"},{"speaker":"鈴木委員","kind":"意見","question":"分かりました。それからまた、本当に、長寿をお祝いするという、高齢者をみんなで長寿をお祝いするという社会として、ぜひあるべきだなと思っています。取りあえず以上です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":10,"id":"exchange-003"},{"speaker":"吉田委員","kind":"質問","question":"やはり楽しみにしておられた方も居るのではないかなと思います。なので、やはりこういうことは、やめるときはすごく丁寧な説明が必要かなと思うのですけれども、やめられる前、来年だな、などというふうに思っていた方とかご家族がいらっしゃると思うのですが、その辺は説明とかいうことはどのようにされるのか伺いたいと思います。","respondent":"東野福祉計画課長","answer":"先日の民生委員会長協議会がございました。その中で、今年度、こちらの長寿お祝い事業を社会福祉協議会は１００歳のみにしますというような説明がありましたので、民生委員などを通じて地域のほうにはお知らせをしていくというような考えであろうかと思います。","voiceIndex":12,"id":"exchange-004"},{"speaker":"吉田委員","kind":"質問・要望","question":"失礼な言い方に当たるかもしれないですけれど、思いのほか、節目を迎えるということでお祝い、ですから、金額とか物とかいうより、そのお祝いを、祝意を表してもらえるということに多分、喜びを見いだしておられるのかなと思うのですが、ということであれば、事業としては社会福祉協議会の事業だとしても、やはり社会福祉協議会のほうに区としても、より丁寧な説明というか、ご本人に納得がいくような。","respondent":"東野福祉計画課長","answer":"繰り返しになりますが、あくまでも社会福祉協議会としての責任の下、説明をする場合につきましては社会福祉協議会が行うものだと考えています。特に、区のほうには何も求められたものはございません。","voiceIndex":14,"id":"exchange-005"}]},{"id":"topic-02","title":"品川区障害福祉計画・障害児福祉計画策定のための基礎調査","agenda":"品川区障害福祉計画・障害児福祉計画策定のための基礎調査","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"調査概要の（２）のところの調査・分析方法のところで、障害者団体ヒアリングと書かれていて、これ、ヒアリングを実施して、計画策定や調査項目等に係る意見や要望を聴取するとなっているのですけれども、裏のスケジュールを見ると、団体ヒアリングというのが、そのアンケート調査が終わった１１月下旬から１２月中旬ということになっているのですが。","respondent":"佐藤障害者施策推進課長","answer":"障害児者へのアンケートにつきましては、先ほどおっしゃっていただいたようなところで大田区のほうで４９％というところ、また、世田谷区、目黒区等の同様の調査を見ましても、５０％程度というところではございまして。","voiceIndex":21,"id":"exchange-006"},{"speaker":"鈴木委員","kind":"質問・要望","question":"サービス使われている方とかは、計画も組まれているわけですから、その計画、相談事業所の担当者の方から、きちんと出していただきたいということでリマインドをするだったりとか、事業所は事業所で、委託業者のほうから、また、そういう形でリマインドしていただくだったりとか、そういう形で、ぜひともこれは少なくとも５０％超えるという目標は掲げていただいて、少なくとも他区並み、また。","respondent":"佐藤障害者施策推進課長、松山障害者支援課長","answer":"それから最後、医療的ケアの部分の対応ですけれども、それについては障害者支援課のほうから回答いたします。現在、調査集計中ですので、次回の支援関係機関連絡会につきましては、結果を連絡会のほうに報告をする予定になっております。ただし、集計中ですので、まだ数字としてはつかんでいるものではございません。","voiceIndex":23,"id":"exchange-007"},{"speaker":"鈴木委員","kind":"確認","question":"その発送した人たちに、今回の調査も全件調査の中に入れていただくということで捉えていいのか、その点を伺いたいのと、その発送した人数というのが、いつも医療的ケア児者の人数が分からないと、でもそれは、いろいろと保健センターだったりとか、サービス使われているところだったりとか、そういうところも含めて把握をされて、この人数というのが一定出てきたということで考えていいのか、その点。","respondent":"松山障害者支援課長","answer":"当然ながら今回、その旨、返却いただいた方につきましては、こちらの計画につきましても、ご意見を伺いたいということは予定しておりますので、そのように進めてまいります。","voiceIndex":26,"id":"exchange-008"},{"speaker":"鈴木委員","kind":"確認","question":"分かりました。障害者団体のヒアリングなのですけれど、これは前回もかなり、１２団体を対象にしてヒアリングをしていただいて、７団体だけではなくて区内の障害者団体は全てヒアリングということで、していただくということで確認させていただいていいか、その点について伺いたいと思います。この事業者が、この項目とかまで含めて、事業者も含めて検討されたのか、そこら辺のところも教えてください。","respondent":"佐藤障害者施策推進課長","answer":"団体ヒアリングのほうですけれども、委員おっしゃったとおり、７団体以外のところにつきましても、今回実施、前回と同じ数程度の団体ヒアリングを予定しています。対象につきましては、今、確認中ですので、そういった形で実施をする予定です。","voiceIndex":28,"id":"exchange-009"},{"speaker":"吉田委員","kind":"質問・要望","question":"私から伺いたいのは、まず最初に、今の障害者団体ヒアリングというのを鈴木委員がおっしゃいましたけれど、７団体以外もヒアリングしているということなのですが、前回の実績でいうと何団体にヒアリングされたのか伺いたいと思います。それが次の品川区の障害者施策を組み立てるのに非常に役に立つのではないかなと思うのですけれど、その辺の設問はどこにあるのか教えていただきたいと思います。","respondent":"佐藤障害者施策推進課長","answer":"前回の団体ヒアリングの対象の団体数ということですけれども、前回、１２団体を対象として調査を実施しています。","voiceIndex":31,"id":"exchange-010"},{"speaker":"吉田委員","kind":"質問","question":"その当事者の方、またご家族の方にとっては非常に重要な調査になりますので、その時点において、きちんとした計画につながるようなアンケート、それを取るためのご協力はもう少し仰いでもいいのではないかなと思うのですが、その辺についてはいかがでしょうか。","respondent":"佐藤障害者施策推進課長","answer":"今の計画に対する不満ですとかといったところの具体的な設問という形で、今回設定するというのはなかなか難しいかもしれませんが、そういった部分につきまして、いま一度、対応につきましては区のほうで確認いたしまして。","voiceIndex":33,"id":"exchange-011"},{"speaker":"吉田委員","kind":"質問","question":"そういうような話合いの場とか、７団体だけに限るのがいいかどうか分かりませんが、そういう方たちに、まず、今後こういう計画をつくるに当たってこういう設問を考えているのだけれども、というような説明の機会というのは持たれたのでしょうか。","respondent":"佐藤障害者施策推進課長","answer":"今回調査の内容のところですけれども、こちらも前回調査を行いまして、その結果報告、それからそれを踏まえて、今回の計画の策定のための委員会等も実施させていただいて今回計画をつくっているという部分におきましては、その策定の委員会であったりですとか、また。","voiceIndex":35,"id":"exchange-012"},{"speaker":"吉田委員","kind":"質問・要望","question":"やはりいろいろな施策は、大きな福祉計画の次に実行計画というものがつくられる。それで、品川区、実行計画ないよねというのは複数ご意見を伺うところなので、その次の障害児者の福祉計画は当然つくられるべきですが、その後の実行計画をぜひつくる方向で、それが可能になるようなアンケートにしていただきたいなと思うのですけれど、実行計画の作成についてはどのようにお考えか伺いたいと思います。","respondent":"佐藤障害者施策推進課長","answer":"そこに合わせて様々な施策、展開していますので、個別のところについて、細かい計画というところで外部にご提示するような計画というところでは、全て網羅してつくっているものではございませんけれども、必要な部分については。","voiceIndex":37,"id":"exchange-013"},{"speaker":"吉田委員","kind":"質問・要望","question":"こういうところに出てこないのですかね、個別にお話しすると、品川区は実行計画つくらないよねというのがいろいろ出てくるのですけれども、やはりその辺も踏まえた事業者によるヒアリングのときにも、その辺は少し促すようなヒアリングの仕方も中にはあってもいいのかなと思います。その点についても検討していただきたいと思うのですけれど、以上、いかがでしょうか。","respondent":"佐藤障害者施策推進課長","answer":"一方で、そちらのみにならないようなというようなところも懸念されるところではありますので、設問の記述等につきましては、こちらのほうでも再度確認をさせていただいて、今申し上げたようなところが網羅できるといいますか、利用者の意見をきちんと伺いつつ。","voiceIndex":39,"id":"exchange-014"},{"speaker":"吉田委員","kind":"質問・要望","question":"分かりました。その中でぜひ、区としては、やはり実行計画をいろいろなところで示す中で、次は品川区はこの施策を考えているのだということをみんなで理解することにもなりますので、ぜひその辺は検討していただくことを強く求めておきたいと思います。品川区、どれだけ今まで意見聞いてこなかったのだと率直に思いました、というご意見を伺いました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":41,"id":"exchange-015"},{"speaker":"やなぎさわ委員","kind":"質問","question":"回答率、有効回収率についてなのですけれども、事業所がやはり前回は３４.５％ということで、実際は４８事業所しか回答いただけてないので、これは正確な実態を把握するのには少し物足りないかなと思うところで、今回、１６０事業所で少し対象事業者数増えてはいるのですけれど、やはり回答率を上げていきたいというところで、前回のときに区民委員からも、未提出というか。","respondent":"佐藤障害者施策推進課長","answer":"特に事業所アンケートの回収の部分につきましてですけれども、まず、前回の、答えていただいたところの運営主体等につきましても分析はしているところでございまして、例えば、属性として、社会福祉法人ですとかそういったところでないところとか。","voiceIndex":43,"id":"exchange-016"},{"speaker":"やなぎさわ委員","kind":"質問","question":"ちなみになのですけれど、これ事業者はアンケートの際に、その回答欄に事業所名を記入などをするようになっているのでしょうか、お伺いします。","respondent":"佐藤障害者施策推進課長","answer":"今のご質問ですけれども、事業所の概要についてということで、こちらは事業所アンケートですので、ページが後のほうですが、１ページ目のところに事業所名、それから所在地等ご記入をいただくようになっているものです。","voiceIndex":45,"id":"exchange-017"},{"speaker":"やなぎさわ委員","kind":"質問","question":"単純にやはり事業所、本当に忙しくて手が回らないというところも、私も介護施設ですが経験ありますけれども、というのもありますし、やはり何か事業所名を書くということに対して、少しやはり、本音を書きづらいというところがもしかしたら、回収率を下げている原因になっているかもしれないなとは思うのですが、ここはいかがでしょう。","respondent":"佐藤障害者施策推進課長","answer":"こちら、今のご質問ですけれども、事業所名をご記入いただくところが、答えの部分について障害というか、答えにくさを出しているというようなところは、今回出している設問の内容から踏まえても、そこが大きな原因というふうには捉えているものではございませんで。","voiceIndex":47,"id":"exchange-018"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"福祉施設、サービス事業者に対しての設問のところでいうと、例えば、サイドブックス上だと５６ページの経営状況というところの問６－２のところで、事業所の収支見込みが赤字になった理由というところで、例えばここに、４番職員人件費の高騰とか、２番報酬改定の影響というのは書いてあるのですけれど、例えば、人手不足とか人件費高騰などの人員上の問題とか、いわゆる人手に関わるような。","respondent":"佐藤障害者施策推進課長","answer":"個別の、今おっしゃっていただいたような問題につきましては、当然状況をお伺いするというのは必要で、重要なことだというところはありますけれども、一方で状況をお伺いするというところで、それからお困り事というようなことを伺うようなところにはなってありますので。","voiceIndex":49,"id":"exchange-019"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"これは要望でとどめておきますのでお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":51,"id":"exchange-020"},{"speaker":"鈴木委員","kind":"質問・要望","question":"今回の調査で、３年前の調査と変更した点というのがどんな点があるのかということを教えていただきたいと思います。それに加えて、地域生活支援事業のみを使われている方というのは受給者証は必要ないと思うのですけれど、そういう地域生活支援事業のサービスを使われている方も全部含まれるということで考えていいのか、そこのところの確認をもう一回お願いしたいと思います。","respondent":"佐藤障害者施策推進課長","answer":"そういった策定委員会等を踏まえて、基礎調査をといったところで、調査の内容についても策定委員会等で検討して実施したほうが、というふうなご意見ではありますが、そのあたりは、次回以降検討はさせていただきたいと思いますけれども、今現在、先ほど申し上げたとおり。","voiceIndex":53,"id":"exchange-021"},{"speaker":"鈴木委員","kind":"質問・要望","question":"この項目については推進委員会で検討されたということなのですかという、その点確認させていただきたいというのと、あともう一つ、全件調査というところでは、では、受給者証が発行されている人の人数というだけではなくて、受給者証が発行されていないけれども、地域生活支援事業のみを使われている方とかも全部含まれるということで考えていいのかというものの確認を改めてお願いしたいと思います。","respondent":"佐藤障害者施策推進課長","answer":"対象者につきましては、委員がおっしゃっているところの部分が、定義が……、こちら、今のご質問は、障害福祉サービス利用者等の中に地域生活支援事業が入っているかどうかというところですか。","voiceIndex":55,"id":"exchange-022"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そういうところでは、そういうものの切実な思いがこのアンケートの中でも見えるような形になってくるというのが本当に大事なのではないかなと思いますので、このアンケートを団体の皆さんにも見ていただいて、よりよいものにしていくということというのはすごく大事なのではないかなと思いますし、できればその策定委員会で、その後計画をつくっていくわけですから。","respondent":"佐藤障害者施策推進課長、松山障害者支援課長","answer":"その中で質問項目、今虐待というお話もございましたが、そういったところも踏まえて、現状、障害者施策の課題等につきまして、どの部分を盛り込んでいくかというところも、次回以降踏まえて、策定の調査の実施の流れにつきまして、再度。それについて、恐らく３年前は、児童相談所が区に設置されていなかったものですから、施設入所のお子さんに対して給付というのが、区で管理する対象のほうにならなかったのですが、品川区児童相談所が設置されたことに伴いまして。","voiceIndex":60,"id":"exchange-023"},{"speaker":"鈴木委員","kind":"提案","question":"調査項目、本当にこの名豊の会社も、そういういろいろな福祉のところも、都内でもいろいろとやっているというところは、ホームページで確認もさせていただきましたけれども、そういうところでの提案ということですが、品川区は品川区独自の実態というのがありますので、そういうところも踏まえたアンケートになるように、ぜひとも、アンケート項目の中身を検討できるという仕組み。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":63,"id":"exchange-024"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7139#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":28574,"voices":72}}]);
